# Load the separate orientation module robustly. New adaptations should use
# rotation_correction.py. Older builds used derotation*.py filenames, which
# remain available as compatibility fallbacks.

ORIENTATION_MODULE_WARNING = ""

def _load_orientation_function():
    try:
        base_dir = os.path.dirname(os.path.abspath(__file__))
    except NameError:
        base_dir = os.getcwd()

    # Prefer the stable, script-neutral public filename. Retain historical
    # development filenames only as compatibility fallbacks.
    candidates = [
        os.path.join(base_dir, "rotation_correction.py"),
        os.path.join(base_dir, "derotation_v23_EDM_SINGLE_STAVE.py"),
        os.path.join(base_dir, "derotation_v22_I_D_SIDEWAYS_DIAGNOSTICS.py"),
        os.path.join(base_dir, "derotation_v21_P_STAVES_O_ROLLBACK.py"),
        os.path.join(base_dir, "derotation_v20_O_P_STAVE_FALLBACKS.py"),
        os.path.join(base_dir, "derotation_v19_K_CURVED_PERPENDICULAR.py"),
    ]
    candidates.extend(sorted(
        glob.glob(os.path.join(base_dir, "derotation*.py")),
        key=lambda p: os.path.getmtime(p),
        reverse=True
    ))
    candidates.extend([
        os.path.join(base_dir, "derotation.py"),
        os.path.join(base_dir, "derotation_v13_O_STRUCTURAL_CONSENSUS.py"),
        os.path.join(base_dir, "derotation_v12_PRINCIPAL_STAVE_DIAGNOSTIC.py"),
    ])

    seen = set()
    errors = []
    for candidate in candidates:
        candidate = os.path.abspath(candidate)
        if candidate in seen or not os.path.isfile(candidate):
            continue
        seen.add(candidate)
        try:
            spec = importlib.util.spec_from_file_location(
                "_derotation_runtime", candidate
            )
            if spec is None or spec.loader is None:
                continue
            module = importlib.util.module_from_spec(spec)
            spec.loader.exec_module(module)
            func = getattr(module, "align_unit", None)
            if callable(func):
                return func, "", candidate, module
        except Exception as exc:
            errors.append(f"{os.path.basename(candidate)}: {exc}")

    def identity_align(unit):
        copied = dict(unit)
        copied["strokes"] = [
            [tuple(point) for point in stroke]
            for stroke in unit.get("strokes", [])
        ]
        copied["alignment_rule"] = "orientation module unavailable"
        copied["alignment_target"] = "none"
        copied["alignment_angle_deg"] = 0.0
        copied["alignment_applied"] = False
        copied["alignment_warning"] = "Orientation module could not be loaded"
        return copied

    detail = "; ".join(errors) if errors else "No orientation module file found"
    return identity_align, detail, "", None

align_rune_unit, ORIENTATION_MODULE_WARNING, ORIENTATION_MODULE_PATH, ORIENTATION_MODULE = (
    _load_orientation_function()
)

