    def _set_window_icon(self):
        """Use the embedded multi-resolution Carve ICO as the application icon."""
        self.app_icon = None
        self.app_icon_path = ""
        try:
            icon_bytes = base64.b64decode(APP_ICON_ICO_BASE64)
            if os.name == "nt":
                # Tk's Windows iconbitmap interface requires a real path. Keep
                # the temporary file for the lifetime of the application.
                handle = tempfile.NamedTemporaryFile(
                    prefix="carve_", suffix=".ico", delete=False
                )
                try:
                    handle.write(icon_bytes)
                finally:
                    handle.close()
                self.app_icon_path = handle.name
                self.root.iconbitmap(default=self.app_icon_path)
            else:
                # On non-Windows systems, use a Tk image made from the same ICO.
                with Image.open(io.BytesIO(icon_bytes)) as icon_image:
                    icon_image.seek(0)
                    icon_image = icon_image.convert("RGBA")
                    self.app_icon = ImageTk.PhotoImage(icon_image)
                self.root.iconphoto(True, self.app_icon)
        except Exception:
            # Icon failure must never prevent Carve from starting.
            self.app_icon = None
            self.app_icon_path = ""

    def toggle_saved_pane(self):
        if not self._context_change_allowed():
            return

        # Pane switching is purely navigational. Preserve the exact active sign
        # and synchronize the newly visible pane to that sign.
        active_sign_id = self._preserved_sign_id()

        if self.saved_pane_mode == "signs":
            self.saved_pane_mode = "inscriptions"
            self.saved_sign_tree_frame.pack_forget()
            self.saved_sign_buttons.pack_forget()
            self.inscription_tree_frame.pack(
                fill="both", expand=True, padx=6, pady=6
            )
            self.saved_pane_title.configure(text="Saved inscriptions")
            self.saved_pane_toggle.configure(text="Show signs")

            # Rebuilding/selecting the inscription tree may queue one or more
            # <<TreeviewSelect>> events. Suppress their normal "open" action:
            # this toggle must never substitute the inscription's first sign.
            token = self._begin_selection_suppression(inscriptions=True)
            # Both trees are kept current by refresh_saved_panes(); toggling is
            # therefore a cheap visibility change rather than an O(n) rebuild.
            if active_sign_id:
                self._select_saved_item_for_sign(active_sign_id)
            self._end_selection_suppression(token, inscriptions=True)
        else:
            self.saved_pane_mode = "signs"
            self.inscription_tree_frame.pack_forget()
            self.saved_sign_buttons.pack_forget()
            self.saved_sign_tree_frame.pack(fill="both", expand=True, padx=6, pady=6)
            self.saved_pane_title.configure(text="Saved signs")
            self.saved_pane_toggle.configure(text="Show inscriptions")

            if active_sign_id and active_sign_id in self.tree.get_children(""):
                self.tree.selection_set(active_sign_id)
                self.tree.focus(active_sign_id)
                self._scroll_saved_sign_near_top(active_sign_id)


    def refresh_saved_panes(self):
        self._refresh_object_filter_menu()
        self.refresh_sign_table()
        self.refresh_inscription_table()

    def inscription_summaries(self):
        grouped = {}
        for sid, rows in self.group_rows_by_sign().items():
            if not rows:
                continue
            first = rows[0]
            key = (
                first.get("location",""),
                first.get("object_type",""),
                first.get("object_number","")
            )
            item = grouped.setdefault(key, {
                "location": key[0],
                "object_type": key[1],
                "object_number": key[2],
                "date_start": first.get("date_start",""),
                "date_end": first.get("date_end",""),
                "sign_ids": [],
                "image": first.get("image","")
            })
            item["sign_ids"].append(sid)
        return list(grouped.values())

    def sort_inscription_table_by(self, column):
        if self.inscription_sort_column == column:
            self.inscription_sort_reverse = not self.inscription_sort_reverse
        else:
            self.inscription_sort_column = column
            self.inscription_sort_reverse = False
        self.refresh_inscription_table()

    def _inscription_sort_key(self, row):
        col = self.inscription_sort_column
        mapping = {
            "object": "object_type", "no": "object_number",
            "date_start": "date_start", "date_end": "date_end",
            "location": "location"
        }
        key = mapping.get(col, col)
        val = row.get(key, "")
        if col in {"date_start", "date_end"}:
            parsed = self._parse_period_year(val)
            primary = parsed if parsed is not None else float("inf")
        else:
            primary = self._unicode_key(val)
        return (primary, self._unicode_key(row.get("location", "")), self._unicode_key(row.get("object_type", "")), self._unicode_key(row.get("object_number", "")))

    def refresh_inscription_table(self):
        if not hasattr(self, "inscription_tree"):
            return
        current = self.inscription_tree.selection()
        current = current[0] if current else ""
        for item in self.inscription_tree.get_children():
            self.inscription_tree.delete(item)

        f = self._unicode_key(self.filter_text.get().strip())
        summaries = sorted(
            self.inscription_summaries(),
            key=self._inscription_sort_key,
            reverse=self.inscription_sort_reverse
        )
        for index, row in enumerate(summaries):
            textblob = self._unicode_key(
                " ".join(str(v) for v in row.values())
            )
            if f and f not in textblob:
                continue
            iid = f"inscription:{index}"
            self.inscription_tree.insert(
                "", "end", iid=iid,
                values=(
                    row["location"], row["object_type"],
                    row["object_number"], row["date_start"],
                    row["date_end"]
                )
            )
            self.inscription_tree.set(iid, "location", row["location"])
            self.inscription_tree.item(iid, tags=(",".join(row["sign_ids"]),))
        if current and current in self.inscription_tree.get_children():
            self.inscription_tree.selection_set(current)

    def _selected_inscription_summary(self):
        selection = self.inscription_tree.selection()
        if not selection:
            return None
        iid = selection[0]
        values = self.inscription_tree.item(iid, "values")
        if not values:
            return None
        for summary in self.inscription_summaries():
            if (
                str(summary["location"]) == str(values[0])
                and str(summary["object_type"]) == str(values[1])
                and str(summary["object_number"]) == str(values[2])
            ):
                return summary
        return None

    def on_inscription_tree_select(self, event=None):
        # The inscription Treeview remains instantiated while Saved signs are
        # visible.  Tk can deliver a queued selection event from that hidden
        # tree after a mode switch; it must never reopen its remembered sign.
        if (
            self.current_view != "entry"
            or self.saved_pane_mode != "inscriptions"
        ):
            return
        if self.suppress_inscription_select_callback:
            # Programmatic selection is navigation only: keep the visible blue
            # highlight, but do not open the inscription or replace the active sign.
            return
        if not self._context_change_allowed():
            return
        summary = self._selected_inscription_summary()
        if not summary:
            return
        self.updating_fields = True
        try:
            self.ins.set(summary["location"])
            self.object_type.set(summary["object_type"])
            self.object_number.set(summary["object_number"])
            self.date_start.set(summary["date_start"])
            self.date_end.set(summary["date_end"])
        finally:
            self.updating_fields = False
        self.open_selected_inscription()

    def open_selected_inscription(self):
        if not self._context_change_allowed():
            return
        summary = self._selected_inscription_summary()
        if not summary or not summary["sign_ids"]:
            return
        sign_ids = summary["sign_ids"]
        key = (
            summary.get("location", ""),
            summary.get("object_type", ""),
            summary.get("object_number", ""),
        )
        sid = self.inscription_active_sign_ids.get(key)
        if sid not in sign_ids:
            sid = sign_ids[0]
        if sid in self.tree.get_children(""):
            self._set_active_sign_id(sid)
            self._remember_active_sign(sid)
            self.tree.selection_set(sid)
            self.tree.focus(sid)
            self._scroll_saved_sign_near_top(sid)
            self.show_selected_sign_data()

    def focus_is_text_input(self):
        widget = self.root.focus_get()
        return isinstance(widget, (tk.Entry, ttk.Entry, ttk.Combobox, tk.Text))


    def handle_return_shortcut(self, event=None):
        if self.focus_is_text_input():
            return None
        if self.current_view != "entry":
            return "break"
        self.finish_sign()
        return "break"

    def handle_space_shortcut(self, event=None):
        if self.focus_is_text_input():
            return None
        if self.current_view != "entry":
            return "break"
        self.finish_stroke()
        return "break"

    def handle_undo_shortcut(self, event=None):
        if self.focus_is_text_input():
            return None
        if self.current_view != "entry":
            return "break"
        self.undo_point()
        return "break"

    def handle_escape_shortcut(self, event=None):
        if self.focus_is_text_input():
            return None
        if self.current_view != "entry":
            return "break"
        self.cancel_current_stroke()
        return "break"

    def handle_delete_shortcut(self, event=None):
        # Delete a sign only when the Saved signs table itself has keyboard focus.
        # In text fields, Delete must retain its ordinary editing behaviour.
        if self.focus_is_text_input():
            return None
        if self.root.focus_get() is self.tree:
            self.delete_selected_sign()
            return "break"
        return None

    def on_graphemes_changed(self, *args):
        new = self.graphemes.get()
        old = getattr(self, "last_graphemes_value", "")
        # Auto-copy unless Component has been manually changed for a bindrune.
        if self.component.get() in ("", old):
            self.component.set(self._primary_grapheme(new))
        self.last_graphemes_value = new

    def toggle_transcriptions(self):
        visible = not self.show_annotations.get()
        self.show_annotations.set(visible)
        self.annotation_toggle_button.configure(
            text="Hide annotations" if visible else "Show annotations"
        )
        self.draw(refresh_table=False)

    def _sync_app_state_from_view(self):
        """Reflect the current non-editing view in the central app state."""
        if self.app_state in (
            self.APP_STATE_DRAWING,
            self.APP_STATE_EDITING,
        ):
            return
        self.app_state = (
            self.APP_STATE_ENTRY
            if self.current_view == "entry"
            else self.APP_STATE_ANALYSIS
        )

    def _context_change_allowed(self):
        """Return False while an unfinished sign is being drawn or edited.

        Widget disabling is the visible protection. This guard is the logical
        backstop for callbacks triggered by keyboard events, delayed jobs, or
        programmatic calls.
        """
        return self.app_state not in (
            self.APP_STATE_DRAWING,
            self.APP_STATE_EDITING,
        )

    def _is_editing(self):
        """Return True when the application is in editing mode."""
        return self.app_state == self.APP_STATE_EDITING

    def _set_editing_controls(self, enabled):
        """Enable or disable controls that can change editing context.

        Save and Cancel remain available during editing. Navigation, project,
        analysis, export, and saved-item controls are disabled until the edit
        is saved or cancelled.
        """
        active = not enabled

        normal_buttons = [
            self.toolbar_buttons.get("edit"),
            self.toolbar_buttons.get("delete"),
            self.file_menu_button,
            self.mode_menu_button,
            self.save_image_menu_button,
            self.go_to_button,
            self.saved_pane_toggle,
        ]
        edit_buttons = [
            self.toolbar_buttons.get("finish_sign"),
        ]

        for button in normal_buttons:
            if button is not None:
                button.state(["disabled"] if active else ["!disabled"])
        for button in edit_buttons:
            if button is not None:
                button.state(["!disabled"] if active else ["disabled"])

        # Both saved-item panes are locked, including the currently hidden one,
        # so switching panes after editing cannot expose an incorrectly active
        # tree.
        self.tree.state(["disabled"] if active else ["!disabled"])
        if hasattr(self, "inscription_tree"):
            self.inscription_tree.state(
                ["disabled"] if active else ["!disabled"]
            )

        self._update_save_image_menu_state()
        self.update_metadata_button_visibility()
        self._update_contextual_toolbar_state()

    def _update_contextual_toolbar_state(self):
        """Enable editing actions only when their prerequisites exist."""
        buttons = getattr(self, "toolbar_buttons", {})
        if not buttons:
            return

        has_image = self.image is not None
        image_name = os.path.basename(self.path) if self.path else ""
        image_rows = [
            row for row in self.rows
            if image_name and row.get("image", "") == image_name
        ]
        active_id = getattr(self, "active_sign_id", None)
        has_selected = bool(
            has_image
            and active_id
            and any(row.get("sign_id") == active_id for row in image_rows)
        )
        has_annotations = bool(
            image_rows or self.current_points or self.current_strokes
        )
        editing = self._is_editing()

        enabled = {
            "edit": has_selected and not editing,
            "delete": has_selected and not editing,
            "zoom_sign": has_selected and not editing,
            "annotations": has_image and has_annotations,
            "undo_point": has_image and bool(self.current_points),
            "undo_stroke": has_image and bool(self.current_strokes),
            "finish_stroke": has_image and len(self.current_points) >= 2,
            "finish_sign": has_image and (
                editing or bool(self.current_points) or bool(self.current_strokes)
            ),
            "rotate_left": has_image,
            "rotate_right": has_image,
            "rotation_reset": has_image and abs(float(self.view_rotation_deg or 0.0)) > 1e-9,
        }
        for key, can_use in enabled.items():
            button = buttons.get(key)
            if button is not None:
                button.state(["!disabled"] if can_use else ["disabled"])

    def _is_drawing_new_sign(self):
        """Return True while an unsaved new sign is being drawn."""
        return self.app_state == self.APP_STATE_DRAWING

    def _enter_drawing_mode(self):
        """Lock context as soon as the first point of a new sign is added."""
        if self._is_drawing_new_sign():
            return
        self.app_state = self.APP_STATE_DRAWING
        self._set_editing_controls(False)
        self.status.set(
            "Drawing new sign. Finish the sign or undo all strokes before "
            "changing images, projects, saved signs, or analysis views."
        )

    def _leave_drawing_mode(self):
        """Release the new-sign context lock when its buffer is empty or saved."""
        if not self._is_drawing_new_sign():
            return
        self.app_state = (
            self.APP_STATE_ENTRY
            if self.current_view == "entry"
            else self.APP_STATE_ANALYSIS
        )
        self._set_editing_controls(True)

    def _release_drawing_lock_if_empty(self):
        """Unlock the interface after the complete new-sign buffer is cleared."""
        if (
            self._is_drawing_new_sign()
            and not self.current_points
            and not self.current_strokes
        ):
            self._leave_drawing_mode()

    def _enter_edit_mode(self):
        """Enter the central editing state and apply edit controls."""
        self.app_state = self.APP_STATE_EDITING
        self._set_editing_controls(False)
        self.status.set(
            "Editing sign. Finish sign before changing "
            "images or analysis views."
        )

    def _leave_edit_mode(self):
        """Leave editing and derive entry/analysis state from the active view."""
        self.app_state = (
            self.APP_STATE_ENTRY
            if self.current_view == "entry"
            else self.APP_STATE_ANALYSIS
        )
        self._set_editing_controls(True)

    def stored_metadata_for_current_target(self):
        sid = self.selected_sign_id()
        rows = self.group_rows_by_sign().get(sid, []) if sid else []
        if not rows and self.path:
            image_name = os.path.basename(self.path)
            rows = [r for r in self.rows if r.get("image", "") == image_name]
        return rows[0] if rows else None

    def update_metadata_button_visibility(self):
        if not hasattr(self, "apply_metadata_button"):
            return
        if self._is_editing():
            self.apply_metadata_button.grid_remove()
            return
        stored = self.stored_metadata_for_current_target()
        if not stored:
            self.apply_metadata_button.grid_remove()
            return
        current = (
            self.ins.get().strip(),
            self.fmt_coord(self.latitude.get()),
            self.fmt_coord(self.longitude.get()),
            self.object_type.get().strip(),
            self.object_number.get().strip(),
            self.date_start.get().strip(),
            self.date_end.get().strip(),
        )
        previous = (
            stored.get("location", ""),
            stored.get("latitude", ""),
            stored.get("longitude", ""),
            stored.get("object_type", ""),
            stored.get("object_number", ""),
            stored.get("date_start", ""),
            stored.get("date_end", ""),
        )
        if current != previous:
            self.apply_metadata_button.grid()
        else:
            self.apply_metadata_button.grid_remove()

    def set_group_enabled(self, parent, enabled):
        """Enable/disable interactive ttk controls recursively without changing layout."""
        for child in parent.winfo_children():
            if child.winfo_children():
                self.set_group_enabled(child, enabled)
            if isinstance(child, (ttk.Button, ttk.Entry, ttk.Checkbutton, ttk.Combobox)):
                if enabled:
                    if child is getattr(self, "direction_combobox", None):
                        child.configure(state="readonly")
                    else:
                        child.configure(state="normal")
                else:
                    child.configure(state="disabled")

    def focus_normalized_on_selected(self):
        """Center the selected sign in the normalized viewport as closely as possible."""
        if self.current_view != "normalized":
            return
        sign_id = self.selected_sign_id()
        if not sign_id:
            return

        canvas = self.normalized_canvas
        canvas.update_idletasks()
        bbox = getattr(self, "normalized_sign_boxes", {}).get(sign_id)
        if bbox is None:
            bbox = canvas.bbox(f"signbox:{sign_id}")
        if not bbox:
            self.status.set(
                "Selected sign is not visible in the current Sign inventory."
            )
            return

        region = canvas.cget("scrollregion")
        try:
            sx1, sy1, sx2, sy2 = map(float, region.split())
        except Exception:
            return

        vw = max(canvas.winfo_width(), 1)
        vh = max(canvas.winfo_height(), 1)
        rw = max(sx2 - sx1, 1)
        rh = max(sy2 - sy1, 1)
        visible_left = canvas.canvasx(0)
        visible_top = canvas.canvasy(0)
        visible_right = canvas.canvasx(vw)
        visible_bottom = canvas.canvasy(vh)
        pad = 55
        target_x = visible_left
        if self.normalized_wrap_to_screen.get():
            target_x = sx1
        elif bbox[0] - pad < visible_left:
            target_x = bbox[0] - pad
        elif bbox[2] + pad > visible_right:
            target_x = bbox[2] + pad - vw

        target_y = visible_top
        if bbox[1] - pad < visible_top:
            target_y = bbox[1] - pad
        elif bbox[3] + pad > visible_bottom:
            target_y = bbox[3] + pad - vh

        canvas.xview_moveto(max(0.0, min(1.0, (target_x - sx1) / rw)))
        canvas.yview_moveto(max(0.0, min(1.0, (target_y - sy1) / rh)))
        canvas.update_idletasks()


    def on_normalized_canvas_click(self, event):
        """Select the clicked normalized sign in the Saved signs pane."""
        canvas = self.normalized_canvas
        x = canvas.canvasx(event.x)
        y = canvas.canvasy(event.y)
        items = canvas.find_overlapping(x, y, x, y)

        sign_id = None
        for item in reversed(items):
            tags = canvas.gettags(item)
            for tag in tags:
                if tag.startswith("signid:"):
                    sign_id = tag.split(":", 1)[1]
                    break
            if sign_id:
                break

        if not sign_id:
            return

        self.normalized_click_selection = True
        try:
            if self._toggle_saved_item_for_sign(sign_id):
                self._sync_analysis_grapheme_from_sign(sign_id)
                self.root.after_idle(self.show_selected_sign_data)
        finally:
            # Clear after pending Treeview selection callbacks have run.
            self.root.after_idle(lambda: setattr(self, "normalized_click_selection", False))

    def _refresh_status_line(self):
        if not hasattr(self, "status_line"):
            return
        status = self.status.get().strip()
        image = self.current_image_label.get().strip()
        if image and image != "Current image: —":
            self.status_line.set(f"{status} · {image}")
        else:
            self.status_line.set(status)

    def _figure_text_scale(self):
        try:
            return max(
                0.5,
                (float(
                    self.figure_text_percent.get()
                    .strip().rstrip("%")
                ) + 25.0) / 100.0
            )
        except Exception:
            return 1.25

    def _figure_symbol_scale(self):
        """Scale rune symbols with the shared Figure scale control.

        The displayed 100% is the historical 125% setting, so it maps to
        the previous symbol size (factor 1.0).
        """
        return self._figure_text_scale() / 1.25

    def _figure_font(self, role="small", bold=False):
        base = {
            "small": 7,
            "normal": 8,
            "axis": 9,
            "title": 10,
        }.get(role, 7)
        size = max(6, round(base * self._figure_text_scale()))
        return ("Arial", size, "bold") if bold else ("Arial", size)

    def _legend_layout(self, labels, available_height):
        """Shared compact legend geometry for both map modes."""
        labels = list(labels)
        font = tkfont.Font(
            root=self.root,
            font=self._figure_font("small")
        )
        line_height = max(
            13,
            round(font.metrics("linespace") + 3)
        )
        rows_per_column = max(
            1, int(max(40, available_height) // line_height)
        )
        columns = max(
            1, math.ceil(len(labels) / rows_per_column)
        )
        widths = []
        for column in range(columns):
            first = column * rows_per_column
            last = min(len(labels), first + rows_per_column)
            measured = [
                font.measure(f"{index + 1}. {labels[index]}")
                for index in range(first, last)
            ]
            widths.append(max(74, max(measured or [58]) + 12))
        return {
            "gap": 8,
            "padding": 6,
            "line_height": line_height,
            "rows_per_column": rows_per_column,
            "column_widths": widths,
            "width": sum(widths) + 12,
        }

    def _current_figure_canvas(self):
        canvases = {
            "entry": self.c,
            "normalized": self.normalized_canvas,
            "network": self.network_canvas,
            "cluster": self.cluster_canvas,
            "pairwise": self.pairwise_canvas,
            "map": self.map_canvas,
            "time_longitude": self.time_longitude_canvas,
        }
        return canvases.get(self.current_view)

    def _refresh_current_figure(self):
        """Explicitly rebuild the current figure when requested by UI logic."""
        refreshers = {
            "entry": lambda: self.draw(refresh_table=False),
            "normalized": self.render_normalized_comparison,
            "network": self.render_similarity_network,
            "cluster": self.render_cluster_view,
            "pairwise": self.render_pairwise_comparison,
            "map": self.render_rune_map,
            "time_longitude": self.render_time_longitude,
        }
        refresher = refreshers.get(self.current_view)
        if refresher:
            refresher()
        self.root.update_idletasks()

    @staticmethod
    def _clamped_percent_scale(var, low=50.0, high=200.0):
        try:
            value = int(round(float(var.get())))
        except Exception:
            value = 100
        value = max(low, min(high, value))
        try:
            var.set(value)
        except Exception:
            pass
        return value / 100.0

    def _trim_overhang_tolerance_scale(self):
        return self._clamped_percent_scale(self.analysis_trim_overhang_tolerance_pct)

    def _equalize_parallel_tolerance_scale(self):
        return self._clamped_percent_scale(self.analysis_equalize_parallel_tolerance_pct)

    def _crop_outline_tolerance_scale(self):
        return self._clamped_percent_scale(self.analysis_crop_outline_tolerance_pct)

    def _trim_max_overhang_fraction(self):
        try:
            value = int(round(float(self.analysis_trim_max_overhang_length_pct.get())))
        except Exception:
            value = 14
        value = max(1, min(40, value))
        try:
            self.analysis_trim_max_overhang_length_pct.set(value)
        except Exception:
            pass
        return value / 100.0

    def _sync_principal_stave_weights(self):
        """Push visible settings into the orientation module when supported."""
        values = {}
        for key, var in self.principal_stave_weight_vars.items():
            try:
                value = int(round(float(var.get())))
            except Exception:
                value = 0
            value = max(0, min(100, value))
            try:
                var.set(value)
            except Exception:
                pass
            values[key] = value

        setter = getattr(ORIENTATION_MODULE, "set_principal_stave_weights", None)
        if callable(setter):
            try:
                setter(**values)
            except Exception:
                pass
        return values

    def show_normalization_settings(self):
        """Open a modest settings dialog for advanced normalization controls."""
        if self.current_view != "normalized":
            self.status.set("Normalization settings are available in Sign inventory.")
            return
        existing = getattr(self, "_normalization_settings_window", None)
        if existing is not None and existing.winfo_exists():
            existing.lift()
            existing.focus_set()
            return

        win = tk.Toplevel(self.root)
        self._normalization_settings_window = win
        win.title("Normalization settings")
        win.transient(self.root)
        win.resizable(False, False)

        body = ttk.Frame(win, padding=10)
        body.pack(fill="both", expand=True)

        def add_section(row, title):
            label = ttk.Label(body, text=title, font=("Arial", 10, "bold"))
            label.grid(row=row, column=0, columnspan=3, sticky="w", pady=(8 if row else 0, 4))

        def add_spin(row, label, variable, from_, to_, increment=1, suffix="%"):
            ttk.Label(body, text=label).grid(row=row, column=0, sticky="w", padx=(0, 8), pady=2)
            spin = ttk.Spinbox(
                body, textvariable=variable, from_=from_, to=to_,
                increment=increment, width=7
            )
            spin.grid(row=row, column=1, sticky="w", pady=2)
            if suffix:
                ttk.Label(body, text=suffix).grid(row=row, column=2, sticky="w", pady=2)

        add_section(0, "Main stave identification")
        add_spin(1, "Chord weight", self.principal_stave_weight_vars["chord"], 0, 100, 1, "")
        add_spin(2, "Length weight", self.principal_stave_weight_vars["length"], 0, 100, 1, "")
        add_spin(3, "Straightness weight", self.principal_stave_weight_vars["straightness"], 0, 100, 1, "")
        add_spin(4, "Vertical extent weight", self.principal_stave_weight_vars["vertical_extent"], 0, 100, 1, "")
        add_spin(5, "Verticality weight", self.principal_stave_weight_vars["verticality"], 0, 100, 1, "")

        add_section(6, "Trim overhangs")
        add_spin(7, "Junction radius", self.analysis_junction_radius_pct, 1, 8, 1)
        add_spin(8, "Overhang tolerance", self.analysis_trim_overhang_tolerance_pct, 50, 200, 1)
        add_spin(9, "Max overhang length", self.analysis_trim_max_overhang_length_pct, 1, 40, 1)

        add_section(10, "Equalize parallel staves")
        add_spin(11, "Equalizing tolerance", self.analysis_equalize_parallel_tolerance_pct, 50, 200, 1)

        add_section(12, "Crop outline")
        add_spin(13, "Boundary tolerance", self.analysis_crop_outline_tolerance_pct, 50, 200, 1)

        buttons = ttk.Frame(body)
        buttons.grid(row=14, column=0, columnspan=3, sticky="ew", pady=(10, 0))

        def reset_defaults():
            self.normalized_show_derotation_diagnostics.set(False)
            self.principal_stave_weight_vars["chord"].set(25)
            self.principal_stave_weight_vars["length"].set(12)
            self.principal_stave_weight_vars["straightness"].set(22)
            self.principal_stave_weight_vars["vertical_extent"].set(18)
            self.principal_stave_weight_vars["verticality"].set(23)
            self.analysis_junction_radius_pct.set(3)
            self.analysis_trim_overhang_tolerance_pct.set(100)
            self.analysis_trim_max_overhang_length_pct.set(14)
            self.analysis_equalize_parallel_tolerance_pct.set(100)
            self.analysis_crop_outline_tolerance_pct.set(100)
            self._sync_principal_stave_weights()
            self.status.set("Normalization settings reset. Click Refresh to redraw.")

        def on_close():
            self._normalization_settings_window = None
            win.destroy()

        ttk.Button(buttons, text="Reset", command=reset_defaults).pack(side="left")
        ttk.Button(buttons, text="Close", command=on_close).pack(side="right")

        win.protocol("WM_DELETE_WINDOW", on_close)
        win.bind("<Escape>", lambda _event: on_close())

    def handle_orientation_diagnostics_shortcut(self, event=None):
        """Recognize Ctrl+Alt+D robustly across Tk keyboard layouts."""
        if event is None:
            return None
        key = str(getattr(event, "keysym", "") or "").lower()
        if key != "d":
            return None
        state = int(getattr(event, "state", 0) or 0)
        ctrl_down = bool(state & 0x0004)
        alt_down = bool(state & 0x0008) or bool(state & 0x0080) or bool(state & 0x20000)
        if not (ctrl_down and alt_down):
            return None
        return self.toggle_orientation_diagnostics_shortcut(event)

    def toggle_orientation_diagnostics_shortcut(self, event=None):
        """Secret Sign inventory shortcut for internal orientation diagnostics."""
        if self.current_view != "normalized":
            return None
        enabled = not bool(self.normalized_show_derotation_diagnostics.get())
        self.normalized_show_derotation_diagnostics.set(enabled)
        self.render_normalized_comparison()
        state = "shown" if enabled else "hidden"
        self.status.set(f"Orientation diagnostics {state}.")
        return "break"

    def _current_figure_name(self):
        names = {
            "entry": "sign_editing",
            "normalized": "sign_inventory",
            "network": "similarity_network",
            "cluster": "cluster_subvariants",
            "pairwise": "pairwise_comparison",
            "map": "sign_map",
            "time_longitude": "time_longitude",
        }
        return names.get(self.current_view, "rune_figure")

    def _editing_display_image(self):
        if self.image is None:
            return None
        angle = float(self.view_rotation_deg or 0.0)
        if abs(angle) < 1e-9:
            return self.image
        return self.image.rotate(
            angle, resample=Image.Resampling.BICUBIC, expand=True
        )

    def _update_view_buttons(self):
        labels = {
            "entry": "Sign editing",
            "normalized": "Sign inventory",
            "network": "Similarity network",
            "cluster": "Subclustering",
            "pairwise": "Pairwise comparison",
            "map": "Sign map",
            "time_longitude": "Time–longitude",
        }
        label = labels.get(self.current_view, "Sign editing")
        self.mode_menu_button.configure(text=f"Mode: {label}")
        self._sync_app_state_from_view()
        self._update_save_image_menu_state()
        self._update_normalization_menu_state()
        self._update_figure_scale_state()

    def _update_figure_scale_state(self):
        """Only the network, map, and time–longitude use figure scale."""
        if self.current_view in {"network", "map", "time_longitude"}:
            self.figure_scale_box.configure(state="readonly")
            self.figure_scale_label.state(["!disabled"])
        else:
            self.figure_scale_box.configure(state="disabled")
            self.figure_scale_label.state(["disabled"])

    def _update_save_image_menu_state(self):
        """Enable figure export in all supported non-editing views."""
        context_locked = self.app_state in (
            self.APP_STATE_DRAWING,
            self.APP_STATE_EDITING,
        )
        if context_locked:
            self.save_image_menu_button.state(["disabled"])
        else:
            self.save_image_menu_button.state(["!disabled"])

    def _update_normalization_menu_state(self):
        """Keep advanced normalization settings scoped to Sign inventory."""
        menu = getattr(self, "normalization_menu", None)
        index = getattr(self, "normalization_settings_menu_index", None)
        if menu is None or index is None:
            return
        state = "normal" if self.current_view == "normalized" else "disabled"
        try:
            menu.entryconfig(index, state=state)
        except Exception:
            pass

    def _analysis_view_frame(self, view_name):
        """Return the frame belonging to an analysis-mode name."""
        return {
            "normalized": self.normalized_view,
            "network": self.network_view,
            "cluster": self.cluster_view,
            "pairwise": self.pairwise_view,
            "map": self.map_view,
            "time_longitude": self.time_longitude_view,
        }.get(view_name)

    def _leave_analysis_view(self):
        frame = self._analysis_view_frame(self.current_view)
        if frame is not None:
            frame.pack_forget()

    def _set_analysis_controls(self, enabled):
        # Object and sign metadata remain visible in the right-hand pane.
        if enabled:
            if not self.editing_toolbar.winfo_manager():
                self.editing_toolbar.pack(
                    fill="x", padx=4, pady=(0,4),
                    before=self.view_container
                )
        else:
            self.editing_toolbar.pack_forget()

    def _update_metadata_editability_for_view(self, view_name=None):
        """Make metadata read-only in sign-analysis modes."""
        view_name = self.current_view if view_name is None else view_name
        editable = view_name not in {
            "normalized", "network", "cluster", "pairwise", "map",
            "time_longitude"
        }
        self.set_group_enabled(self.metadata_row, editable)
        if not editable:
            self.apply_metadata_button.grid_remove()

    def _update_analysis_metadata_and_saved_pane(self, view_name=None):
        """Lock metadata and Saved inscriptions in restricted sign-analysis modes."""
        view_name = self.current_view if view_name is None else view_name
        restricted = self._uses_restricted_saved_signs(view_name)
        pane_locked = restricted or view_name == "normalized"

        self._update_metadata_editability_for_view(view_name)

        if pane_locked:
            self._show_saved_signs_pane()
            if view_name == "normalized":
                token = self._begin_selection_suppression(saved=True)
                try:
                    self.refresh_sign_table()
                finally:
                    self._end_selection_suppression(token, saved=True)
                # Refreshing the Treeview rebuilds its rows, so explicitly
                # restore the canonical sign's viewport position.  This is
                # especially important when returning to Sign inventory from
                # an analytical canvas.
                active_sign_id = self._preserved_sign_id()
                if active_sign_id in self.tree.get_children(""):
                    self._scroll_saved_sign_near_top(active_sign_id)
            self.saved_pane_toggle.state(["disabled"])
        else:
            self.saved_pane_toggle.state(["!disabled"])
            if view_name == "entry":
                token = self._begin_selection_suppression(saved=True)
                try:
                    self.refresh_sign_table()
                finally:
                    self._end_selection_suppression(token, saved=True)

    def _show_saved_signs_pane(self):
        """Show Saved signs without changing the active sign."""
        if self.saved_pane_mode == "signs":
            return
        self.saved_pane_mode = "signs"
        self.inscription_tree_frame.pack_forget()
        self.saved_sign_buttons.pack_forget()
        self.saved_sign_tree_frame.pack(fill="both", expand=True, padx=6, pady=6)
        self.saved_pane_title.configure(text="Saved signs")
        self.saved_pane_toggle.configure(text="Show inscriptions")

    def _begin_selection_suppression(self, *, saved=False, inscriptions=False):
        """Suppress queued Treeview callbacks for one programmatic update."""
        self._selection_suppression_generation += 1
        token = self._selection_suppression_generation
        if saved:
            self.suppress_saved_tree_callback = True
        if inscriptions:
            self.suppress_inscription_select_callback = True
        return token

    def _end_selection_suppression(self, token, *, saved=False, inscriptions=False):
        """Release suppression after Tk has drained the current event cycle."""
        def release():
            if token != self._selection_suppression_generation:
                return
            # Tokens can overlap: selecting an inscription also selects its
            # hidden Saved-sign row.  The newest token therefore owns the
            # complete suppression state, not merely one flag.
            self.suppress_saved_tree_callback = False
            self.suppress_inscription_select_callback = False
        self.root.after_idle(release)


    def _show_analysis_view(
        self, view_name, grapheme_var=None, initial_message=None,
        render_on_entry=None, after_entry=None
    ):
        """Switch to an analysis frame using one consistent code path."""
        if not self._context_change_allowed():
            return False
        if self.current_view == view_name:
            self._update_view_buttons()
            return False

        active_sign_id = self._preserved_sign_id()
        previous_view = self.current_view

        if self.current_view == "entry":
            self.entry_view.pack_forget()
        else:
            self._leave_analysis_view()

        frame = self._analysis_view_frame(view_name)
        if frame is None:
            raise ValueError(f"Unknown analysis view: {view_name}")
        frame.pack(fill="both", expand=True)
        self.current_view = view_name
        self._set_analysis_controls(False)

        if (
            self._uses_restricted_saved_signs(view_name)
            and not self._uses_restricted_saved_signs(previous_view)
            and active_sign_id
        ):
            self._sync_analysis_grapheme_from_sign(active_sign_id)

        if grapheme_var is not None and not grapheme_var.get().strip():
            grapheme_var.set(self._network_grapheme_default())

        self._update_analysis_metadata_and_saved_pane(view_name)

        if self._uses_restricted_saved_signs(view_name):
            self._refresh_restricted_saved_signs()

        self._update_view_buttons()

        if render_on_entry is not None:
            render_on_entry()
        elif initial_message:
            canvas = self._current_figure_canvas()
            if canvas is not None and not canvas.find_all():
                self.status.set(initial_message)

        if after_entry is not None:
            after_entry()
        # Selection markers always follow the canonical active sign.  This
        # updates only the marker layer and does not rebuild the figure.
        self._refresh_selection_markers()
        return True


    def return_to_entry_view(self):
        if not self._context_change_allowed():
            return
        active_sign_id = self._preserved_sign_id()
        self._leave_analysis_view()
        self.entry_view.pack(fill="both", expand=True)
        self.current_view = "entry"
        self._set_analysis_controls(True)
        self._update_analysis_metadata_and_saved_pane("entry")
        if active_sign_id and active_sign_id in self.tree.get_children(""):
            self._select_saved_item_for_sign(active_sign_id)
            self.show_selected_sign_data()
            self._scroll_saved_sign_near_top(active_sign_id)
        if self._is_editing():
            self._enter_edit_mode()
        else:
            self._leave_edit_mode()
        self.draw(refresh_table=False)
        self._update_view_buttons()

    def toggle_main_view(self):
        self._show_analysis_view(
            "normalized",
            render_on_entry=self.render_normalized_comparison,
            after_entry=lambda: self.root.after_idle(
                self.focus_normalized_on_selected
            ),
        )

    def toggle_network_view(self):
        """Show Similarity Network without building until requested."""
        active_sign_id = self._preserved_sign_id()
        shown = self._show_analysis_view(
            "network",
            grapheme_var=self.network_grapheme_var,
            initial_message="Adjust the settings and click Build network.",
        )
        if self.current_view == "network":
            self._prepare_restricted_saved_pane(active_sign_id)
            self._on_analysis_colour_mode_changed()
        return shown

    def _uses_restricted_saved_signs(self, view_name=None):
        view_name = self.current_view if view_name is None else view_name
        return view_name in {"network", "cluster", "pairwise", "map", "time_longitude"}

    def _analysis_grapheme_selection(self, text=None):
        """Parse the shared Sign field.

        Examples:
            e       -> one grapheme
            e,r,t   -> three graphemes
            *       -> all graphemes

        Matching is Unicode-normalized and whitespace/duplicates are ignored.
        """
        if text is None:
            text = self.analysis_grapheme_var.get()
        raw = str(text or "").strip()
        if raw == "*":
            return None  # None means unrestricted / all signs.
        selected = set()
        for token in raw.split(","):
            token = token.strip()
            if token:
                selected.add(self._unicode_key(token))
        return selected

    def _analysis_grapheme_matches(self, grapheme, selector=None):
        """Return whether a grapheme belongs to a Sign-field selection."""
        if selector is None:
            selector = self._analysis_grapheme_selection()
        # A literal wildcard is represented by None.
        if selector is None:
            return True
        if not selector:
            return False
        return self._unicode_key(str(grapheme or "").strip()) in selector

    def _sign_grapheme_for_id(self, sign_id):
        if not sign_id:
            return ""
        rows = self.group_rows_by_sign().get(sign_id, [])
        if not rows:
            return ""
        return self._primary_grapheme(rows[0].get("graphemes", ""))

    def _sync_analysis_grapheme_from_sign(self, sign_id):
        """Update the shared analysis Sign field from a selected Saved sign.

        Return True only when the grapheme actually changes.
        """
        grapheme = self._sign_grapheme_for_id(sign_id)
        if not grapheme:
            return False

        current = self.analysis_grapheme_var.get().strip()
        current_selection = self._analysis_grapheme_selection(current)
        # Saved-sign navigation may update an ordinary single-sign selector,
        # but must never collapse an explicit multi-sign or wildcard analysis.
        if current == "*" or (
            current_selection is not None and len(current_selection) > 1
        ):
            return False
        grapheme_tokens = {
            self._unicode_key(token)
            for token in self._tokens(grapheme)
            if token
        }
        if (
            current_selection is not None
            and len(current_selection) == 1
            and grapheme_tokens
            and next(iter(current_selection)) in grapheme_tokens
        ):
            return False
        if self._unicode_key(current) != self._unicode_key(grapheme):
            self.analysis_grapheme_var.set(grapheme)
            return True
        return False

    def _filter_saved_signs_for_analysis(self):
        """Show only occurrences of the active grapheme in restricted modes."""
        if not self._uses_restricted_saved_signs():
            return

        selector_text = self.analysis_grapheme_var.get().strip()
        if not selector_text:
            return
        selector = self._analysis_grapheme_selection(selector_text)

        summaries = {
            item["sign_id"]: item
            for item in self.sign_summaries()
        }
        include_incomplete = bool(
            self.analysis_include_incomplete.get()
        )
        include_ambiguous = bool(
            self.analysis_include_ambiguous.get()
        )

        for iid in list(self.tree.get_children("")):
            summary = summaries.get(iid)
            if summary is None:
                continue

            raw_graphemes = str(summary.get("graphemes", "")).strip()
            ambiguous = self._is_ambiguous_grapheme(raw_graphemes)
            sign_g = self._unicode_key(
                self._primary_grapheme(raw_graphemes)
            )
            sign_tokens = {
                self._unicode_key(token)
                for token in self._tokens(self._primary_grapheme(raw_graphemes))
                if token
            }
            certainty = str(
                summary.get("certainty", "complete")
            ).strip().lower()

            if not (
                self._analysis_grapheme_matches(sign_g, selector)
                or (
                    selector is not None
                    and sign_tokens
                    and any(token in selector for token in sign_tokens)
                )
            ):
                self.tree.delete(iid)
                continue

            if not include_incomplete and certainty != "complete":
                self.tree.delete(iid)
                continue
            if not include_ambiguous and ambiguous:
                self.tree.delete(iid)

    def _filter_saved_signs_for_normalized(self):
        """Apply Sign inventory's incomplete-sign filter to the Saved signs pane."""
        if self.current_view != "normalized":
            return
        summaries = {
            item["sign_id"]: item
            for item in self.sign_summaries()
        }
        for iid in list(self.tree.get_children("")):
            summary = summaries.get(iid)
            if summary is None:
                continue
            certainty = str(
                summary.get("certainty", "complete")
            ).strip().lower()
            ambiguous = self._is_ambiguous_grapheme(
                summary.get("graphemes", "")
            )
            if (
                not self.normalized_include_incomplete.get()
                and certainty != "complete"
            ) or (
                not self.normalized_include_ambiguous.get()
                and ambiguous
            ):
                self.tree.delete(iid)

    def on_include_incomplete_changed(self):
        """Refresh visible signs and the Saved signs pane after incomplete toggle."""
        self.refresh_sign_table()
        if self.current_view == "normalized":
            self._filter_saved_signs_for_normalized()
            self.render_normalized_comparison()
        elif self._uses_restricted_saved_signs():
            self._refresh_restricted_saved_signs()
            self._refresh_current_figure()


    def _refresh_restricted_saved_signs(self):
        """Refresh/filter Saved signs only when the restricted dataset changed.

        Switching between analytical modes used to rebuild the entire Saved-signs
        tree every time.  The Sign selector and Include incomplete setting are
        shared across these modes, so an unchanged filtered tree can be reused.
        """
        if not self._uses_restricted_saved_signs():
            return

        key = (
            self.analysis_grapheme_var.get().strip(),
            bool(self.analysis_include_incomplete.get()),
            bool(self.analysis_include_ambiguous.get()),
        )
        if getattr(self, "_restricted_saved_pane_key", None) == key:
            return

        token = self._begin_selection_suppression(saved=True)
        try:
            self.refresh_sign_table()
            self._filter_saved_signs_for_analysis()
            self._restricted_saved_pane_key = key
            # Filtering can rebuild the visible rows after an earlier
            # selection/see() call. Restore the active row only now, when the
            # final restricted Treeview contents are in place.
            active_sign_id = self._preserved_sign_id()
            if active_sign_id in self.tree.get_children(""):
                self.tree.selection_set(active_sign_id)
                self.tree.focus(active_sign_id)
                self._scroll_saved_sign_near_top(active_sign_id)
        finally:
            # Tk may queue <<TreeviewSelect>> until after refresh_sign_table()
            # returns, so keep suppression through the current event cycle.
            self._end_selection_suppression(token, saved=True)

    def _prepare_restricted_saved_pane(self, active_sign_id=None):
        """Use a sign-only Saved pane for grapheme-based analysis modes."""
        # The shared Sign selector was established before this pane is shown.
        # Deriving it again from a bindrune row could replace a component such
        # as ``d`` with the complete bindrune label and discard Subclustering.

        self._show_saved_signs_pane()

        self.saved_pane_toggle.state(["disabled"])
        # _show_analysis_view() has already refreshed and filtered the cached
        # Saved-signs tree.  Do not rebuild it a second time merely to finish
        # the pane transition; this keeps mode switching responsive.

        if (
            active_sign_id
            and active_sign_id in self.tree.get_children("")
        ):
            token = self._begin_selection_suppression(saved=True)
            self.tree.selection_set(active_sign_id)
            self.tree.focus(active_sign_id)
            self._scroll_saved_sign_near_top(active_sign_id)
            self._end_selection_suppression(token, saved=True)
        self._refresh_selection_markers()


