    def update_current_image_label(self):
        if self.path:
            self.current_image_label.set(f"Current image: {os.path.basename(self.path)}")
        else:
            self.current_image_label.set("Current image: —")

    def object_label_from_values(self, location=None, object_type=None, object_number=None):
        location = self.ins.get().strip() if location is None else str(location).strip()
        object_type = self.object_type.get().strip() if object_type is None else str(object_type).strip()
        object_number = self.object_number.get().strip() if object_number is None else str(object_number).strip()
        return " ".join(x for x in [location, object_type, object_number] if x)

    def _plot_location_identity(self, unit, coordinate=None):
        """Stable grouping key for one plotted inscription/location occurrence."""
        location = str(unit.get("location", "")).strip()
        if not location:
            return ""
        object_type = str(unit.get("object_type", "")).strip()
        object_number = str(unit.get("object_number", "")).strip()
        parts = [location, object_type, object_number]
        if coordinate is not None:
            lon, lat = coordinate
            parts.extend([f"{lon:.6f}", f"{lat:.6f}"])
        return "\t".join(parts)

    def _site_representative_key(self, unit):
        """Group site representatives by inscription/object identity."""
        key = self._plot_location_identity(unit)
        return key or "(unknown location)"

    def _location_label_for_plot(self, unit, extended=False):
        """Visible map labels stay compact unless extended labels are requested."""
        location = str(unit.get("location", "")).strip()
        if not location:
            return ""
        if extended:
            return self.object_label_from_values(
                location,
                unit.get("object_type", ""),
                unit.get("object_number", "")
            )
        return location

    def _plot_label_entries(self, label_records, extended=False):
        """Return ordered display entries while preserving distinct plot groups."""
        entries = []
        for key, unit in label_records:
            label = self._location_label_for_plot(unit, extended=extended)
            if not label:
                continue
            entries.append((key, label))
        return entries

    def _plot_label_lookup(self, label_records, extended=False):
        return {
            key: label
            for key, label in self._plot_label_entries(
                label_records, extended=extended
            )
        }







    def apply_metadata_to_current_image(self):
        """Explicitly apply current metadata fields to all signs on the selected/current image.

        This is intentionally button-driven, not automatic. It updates only rows whose
        image filename matches the selected sign's image, or, if no sign is selected,
        the currently loaded image filename.
        """
        if self.current_points or self.current_strokes:
            if not messagebox.askyesno(
                "Apply metadata?",
                "There is an unfinished drawing. Apply metadata to the saved signs anyway?"
            ):
                return

        sid = self.selected_sign_id()
        target_image = ""
        if sid:
            rows = self.group_rows_by_sign().get(sid, [])
            if rows:
                target_image = rows[0].get("image", "")

        if not target_image and self.path:
            target_image = os.path.basename(self.path)

        if not target_image:
            self.status.set("No selected or current image to update.")
            return

        label = self.object_label_from_values()
        if not messagebox.askyesno(
            "Apply metadata to image",
            f"Apply current metadata to all saved signs attached to image:\n\n"
            f"{target_image}\n\n"
            f"New label: {label or '(empty)'}"
        ):
            return

        changed = 0
        for r in self.rows:
            if r.get("image", "") == target_image:
                r["location"] = self.ins.get().strip()
                r["latitude"] = self.fmt_coord(self.latitude.get())
                r["longitude"] = self.fmt_coord(self.longitude.get())
                r["object_type"] = self.object_type.get().strip()
                r["object_number"] = self.object_number.get().strip()
                r["date_start"] = self.date_start.get().strip()
                r["date_end"] = self.date_end.get().strip()
                changed += 1

        self.rebuild_counts()
        self.refresh_sign_table()
        self.refresh_inscription_table()
        if sid and sid in self.tree.get_children(""):
            self._set_active_sign_id(sid)
            self.tree.selection_set(sid)
        self.draw(refresh_table=False)
        self.update_metadata_button_visibility()
        self.status.set(f"Applied metadata to {changed} point rows on image {target_image}.")

    def fmt_coord(self, value):
        value = str(value).strip()
        if not value:
            return ""
        try:
            return f"{float(value):.6f}"
        except Exception:
            return value

    def _scroll_saved_sign_near_top(self, sign_id):
        """Place the active Saved-sign row a few rows below the top."""
        if not sign_id or sign_id not in self.tree.get_children(""):
            return
        self.tree.update_idletasks()
        try:
            # First guarantee that the row is visible.  Then use its actual
            # rendered position rather than guessing the Treeview's scroll
            # fraction: yview_moveto() fractions are content fractions, not
            # fractions of the maximum number of top rows.
            self.tree.see(sign_id)
            self.tree.update_idletasks()
            bbox = self.tree.bbox(sign_id)
            if not bbox or bbox[3] <= 0:
                return

            row_y, row_height = float(bbox[1]), max(1.0, float(bbox[3]))
            visible_bboxes = []
            for iid in self.tree.get_children(""):
                item_bbox = self.tree.bbox(iid)
                if item_bbox and item_bbox[3] > 0:
                    visible_bboxes.append(item_bbox)
            viewport_top = min(
                (float(item_bbox[1]) for item_bbox in visible_bboxes),
                default=row_y,
            )
            desired_y = viewport_top + 4.0 * row_height
            units = int(round((row_y - desired_y) / row_height))
            if units:
                self.tree.yview_scroll(units, "units")
        except tk.TclError:
            self.tree.see(sign_id)

    def _select_saved_item_for_sign(self, sign_id, suppress_callback=True):
        """Select a sign or its inscription in the currently visible saved pane."""
        if not sign_id:
            return False
        self._set_active_sign_id(sign_id)
        self._remember_active_sign(sign_id)

        # Keep the exact sign selected internally so analytical redraws and
        # selection highlighting continue to use the clicked sign.
        if sign_id in self.tree.get_children(""):
            if suppress_callback:
                saved_token = self._begin_selection_suppression(saved=True)
            try:
                self.tree.selection_set(sign_id)
                self.tree.focus(sign_id)
                self._scroll_saved_sign_near_top(sign_id)
            finally:
                if suppress_callback:
                    self._end_selection_suppression(saved_token, saved=True)

        if self.saved_pane_mode == "inscriptions":
            for iid in self.inscription_tree.get_children(""):
                tags = self.inscription_tree.item(iid, "tags")
                sign_ids = []
                for tag in tags:
                    sign_ids.extend(
                        part for part in str(tag).split(",") if part
                    )
                if sign_id in sign_ids:
                    inscription_token = self._begin_selection_suppression(
                        inscriptions=True
                    )
                    self.inscription_tree.selection_set(iid)
                    self.inscription_tree.focus(iid)
                    self.inscription_tree.see(iid)
                    # Keep normal inscription-opening callbacks suppressed
                    # while Tk processes this programmatic selection.
                    self._end_selection_suppression(
                        inscription_token, inscriptions=True
                    )
                    # Selection/scrolling is sufficient here. Do not update
                    # metadata or open the inscription: the clicked inventory
                    # sign remains the active analytical sign.
                    return True

        # A canvas sign can be valid even when the Saved-signs Treeview is
        # filtered to another grapheme.  Report that validity so callers still
        # refresh the canonical highlight and metadata for the clicked sign.
        return any(row.get("sign_id") == sign_id for row in self.rows)

    def _clear_saved_sign_selection(self):
        """Clear Saved-sign selection and refresh selection markers only."""
        had_selection = bool(self.tree.selection())
        if hasattr(self, "inscription_tree"):
            had_selection = had_selection or bool(
                self.inscription_tree.selection()
            )
        had_selection = had_selection or bool(
            getattr(self, "active_sign_id", None)
        )
        self.active_sign_id = None
        token = self._begin_selection_suppression(
            saved=True, inscriptions=True
        )
        try:
            selection = self.tree.selection()
            if selection:
                self.tree.selection_remove(selection)
            if hasattr(self, "inscription_tree"):
                inscription_selection = self.inscription_tree.selection()
                if inscription_selection:
                    self.inscription_tree.selection_remove(inscription_selection)
        finally:
            self._end_selection_suppression(
                token, saved=True, inscriptions=True
            )
        if had_selection:
            self._refresh_selection_markers()
        return had_selection

    def _toggle_saved_item_for_sign(self, sign_id):
        """Select a sign, or unselect it if it is already active."""
        if not sign_id:
            return False
        if self.selected_sign_id() == sign_id:
            result = self._clear_saved_sign_selection()
            return result
        selected = self._select_saved_item_for_sign(sign_id)
        if selected:
            self._refresh_selection_markers()
        return selected

    def _refresh_selection_markers(self):
        """Update visible selection markers without changing the analysis state."""
        view = self.current_view
        sign_id = getattr(self, "active_sign_id", None)
        if view == "normalized":
            self._highlight_normalized_selection(sign_id)
            if not self.normalized_click_selection:
                self.root.after_idle(self.focus_normalized_on_selected)
        elif view == "network":
            self._highlight_network_selection(sign_id)
        elif view == "cluster":
            self._highlight_cluster_selection(sign_id)
        elif view == "map":
            self._highlight_map_selection(sign_id)
        elif view == "time_longitude":
            self._highlight_time_longitude_selection(sign_id)
        elif view == "pairwise":
            self._highlight_pairwise_selection(sign_id)
        elif view == "entry":
            self.draw(refresh_table=False)

    def on_saved_sign_button_press(self, event=None):
        """Remember whether a click started on the already selected sign."""
        self._saved_sign_press_item = None
        if event is None:
            return
        try:
            iid = self.tree.identify_row(event.y)
        except Exception:
            iid = ""
        if iid and iid == self.selected_sign_id():
            self._saved_sign_press_item = iid

    def on_saved_sign_button_release(self, event=None):
        """Single-click selects; clicking the selected row again unselects it."""
        try:
            iid = self.tree.identify_row(event.y) if event is not None else ""
        except Exception:
            iid = ""
        if iid and iid == self._saved_sign_press_item:
            self._saved_sign_press_item = None
            self.root.after_idle(self._clear_saved_sign_selection)
            return "break"
        self._saved_sign_press_item = None

    def on_saved_sign_double_click(self, event=None):
        """Double-click keeps the same select/focus behavior as a single click."""
        return "break"

    def on_saved_sign_return(self, event=None):
        """Do not enter active editing from Saved signs; use Edit selected."""
        self.root.after_idle(self.show_selected_sign_data)
        if self.current_view != "entry":
            self.root.after_idle(self._refresh_selection_markers)
        return "break"

    def show_selected_sign_data(self):
        if not self._context_change_allowed():
            return
        """Show the selected saved sign's data in the main fields, also outside edit mode."""
        sid = self.selected_sign_id()
        if not sid:
            return
        rows = self.group_rows_by_sign().get(sid, [])
        if not rows:
            return

        first = rows[0]
        self.updating_fields = True
        try:
            self.ins.set(first.get("location", ""))
            self.latitude.set(first.get("latitude", ""))
            self.longitude.set(first.get("longitude", ""))
            self.object_type.set(first.get("object_type", ""))
            self.object_number.set(first.get("object_number", ""))
            self.date_start.set(first.get("date_start", ""))
            self.date_end.set(first.get("date_end", ""))
            self.direction.set(first.get("direction", "LTR"))
            self.graphemes.set(first.get("graphemes", ""))
            self.component.set(first.get("component", first.get("graphemes", "")))
            self.incomplete.set(first.get("certainty", "complete") == "incomplete")
            try:
                self.view_rotation_deg = float(
                    first.get("view_rotation_deg", "0") or 0
                )
            except (TypeError, ValueError):
                self.view_rotation_deg = 0.0
            self._rotated_image_size = None
            if hasattr(self, "rotation_status"):
                self.rotation_status.set(
                    f"Rotation: {self.view_rotation_deg:g}°"
                )
        finally:
            self.updating_fields = False
            self.metadata_dirty = False

        self._try_open_image_for_rows(rows)
        self.update_metadata_button_visibility()
        if self.current_view == "entry":
            self.draw(refresh_table=False)

    def on_tree_select(self, event=None):
        if self.suppress_saved_tree_callback:
            return
        if not self._context_change_allowed():
            return
        if self.refreshing_table:
            return

        sid = self._tree_selected_sign_id()
        sid = self._set_active_sign_id(sid)

        if self._uses_restricted_saved_signs() and sid:
            # Restricted sign-analysis modes use the Saved signs tree as a
            # navigator. Preserve native Up/Down traversal and never run an
            # analysis merely because the selection changed.
            self._sync_analysis_grapheme_from_sign(sid)
            self.root.after_idle(self.show_selected_sign_data)
            self.root.after_idle(self._refresh_selection_markers)
            return

        self.root.after_idle(self.show_selected_sign_data)
        if self.current_view != "entry":
            self.root.after_idle(self._refresh_selection_markers)

    # ---------- files ----------

    def open_image(self):
        # Recover from a stale DRAWING state when no unfinished stroke/sign
        # buffer actually exists. Navigating to a saved inscription/sign may
        # leave the application showing an image while there is no active
        # drawing to protect; in that case Open image must remain available.
        self._release_drawing_lock_if_empty()
        if not self._context_change_allowed():
            if self._is_editing():
                self.status.set("Finish the current edit before opening another image.")
            else:
                self.status.set("Finish or undo the current drawing before opening another image.")
            return
        p = filedialog.askopenfilename(filetypes=[("Images","*.jpg *.jpeg *.png *.tif *.tiff")])
        if not p:
            return

        if self.current_view != "entry":
            self.return_to_entry_view()

        # A manually opened image starts a fresh navigation context.  Clear
        # both Saved panes while their selection callbacks are suppressed;
        # otherwise refresh_sign_table() can rebuild/reselect the previously
        # active inscription and immediately reopen its old image.
        self.suppress_selection_autoload = True
        selection_token = self._begin_selection_suppression(
            saved=True, inscriptions=True
        )
        self.active_sign_id = None
        try:
            self.tree.selection_remove(self.tree.selection())
        except Exception:
            pass
        try:
            if hasattr(self, "inscription_tree"):
                self.inscription_tree.selection_remove(
                    self.inscription_tree.selection()
                )
        except Exception:
            pass

        self.path = p
        self.image = Image.open(p).convert("RGB")
        self.view_rotation_deg = 0.0
        self._rotated_image_size = None
        if hasattr(self, "rotation_status"):
            self.rotation_status.set("Rotation: 0°")

        # A manually opened image starts a fresh metadata context. Always use
        # its filename (without extension) as the Location safeguard.
        stem = os.path.splitext(os.path.basename(p))[0]
        self.updating_fields = True
        try:
            self.ins.set(stem)
            self.latitude.set("")
            self.longitude.set("")
            self.object_type.set("")
            self.object_number.set("")
            self.date_start.set("")
            self.date_end.set("")
            self.graphemes.set("")
            self.component.set("")
            self.incomplete.set(False)
        finally:
            self.updating_fields = False

        self.scale = min(
            max(self.c.winfo_width(),1000) / self.image.width,
            max(self.c.winfo_height(),700) / self.image.height
        )
        self.ox = self.oy = 0
        self.update_current_image_label()
        self.update_metadata_button_visibility()
        self.draw()
        self.status.set("Click along stroke. Space/double-click ends stroke; Enter ends sign.")

        def _release_open_image_selection_suppression():
            self.suppress_selection_autoload = False
            self._end_selection_suppression(
                selection_token, saved=True, inscriptions=True
            )

        # Treeview selection events may be queued until after draw() rebuilds
        # the Saved panes, so release suppression only after the current event
        # cycle has completed.
        self.root.after_idle(_release_open_image_selection_suppression)

    def _csv_snapshot(self):
        serial = [
            {field: row.get(field, "") for field in FIELDS}
            for row in self.rows
        ]
        return json.dumps(
            serial, ensure_ascii=False, sort_keys=True,
            separators=(",", ":")
        )

    def csv_has_unsaved_changes(self):
        return self._csv_snapshot() != self._saved_csv_snapshot

    def _load_csv_path(self, path):
        path = os.path.abspath(path)
        self.csv_dir = os.path.dirname(path)
        self.csv_path = path
        with open(path, encoding="utf-8-sig", newline="") as f:
            loaded = list(csv.DictReader(f))

        if loaded and "point" not in loaded[0]:
            messagebox.showerror(
                "Old CSV format",
                "This is a straight-segment CSV from version 1."
            )
            return False

        self.rows = []
        sign_map = {}
        for r in loaded:
            r = dict(r)
            if "location" not in r:
                r["location"] = r.get("inscription", "")
            r.setdefault("latitude", "")
            r.setdefault("longitude", "")
            r.setdefault("object_type", "")
            r.setdefault("object_number", "")
            r.setdefault("date_start", "")
            r.setdefault("date_end", "")
            if "graphemes" not in r:
                r["graphemes"] = r.get("rune", "")
            r.setdefault("direction", "LTR")
            r.setdefault("certainty", "complete")
            r.setdefault("view_rotation_deg", "0")
            r.setdefault("component", r["graphemes"])
            r.setdefault("annotator", "")
            # Backward-compatible default: older Carve 1.1 development files
            # had automatic orientation detection hard-coded for j.
            if "matrix_orientation_detection" not in r:
                r["matrix_orientation_detection"] = (
                    "1" if str(r.get("graphemes", "")).strip().lower() == "j" else ""
                )
            if not r.get("sign_id"):
                old_key = (
                    r.get("location",""), r.get("object_type",""),
                    r.get("object_number",""), r.get("image",""),
                    r.get("graphemes",""), r.get("instance",""),
                    r.get("certainty","complete"),
                    r.get("annotator","")
                )
                sign_map.setdefault(old_key, short_id())
                r["sign_id"] = sign_map[old_key]
            self.rows.append({
                field: (
                    self._nfc(r.get(field, ""))
                    if isinstance(r.get(field, ""), str)
                    else r.get(field, "")
                )
                for field in FIELDS
            })

        self.rebuild_counts()
        self.refresh_sign_table()
        self.draw(refresh_table=False)
        self.root.update_idletasks()
        self.root.after(50, self.refresh_sign_table)
        self.update_metadata_button_visibility()
        self._saved_csv_snapshot = self._csv_snapshot()
        self.status.set(f"CSV loaded: {os.path.basename(path)}")
        return True

    # ---------- projects and annotators ----------

    def _load_recent_projects(self):
        try:
            with open(
                self.recent_projects_file,
                encoding="utf-8"
            ) as handle:
                values = json.load(handle)
            if isinstance(values, list):
                return [
                    os.path.abspath(path) for path in values
                    if isinstance(path, str) and os.path.isfile(path)
                ][:10]
        except Exception:
            pass
        return []

    def _save_recent_projects(self):
        try:
            with open(
                self.recent_projects_file,
                "w", encoding="utf-8"
            ) as handle:
                json.dump(
                    self.recent_projects[:10],
                    handle, ensure_ascii=False, indent=2
                )
        except Exception:
            pass

    def _remember_recent_project(self, path):
        path = os.path.abspath(path)
        self.recent_projects = [
            existing for existing in self.recent_projects
            if os.path.normcase(existing) != os.path.normcase(path)
        ]
        self.recent_projects.insert(0, path)
        self.recent_projects = self.recent_projects[:10]
        self._save_recent_projects()
        self._refresh_recent_projects_menu()

    def _refresh_recent_projects_menu(self):
        if not hasattr(self, "recent_projects_menu"):
            return
        self.recent_projects_menu.delete(0, "end")
        valid = [
            path for path in self.recent_projects
            if os.path.isfile(path)
        ]
        self.recent_projects = valid[:10]
        if not valid:
            self.recent_projects_menu.add_command(
                label="(None)", state="disabled"
            )
            return
        for path in valid:
            self.recent_projects_menu.add_command(
                label=os.path.basename(path),
                command=lambda p=path: self.open_project_path(p)
            )

    def _nfc(self, value):
        return unicodedata.normalize("NFC", str(value or ""))

    def _unicode_key(self, value):
        return self._nfc(value).casefold()

    def _safe_project_stem(self, name):
        """Keep Unicode and replace only characters forbidden in filenames."""
        stem = self._nfc(name).strip()
        stem = re.sub(r'[<>:"/\\|?*\x00-\x1f]', "_", stem)
        stem = re.sub(r"_+", "_", stem)
        stem = stem.rstrip(" .").lstrip(" ")
        if not stem:
            stem = "project"
        base = stem.split(".", 1)[0].casefold()
        reserved = {
            "con", "prn", "aux", "nul",
            *(f"com{i}" for i in range(1, 10)),
            *(f"lpt{i}" for i in range(1, 10)),
        }
        if base in reserved:
            stem = "_" + stem
        return stem

    def _relative_or_absolute(self, target, base):
        try:
            relative = os.path.relpath(target, base)
            # Prefer a relative path unless it crosses many parent folders.
            if not os.path.isabs(relative):
                return relative
        except Exception:
            pass
        return os.path.abspath(target)

    def _resolve_project_path(self, value, base):
        if not value:
            return ""
        return (
            os.path.abspath(os.path.join(base, value))
            if not os.path.isabs(value)
            else os.path.abspath(value)
        )

    def _project_payload(self, project_path=None):
        project_path = project_path or self.project_path
        base = os.path.dirname(os.path.abspath(project_path))
        return {
            "format": "Runic Annotator project",
            "version": 1,
            "project_name": self.project_name,
            "csv": self._relative_or_absolute(
                self.csv_path, base
            ) if self.csv_path else "",
            "images": self._relative_or_absolute(
                self.image_dir, base
            ) if self.image_dir else "images",
            "annotators": list(self.annotators),
            "current_annotator": self.current_annotator.get().strip(),
        }

    def _write_project_file(self, path):
        path = os.path.abspath(path)
        try:
            os.makedirs(os.path.dirname(path), exist_ok=True)
            with open(path, "w", encoding="utf-8") as handle:
                json.dump(
                    self._project_payload(path),
                    handle, ensure_ascii=False, indent=2
                )
        except Exception as exc:
            messagebox.showerror(
                "Save Project",
                f"Could not save the project:\n\n{exc}"
            )
            return False
        self.project_path = path
        self.project_folder = os.path.dirname(path)
        self._remember_recent_project(path)
        self._update_project_title()
        self.status.set(f"Project saved: {os.path.basename(path)}")
        return True

    def toggle_about_popover(self):
        """Show or hide the compact About panel below the toolbar button."""
        if self.about_popover is not None:
            self._close_about_popover()
            return

        popover = tk.Toplevel(self.root)
        self.about_popover = popover
        popover.withdraw()
        popover.overrideredirect(True)
        popover.transient(self.root)

        panel = tk.Frame(
            popover, background="white",
            highlightbackground="#a0a0a0", highlightthickness=1,
            padx=16, pady=14
        )
        panel.pack(fill="both", expand=True)

        base_font = tkfont.nametofont("TkDefaultFont")
        title_font = base_font.copy()
        title_font.configure(size=max(14, int(base_font.cget("size")) + 4), weight="bold")
        subtitle_font = base_font.copy()
        subtitle_font.configure(slant="italic")

        tk.Label(
            panel, text=APP_DISPLAY_NAME, background="white",
            font=title_font, anchor="w"
        ).pack(anchor="w")
        tk.Label(
            panel, text="A runic annotation and analysis platform",
            background="white", font=subtitle_font, anchor="w"
        ).pack(anchor="w", pady=(8,0))
        tk.Label(
            panel, text="© 2026 Guus Kroonen",
            background="white", font=base_font, anchor="w"
        ).pack(anchor="w", pady=(12,0))
        tk.Label(
            panel, text="AI-assisted development: ChatGPT (OpenAI)",
            background="white", font=base_font, anchor="w"
        ).pack(anchor="w", pady=(4,0))
        tk.Label(
            panel, text="Licensed under GNU GPLv3",
            background="white", font=base_font, anchor="w"
        ).pack(anchor="w", pady=(12,0))
        tk.Label(
            panel, text="See LICENSE.md for details.",
            background="white", font=base_font, anchor="w"
        ).pack(anchor="w")
        tk.Label(
            panel,
            text=(
                "Coastline data: Natural Earth 1:50m Land (v4.1.0)\n"
                "Public domain · naturalearthdata.com"
            ),
            background="white", font=base_font,
            anchor="w", justify="left"
        ).pack(anchor="w", pady=(12,0))

        popover.update_idletasks()
        x = self.info_menu_button.winfo_rootx()
        y = self.info_menu_button.winfo_rooty() + self.info_menu_button.winfo_height() + 2
        width = popover.winfo_reqwidth()
        screen_width = popover.winfo_screenwidth()
        x = max(0, min(x, screen_width - width - 4))
        popover.geometry(f"+{x}+{y}")
        popover.deiconify()
        popover.lift()

        popover.bind("<Escape>", lambda event: self._close_about_popover())
        self._about_root_click_binding = self.root.bind(
            "<Button-1>", self._dismiss_about_on_outside_click, add="+"
        )
        self._about_popover_click_binding = popover.bind(
            "<Button-1>", self._dismiss_about_on_outside_click, add="+"
        )

    def _dismiss_about_on_outside_click(self, event):
        """Dismiss the About popover unless the click is inside it or the Info button."""
        popover = self.about_popover
        if popover is None:
            return

        x_root = event.x_root
        y_root = event.y_root

        def contains(widget):
            try:
                x1 = widget.winfo_rootx()
                y1 = widget.winfo_rooty()
                return (
                    x1 <= x_root < x1 + widget.winfo_width()
                    and y1 <= y_root < y1 + widget.winfo_height()
                )
            except tk.TclError:
                return False

        if not contains(popover) and not contains(self.info_menu_button):
            self._close_about_popover()

    def _close_about_popover(self):
        """Destroy the About popover and remove its temporary global binding."""
        if self._about_root_click_binding is not None:
            try:
                self.root.unbind(
                    "<Button-1>", self._about_root_click_binding
                )
            except tk.TclError:
                pass
            self._about_root_click_binding = None
        if (
            self.about_popover is not None
            and self._about_popover_click_binding is not None
        ):
            try:
                self.about_popover.unbind(
                    "<Button-1>", self._about_popover_click_binding
                )
            except tk.TclError:
                pass
            self._about_popover_click_binding = None
        if self.about_popover is not None:
            try:
                self.about_popover.destroy()
            except tk.TclError:
                pass
            self.about_popover = None

    def _update_project_title(self):
        suffix = (
            f" - {self.project_name}"
            if self.project_name else ""
        )
        self.root.title(APP_NAME + suffix)

    def _confirm_csv_transition(self, action):
        if self._is_editing():
            messagebox.showinfo(
                "Current sign edit",
                "Finish the current sign edit first."
            )
            return False
        if not self.csv_has_unsaved_changes():
            return True
        answer = messagebox.askyesnocancel(
            "Unsaved sign data",
            "The sign data have changed since the last CSV save.\n\n"
            f"Save before {action}?"
        )
        if answer is None:
            return False
        if answer:
            return self.save_csv(quiet=True)
        return True

    def request_close(self):
        if not self._confirm_csv_transition("closing Carve"):
            return
        icon_path = getattr(self, "app_icon_path", "")
        self.root.destroy()
        if icon_path:
            try:
                os.remove(icon_path)
            except OSError:
                pass

    def new_project(self):
        if not self._context_change_allowed():
            return
        if not self._confirm_csv_transition("creating a new project"):
            return
        name = simpledialog.askstring(
            "New Project", "Project name:", parent=self.root
        )
        if not name or not name.strip():
            return
        annotator = "Unassigned"
        parent = filedialog.askdirectory(
            title="Choose the parent folder for the project"
        )
        if not parent:
            return

        stem = self._safe_project_stem(name)
        folder = os.path.join(parent, stem)
        if os.path.exists(folder) and os.listdir(folder):
            if not messagebox.askyesno(
                "Existing folder",
                f"The folder already exists and is not empty:\n\n{folder}\n\n"
                "Use it for the new project?"
            ):
                return
        os.makedirs(folder, exist_ok=True)
        image_dir = os.path.join(folder, "images")
        os.makedirs(image_dir, exist_ok=True)
        csv_path = os.path.join(
            folder, f"graphemes_{stem}.csv"
        )
        project_path = os.path.join(folder, f"{stem}.proj")

        self.rows = []
        self.counts = {}
        self.current_points = []
        self.current_strokes = []
        self.editing_sign_id = None
        self.editing_instance = None
        self.editing_annotator = None
        self.path = ""
        self.image = self.photo = None
        self.project_name = self._nfc(name).strip()
        self.project_folder = folder
        self.project_path = project_path
        self.csv_path = csv_path
        self.csv_dir = folder
        self.image_dir = image_dir
        self.annotators = [self._nfc(annotator).strip()]
        self.current_annotator.set(self._nfc(annotator).strip())
        self._refresh_annotator_selector()
        self.refresh_sign_table()
        self.draw(refresh_table=False)
        if not self.save_csv(csv_path, quiet=True):
            return
        self._write_project_file(project_path)
        self.status.set(f"Created project {self.project_name}.")


    def open_project(self):
        if not self._context_change_allowed():
            return
        if not self._confirm_csv_transition("opening another project"):
            return
        path = filedialog.askopenfilename(
            defaultextension=".proj",
            filetypes=[("Project files", "*.proj")]
        )
        if path:
            self.open_project_path(path, already_confirmed=True)

    def open_project_path(self, path, already_confirmed=False):
        if not already_confirmed:
            if not self._confirm_csv_transition(
                "opening another project"
            ):
                return
        path = os.path.abspath(path)
        try:
            with open(path, encoding="utf-8") as handle:
                data = json.load(handle)
        except Exception as exc:
            messagebox.showerror(
                "Open Project",
                f"Could not open the project:\n\n{exc}"
            )
            return
        base = os.path.dirname(path)
        csv_path = self._resolve_project_path(
            data.get("csv", ""), base
        )
        image_dir = self._resolve_project_path(
            data.get("images", "images"), base
        )
        if not csv_path or not os.path.isfile(csv_path):
            messagebox.showerror(
                "Open Project",
                f"The project CSV could not be found:\n\n{csv_path}"
            )
            return
        os.makedirs(image_dir, exist_ok=True)
        if not self._load_csv_path(csv_path):
            return

        self.project_path = path
        self.project_folder = base
        self.project_name = (
            str(data.get("project_name", "")).strip()
            or os.path.splitext(os.path.basename(path))[0]
        )
        self.image_dir = image_dir
        values = data.get("annotators", [])
        self.annotators = [
            str(value).strip() for value in values
            if str(value).strip()
        ]
        active = str(data.get("current_annotator", "")).strip()
        if active and active not in self.annotators:
            self.annotators.append(active)
        self.current_annotator.set(
            active if active in self.annotators
            else (self.annotators[0] if self.annotators else "")
        )
        self._refresh_annotator_selector()
        self._remember_recent_project(path)
        self._update_project_title()
        self.status.set(f"Opened project {self.project_name}.")

    def save_project(self):
        if not self.project_path:
            return self.save_project_as()

        if self.csv_path:
            if not self.save_csv(self.csv_path, quiet=True):
                return False

        return self._write_project_file(self.project_path)





    def save_project_as(self):
        if not self.project_path:
            messagebox.showinfo(
                "Save Project As",
                "No project is currently open.\n\n"
                "Use New Project or Import Existing CSV instead."
            )
            return False

        initial_dir = (
            os.path.dirname(self.project_folder)
            if self.project_folder else os.getcwd()
        )
        chosen = filedialog.asksaveasfilename(
            title="Save Project As",
            initialdir=initial_dir,
            initialfile=f"{self.project_name}.proj",
            defaultextension=".proj",
            filetypes=[
                ("Carve project", "*.proj"),
                ("All files", "*.*"),
            ],
        )
        if not chosen:
            return False

        chosen = os.path.abspath(chosen)
        parent = os.path.dirname(chosen)
        stem = self._safe_project_stem(
            os.path.splitext(os.path.basename(chosen))[0]
        )
        new_name = os.path.splitext(os.path.basename(chosen))[0].strip()
        destination = os.path.join(parent, stem)

        if (
            os.path.exists(destination)
            and os.path.abspath(destination)
            != os.path.abspath(self.project_folder or "")
            and os.listdir(destination)
        ):
            messagebox.showerror(
                "Save Project As",
                "The destination folder already exists and is not empty:\n\n"
                f"{destination}"
            )
            return False

        os.makedirs(destination, exist_ok=True)
        new_images = os.path.join(destination, "images")
        os.makedirs(new_images, exist_ok=True)

        new_csv = os.path.join(
            destination, f"graphemes_{stem}.csv"
        )
        new_project = os.path.join(destination, f"{stem}.proj")

        try:
            self._write_csv_atomic(new_csv)

            if os.path.isdir(self.image_dir):
                for name in os.listdir(self.image_dir):
                    source = os.path.join(self.image_dir, name)
                    target = os.path.join(new_images, name)
                    if os.path.isfile(source):
                        shutil.copy2(source, target)
        except Exception as exc:
            messagebox.showerror(
                "Save Project As",
                f"Could not copy the project:\n\n{exc}"
            )
            return False

        self.project_name = new_name
        self.project_folder = destination
        self.project_path = new_project
        self.csv_path = new_csv
        self.csv_dir = destination
        self.image_dir = new_images
        self._saved_csv_snapshot = self._csv_snapshot()

        if not self._write_project_file(new_project):
            return False

        messagebox.showinfo(
            "Project copied",
            f"Project:\n{self.project_name}\n\n"
            f"Folder:\n{destination}\n\n"
            "The copied project is now open."
        )
        return True


    def show_project_information(self):
        if not self.project_path:
            messagebox.showinfo(
                "Project Information",
                "No project is currently open."
            )
            return
        image_names = {
            row.get("image", "") for row in self.rows
            if row.get("image", "")
        }
        info = (
            f"Project: {self.project_name}\n\n"
            f"Project file:\n{self.project_path}\n\n"
            f"CSV:\n{self.csv_path}\n\n"
            f"Images folder:\n{self.image_dir}\n\n"
            f"Signs: {len(self.group_rows_by_sign())}\n"
            f"Images represented in CSV: {len(image_names)}"
        )
        messagebox.showinfo("Project Information", info)

    def _refresh_annotator_selector(self):
        if hasattr(self, "annotator_combobox"):
            self.annotator_combobox.configure(values=self.annotators)

    def _persist_annotator_changes(self, save_csv=False):
        """Persist selector metadata and, when needed, changed CSV rows."""
        self._refresh_annotator_selector()
        if save_csv and self.csv_path:
            self.save_csv(self.csv_path, quiet=True)
        if self.project_path:
            self._write_project_file(self.project_path)

    def _begin_annotator_edit(self, event=None):
        self._annotator_edit_original = self.current_annotator.get().strip()

    def _select_annotator(self, event=None):
        """Switch the default annotator without changing saved signs."""
        selected = self.current_annotator.get().strip()
        self.current_annotator.set(selected)
        self._annotator_edit_original = selected
        if selected and selected not in self.annotators:
            self.annotators.append(selected)
        self._persist_annotator_changes(save_csv=False)

    def _commit_annotator_edit(self, event=None):
        """Rename the active annotator and propagate the rename."""
        old = getattr(
            self, "_annotator_edit_original",
            self.current_annotator.get().strip()
        ).strip()
        new = self.current_annotator.get().strip()

        # Empty names are created only by deleting an annotator.
        if not new:
            self.current_annotator.set(old)
            return "break" if event and getattr(event, "keysym", "") == "Return" else None

        if new == old:
            self.current_annotator.set(new)
            self._annotator_edit_original = new
            self._persist_annotator_changes(save_csv=False)
            return "break" if event and getattr(event, "keysym", "") == "Return" else None

        if new in self.annotators:
            messagebox.showinfo(
                "Annotator",
                f'An annotator named "{new}" already exists.'
            )
            self.current_annotator.set(old)
            return "break" if event and getattr(event, "keysym", "") == "Return" else None

        if old in self.annotators:
            index = self.annotators.index(old)
            self.annotators[index] = new
            for row in self.rows:
                if str(row.get("annotator", "")).strip() == old:
                    row["annotator"] = new
            if self.editing_annotator == old:
                self.editing_annotator = new
            changed_rows = True
        else:
            self.annotators.append(new)
            changed_rows = False

        self.current_annotator.set(new)
        self._annotator_edit_original = new
        self._persist_annotator_changes(save_csv=changed_rows)
        return "break" if event and getattr(event, "keysym", "") == "Return" else None

    def add_annotator(self):
        """Create a uniquely named annotator and start inline renaming."""
        base = "New annotator"
        name = base
        suffix = 2
        while name in self.annotators:
            name = f"{base} {suffix}"
            suffix += 1
        self.annotators.append(name)
        self.current_annotator.set(name)
        self._annotator_edit_original = name
        self._persist_annotator_changes(save_csv=False)
        self.annotator_combobox.focus_set()
        self.annotator_combobox.selection_range(0, "end")
        self.annotator_combobox.icursor("end")

    def remove_current_annotator(self):
        """Delete the current name and clear its saved CSV references."""
        name = self.current_annotator.get().strip()
        if not name or name not in self.annotators:
            return

        affected_signs = {
            str(row.get("sign_id", "")).strip()
            for row in self.rows
            if str(row.get("annotator", "")).strip() == name
        }
        affected_signs.discard("")
        count = len(affected_signs)
        detail = (
            f"\n\nThis will clear the annotator field for "
            f"{count} saved sign{'s' if count != 1 else ''}."
            if count else ""
        )
        if not messagebox.askyesno(
            "Delete Annotator",
            f'Delete annotator "{name}"?{detail}'
        ):
            return

        self.annotators.remove(name)
        changed_rows = False
        for row in self.rows:
            if str(row.get("annotator", "")).strip() == name:
                row["annotator"] = ""
                changed_rows = True
        if self.editing_annotator == name:
            self.editing_annotator = ""

        next_name = self.annotators[0] if self.annotators else ""
        self.current_annotator.set(next_name)
        self._annotator_edit_original = next_name
        self._persist_annotator_changes(save_csv=changed_rows)


    def load_csv(self):
        if not self._context_change_allowed():
            return
        if self._is_editing():
            self.status.set(
                "Finish the current edit before loading another CSV."
            )
            return
        if not self._confirm_csv_transition("loading another CSV"):
            return
        p = filedialog.askopenfilename(
            filetypes=[("CSV","*.csv")]
        )
        if p:
            self._load_csv_path(p)

    def _write_csv_atomic(self, path):
        """Write the current rows atomically using standards-compliant CSV.

        Characters such as ``?`` are ordinary field data and require no
        escaping. The csv module quotes commas, quotes, and line breaks as
        needed. Writing to a sibling temporary file first prevents a failed or
        interrupted save from leaving a partially written project CSV.
        """
        path = os.path.abspath(path)
        folder = os.path.dirname(path)
        os.makedirs(folder, exist_ok=True)
        fd, temporary = tempfile.mkstemp(
            prefix=os.path.basename(path) + ".",
            suffix=".tmp",
            dir=folder,
        )
        try:
            with os.fdopen(
                fd, "w", newline="", encoding="utf-8-sig"
            ) as handle:
                writer = csv.DictWriter(
                    handle,
                    fieldnames=FIELDS,
                    quoting=csv.QUOTE_MINIMAL,
                )
                writer.writeheader()
                for row in self.rows:
                    writer.writerow({
                        field: row.get(field, "")
                        for field in FIELDS
                    })
                handle.flush()
                os.fsync(handle.fileno())
            os.replace(temporary, path)
        except Exception:
            try:
                os.close(fd)
            except OSError:
                pass
            try:
                os.remove(temporary)
            except OSError:
                pass
            raise

    def save_csv(self, path=None, quiet=False):
        if self._is_editing():
            messagebox.showinfo(
                "Sign Annotator",
                "Finish the current sign edit before saving the CSV."
            )
            return False
        if path is None:
            path = self.csv_path
        if not path:
            if not self.rows:
                messagebox.showinfo(
                    "Sign Annotator", "Nothing to save."
                )
                return False
            path = filedialog.asksaveasfilename(
                defaultextension=".csv",
                filetypes=[("CSV","*.csv")]
            )
        if not path:
            return False
        path = os.path.abspath(path)
        try:
            self._write_csv_atomic(path)
        except Exception as exc:
            messagebox.showerror(
                "Save CSV", f"Could not save the CSV:\n\n{exc}"
            )
            return False
        self.csv_path = path
        self.csv_dir = os.path.dirname(path)
        self._saved_csv_snapshot = self._csv_snapshot()
        if not quiet:
            self.status.set(f"CSV saved: {os.path.basename(path)}")
        return True

    def save_csv_as(self):
        """Always ask for a new CSV path in the Explorer Save-As dialog."""
        if self._is_editing():
            messagebox.showinfo(
                "Sign Annotator",
                "Finish the current sign edit before saving the CSV."
            )
            return False
        if not self.rows:
            messagebox.showinfo(
                "Sign Annotator", "Nothing to save."
            )
            return False

        initial_dir = self.csv_dir or os.getcwd()
        initial_file = (
            os.path.basename(self.csv_path)
            if self.csv_path else "graphemes.csv"
        )
        path = filedialog.asksaveasfilename(
            title="Save CSV As",
            initialdir=initial_dir,
            initialfile=initial_file,
            defaultextension=".csv",
            filetypes=[
                ("CSV", "*.csv"),
                ("All files", "*.*"),
            ],
        )
        if not path:
            return False
        return self.save_csv(path=path)


    # ---------- table ----------

    @staticmethod
    def _parse_period_year(value):
        """Return an integer year, or None for blank/invalid input."""
        value = str(value or "").strip()
        if not value:
            return None
        try:
            return int(value)
        except (TypeError, ValueError):
            return None

    def _period_filter_bounds(self):
        """Return normalized inclusive bounds and whether filtering is active."""
        lower_text = self.period_from.get().strip()
        upper_text = self.period_to.get().strip()
        lower = self._parse_period_year(lower_text)
        upper = self._parse_period_year(upper_text)
        active = bool(lower_text or upper_text)
        # Start and End address different inscription fields, so do not
        # reorder them as though they were the bounds of one interval.
        return lower, upper, active

    def _row_matches_period_filter(self, row, bounds=None):
        """Use inclusive range overlap to test one inscription/sign row."""
        lower, upper, active = bounds or self._period_filter_bounds()
        if not active:
            return True

        start = self._parse_period_year(row.get("date_start", ""))
        end = self._parse_period_year(row.get("date_end", ""))

        if self.period_strict.get():
            # Strict mode treats the Period fields as hard lower/upper limits:
            # an inscription's full date range must fit inside them.
            if lower is not None and (start is None or start < lower):
                return False
            if upper is not None and (end is None or end > upper):
                return False
            return True

        # Ordinary mode is inclusive range overlap. An inscription is included
        # when any part of its date range falls within the requested period.
        interval_start = start if start is not None else end
        interval_end = end if end is not None else start
        if interval_start is None and interval_end is None:
            return False
        if interval_start is None:
            interval_start = interval_end
        if interval_end is None:
            interval_end = interval_start
        if lower is not None and interval_end < lower:
            return False
        if upper is not None and interval_start > upper:
            return False
        return True

    def _object_filter_selected(self, object_type):
        key = str(object_type or "").strip()
        if not key:
            return True
        var = self.object_filter_vars.get(key)
        return True if var is None else bool(var.get())

    def _refresh_object_filter_menu(self):
        objects = sorted(
            {str(r.get("object_type", "")).strip() for r in self.rows if str(r.get("object_type", "")).strip()},
            key=self._unicode_key
        )
        for obj in objects:
            if obj not in self.object_filter_vars:
                self.object_filter_vars[obj] = tk.BooleanVar(value=True)
        self._update_object_filter_button()

    def _object_filter_objects(self):
        return sorted(
            [
                key for key in self.object_filter_vars
                if str(key or "").strip()
            ],
            key=self._unicode_key
        )

    def _object_filter_row_text(self, obj):
        mark = "\u2713" if self.object_filter_vars[obj].get() else " "
        return f"{obj}  {mark}"

    def _toggle_object_filter_popup(self):
        popup = getattr(self, "_object_filter_popup", None)
        if popup is not None and popup.winfo_exists():
            self._close_object_filter_popup()
            return
        self._show_object_filter_popup()

    def _close_object_filter_popup(self):
        popup = getattr(self, "_object_filter_popup", None)
        for sequence, attr in (
            ("<Configure>", "_object_filter_root_configure_bind"),
            ("<Button-1>", "_object_filter_root_click_bind"),
        ):
            bind_id = getattr(self, attr, None)
            if bind_id:
                try:
                    self.root.unbind(sequence, bind_id)
                except tk.TclError:
                    pass
                setattr(self, attr, None)
        if popup is not None and popup.winfo_exists():
            popup.destroy()
        self._object_filter_popup = None
        self._object_filter_popup_listbox = None

    def _show_object_filter_popup(self):
        """Open a compact scrollable object-type checklist."""
        objects = self._object_filter_objects()
        popup = tk.Toplevel(self.root)
        self._object_filter_popup = popup
        popup.withdraw()
        popup.transient(self.root)
        popup.overrideredirect(True)

        frame = ttk.Frame(popup, relief="solid", borderwidth=1)
        frame.pack(fill="both", expand=True)

        list_frame = ttk.Frame(frame)
        list_frame.pack(fill="both", expand=True)
        visible_rows = min(max(len(objects), 1), 12)
        listbox = tk.Listbox(
            list_frame, height=visible_rows,
            activestyle="dotbox", exportselection=False,
            borderwidth=0, highlightthickness=1,
            takefocus=False
        )
        scrollbar = ttk.Scrollbar(
            list_frame, orient="vertical", command=listbox.yview
        )
        listbox.configure(yscrollcommand=scrollbar.set)
        list_frame.grid_columnconfigure(0, weight=1)
        list_frame.grid_rowconfigure(0, weight=1)
        listbox.grid(row=0, column=0, sticky="nsew")
        scrollbar.grid(row=0, column=1, sticky="ns")

        if objects:
            for obj in objects:
                listbox.insert("end", self._object_filter_row_text(obj))
        else:
            listbox.insert("end", "No objects")
            listbox.configure(state="disabled")

        button_row = ttk.Frame(frame)
        button_row.pack(fill="x", padx=3, pady=3)

        def set_all_and_close(value):
            self._set_all_objects_in_popup(value)
            self._close_object_filter_popup()

        ttk.Button(
            button_row, text="All", width=4,
            command=lambda: set_all_and_close(True),
            takefocus=False
        ).pack(side="left")
        ttk.Button(
            button_row, text="None", width=5,
            command=lambda: set_all_and_close(False),
            takefocus=False
        ).pack(side="left", padx=(3,0))
        self._object_filter_popup_listbox = listbox
        self._object_filter_popup_objects = objects

        def toggle_selected(event=None):
            if event is not None and getattr(event, "y", None) is not None:
                index = listbox.nearest(event.y)
            else:
                selection = listbox.curselection()
                if not selection:
                    return "break"
                index = selection[0]
            if not objects:
                return "break"
            if index >= len(objects):
                return "break"
            obj = objects[index]
            var = self.object_filter_vars[obj]
            var.set(not var.get())
            listbox.delete(index)
            listbox.insert(index, self._object_filter_row_text(obj))
            listbox.selection_set(index)
            listbox.activate(index)
            self._apply_object_filter()
            return "break"

        def close_from_root_click(event=None):
            x_root = event.x_root
            y_root = event.y_root

            def contains(widget):
                try:
                    x1 = widget.winfo_rootx()
                    y1 = widget.winfo_rooty()
                    return (
                        x1 <= x_root < x1 + widget.winfo_width()
                        and y1 <= y_root < y1 + widget.winfo_height()
                    )
                except tk.TclError:
                    return False

            try:
                if (
                    contains(popup)
                    or contains(self.object_filter_button)
                ):
                    return
                self._close_object_filter_popup()
            except tk.TclError:
                pass

        listbox.bind("<Button-1>", toggle_selected)
        popup.bind("<Escape>", lambda event: self._close_object_filter_popup())

        self.object_filter_button.update_idletasks()
        button_x = self.object_filter_button.winfo_rootx()
        button_w = self.object_filter_button.winfo_width()
        y = (
            self.object_filter_button.winfo_rooty()
            + self.object_filter_button.winfo_height()
        )
        height_px = visible_rows * 22 + 36
        width = button_w
        x = button_x
        popup.geometry(f"{width}x{height_px}+{x}+{y}")
        popup.deiconify()
        popup.lift()
        self._object_filter_root_configure_bind = self.root.bind(
            "<Configure>",
            lambda event: self._close_object_filter_popup(),
            add="+"
        )
        self._object_filter_root_click_bind = self.root.bind(
            "<Button-1>",
            close_from_root_click,
            add="+"
        )

    def _refresh_object_filter_popup(self):
        popup = getattr(self, "_object_filter_popup", None)
        listbox = getattr(self, "_object_filter_popup_listbox", None)
        if popup is None or listbox is None or not popup.winfo_exists():
            return
        objects = self._object_filter_objects()
        self._object_filter_popup_objects = objects
        listbox.configure(state="normal")
        listbox.delete(0, "end")
        if objects:
            for obj in objects:
                listbox.insert("end", self._object_filter_row_text(obj))
        else:
            listbox.insert("end", "No objects")
            listbox.configure(state="disabled")

    def _set_all_objects_in_popup(self, value):
        for var in self.object_filter_vars.values():
            var.set(bool(value))
        self._apply_object_filter()
        self._refresh_object_filter_popup()

    def _clear_all_objects(self):
        for var in self.object_filter_vars.values():
            var.set(False)
        self._apply_object_filter()
        self._refresh_object_filter_popup()

    def _select_all_objects(self):
        for var in self.object_filter_vars.values():
            var.set(True)
        self._apply_object_filter()
        self._refresh_object_filter_popup()

    def _update_object_filter_button(self):
        objects = self._object_filter_objects()
        active_objects = [
            obj for obj in objects
            if self.object_filter_vars[obj].get()
        ]
        total = len(objects)
        active = len(active_objects)
        if total == 0:
            text = "No objects"
        elif active == 0:
            text = "None"
        else:
            text = f"{active} out of {total}"
        self.object_filter_button.configure(text=text)

    def _apply_object_filter(self):
        self._update_object_filter_button()
        self.refresh_saved_panes()
        self._redraw_existing_time_longitude()
        if self.current_view == "normalized":
            self.render_normalized_comparison()
        elif self.current_view == "network":
            self.render_similarity_network()
        elif self.current_view == "cluster":
            self.render_cluster_view()
        elif self.current_view == "pairwise":
            self.render_pairwise_comparison()
        elif self.current_view == "map":
            self.render_rune_map()

    def working_rows(self):
        """Yield the canonical working subset used by tables and analyses.

        Editing, loading, saving, deletion, and metadata changes intentionally
        continue to operate on the complete master dataset in ``self.rows``.
        """
        bounds = self._period_filter_bounds()
        for row in self.rows:
            if (
                self._row_matches_period_filter(row, bounds)
                and self._object_filter_selected(row.get("object_type", ""))
            ):
                yield row

    def _schedule_period_filter_refresh(self, *args):
        """Debounce table refreshes while either Period field is being typed."""
        if self.period_filter_after_id is not None:
            try:
                self.root.after_cancel(self.period_filter_after_id)
            except Exception:
                pass
        self.period_filter_after_id = self.root.after(
            250, self._apply_period_filter
        )

    def _apply_period_filter(self):
        self.period_filter_after_id = None
        self.refresh_saved_panes()
        # Already rendered analytical views follow the global Period filter
        # immediately, just like the object filter.
        self._redraw_existing_time_longitude()
        if self.current_view == "normalized":
            self.render_normalized_comparison()
        elif self.current_view == "network":
            self.render_similarity_network()
        elif self.current_view == "cluster":
            self.render_cluster_view()
        elif self.current_view == "pairwise":
            self.render_pairwise_comparison()
        elif self.current_view == "map":
            self.render_rune_map()

    def group_rows_by_sign(self):
        grouped = {}
        for r in self.working_rows():
            grouped.setdefault(r["sign_id"], []).append(r)
        return grouped

    def _tree_selected_sign_id(self):
        sel = self.tree.selection()
        return sel[0] if sel else None

    def _set_active_sign_id(self, sign_id):
        if sign_id and any(
            row.get("sign_id") == sign_id for row in self.rows
        ):
            self.active_sign_id = sign_id
        else:
            self.active_sign_id = None
        return self.active_sign_id

    def _remember_active_sign(self, sign_id):
        """Remember a deliberate sign choice for its inscription."""
        if not sign_id:
            return
        for row in self.rows:
            if row.get("sign_id") == sign_id:
                key = (
                    row.get("location", ""),
                    row.get("object_type", ""),
                    row.get("object_number", ""),
                )
                self.inscription_active_sign_ids[key] = sign_id
                return

    def selected_sign_id(self):
        active = getattr(self, "active_sign_id", None)
        if active and any(
            row.get("sign_id") == active for row in self.rows
        ):
            return active
        return self._set_active_sign_id(self._tree_selected_sign_id())

    def _preserved_sign_id(self):
        """Return the canonical sign without letting Treeview overwrite it."""
        active = getattr(self, "active_sign_id", None)
        if active and any(
            row.get("sign_id") == active for row in self.rows
        ):
            return active
        return self._tree_selected_sign_id()

    def display_graphemes(self, graphemes, certainty):
        """Display incompleteness on the primary reading of a physical sign."""
        raw = str(graphemes or "")
        primary, separator, alternatives = raw.partition(",")
        if certainty == "incomplete":
            primary += "\u0323"
        return primary + (separator + alternatives if separator else "")

    def display_sign_identifier(self, graphemes, certainty, instance):
        """Place the instance number after an ambiguous sign's primary value.

        For example, an incomplete ``h,m`` with instance 1 is rendered as
        ``h\u03231,m``. The ambiguity and completeness flags remain independent
        properties of the one physical sign; this is only a compact notation.
        """
        raw = str(graphemes or "")
        primary, separator, alternatives = raw.partition(",")
        if certainty == "incomplete":
            primary += "\u0323"
        primary += str(instance or "")
        return primary + (separator + alternatives if separator else "")

    def sign_summaries(self):
        out = []
        for sid, rows in self.group_rows_by_sign().items():
            if not rows:
                continue
            first = rows[0]
            xs = [float(r["x"]) for r in rows if r.get("x","") != ""]
            cx = sum(xs)/len(xs) if xs else 0
            out.append({
                "sign_id": sid,
                "label": self.object_label_from_values(first.get("location",""), first.get("object_type",""), first.get("object_number","")),
                "location": first.get("location",""),
                "object_type": first.get("object_type",""),
                "object_number": first.get("object_number",""),
                "image": first.get("image",""),
                "direction": first.get("direction","LTR"),
                "graphemes": first.get("graphemes",""),
                "instance": first.get("instance",""),
                "certainty": first.get("certainty","complete"),
                "strokes": len(set(r["stroke"] for r in rows)),
                "cx": cx,
            })
        return out

    def sort_sign_table_by(self, column):
        if self.table_sort_column == column:
            self.table_sort_reverse = not self.table_sort_reverse
        else:
            self.table_sort_column = column
            self.table_sort_reverse = False
        self.refresh_sign_table()

    def refresh_sign_table(self):
        # Any external rebuild means the cached restricted Saved-signs pane
        # may no longer reflect current rows/metadata. _refresh_restricted_saved_signs()
        # sets a fresh key after it finishes its own rebuild.
        self._restricted_saved_pane_key = None
        if hasattr(self, "object_filter_button"):
            self._refresh_object_filter_menu()
        current = self.selected_sign_id()
        self.refreshing_table = True
        try:
            for item in self.tree.get_children():
                self.tree.delete(item)

            f = (
                self._unicode_key(self.filter_text.get().strip())
                if hasattr(self, "filter_text") else ""
            )

            def sortkey(row):
                col = self.table_sort_column
                if col == "object":
                    val = row.get("object_type", "")
                elif col == "no":
                    val = row.get("object_number", "")
                elif col == "sign":
                    val = row.get("graphemes", "")
                elif col == "instance":
                    val = int(row["instance"]) if str(row["instance"]).isdigit() else 0
                elif col == "direction":
                    val = row.get("direction", "")
                elif col == "strokes":
                    val = row.get("strokes", 0)
                elif col == "location":
                    val = row.get("location", "")
                else:
                    val = row.get(col, "")
                normalized = (
                    self._unicode_key(val)
                    if isinstance(val, str) else val
                )
                return (
                    normalized,
                    self._unicode_key(row.get("location", "")),
                    self._unicode_key(row.get("object_type", "")),
                    self._unicode_key(row.get("object_number", "")),
                    int(row["instance"])
                    if str(row["instance"]).isdigit() else 0
                )

            for s in sorted(self.sign_summaries(), key=sortkey, reverse=self.table_sort_reverse):
                textblob = self._unicode_key(
                    " ".join(
                        str(s[k]) for k in [
                            "label", "image", "graphemes", "instance",
                            "certainty", "direction"
                        ]
                    )
                )
                if f and f not in textblob:
                    continue
                self.tree.insert(
                    "", "end", iid=s["sign_id"],
                    values=(s.get("location",""), s.get("object_type",""), s.get("object_number",""),
                            self.display_graphemes(s["graphemes"], s["certainty"]),
                            s["direction"])
                )

            if current and current in self.tree.get_children(""):
                self.tree.selection_set(current)

            if (
                hasattr(self, "_uses_restricted_saved_signs")
                and self._uses_restricted_saved_signs(
                    getattr(self, "current_view", None)
                )
            ):
                self._filter_saved_signs_for_analysis()
            elif getattr(self, "current_view", None) == "normalized":
                self._filter_saved_signs_for_normalized()
            # The filtering above may have changed the Treeview's scroll
            # position. Restore the canonical row after the final filter.
            restored_sign_id = self._preserved_sign_id()
            if restored_sign_id in self.tree.get_children(""):
                self.tree.selection_set(restored_sign_id)
                self.tree.focus(restored_sign_id)
                self._scroll_saved_sign_near_top(restored_sign_id)
        finally:
            self.refreshing_table = False
        self.suppress_selection_autoload = False

        # Keep the cached Saved inscriptions pane synchronized whenever the
        # underlying saved-sign table is refreshed.  Pane switching itself
        # remains a cheap show/hide operation, but the inscription tree is no
        # longer left empty after loading or changing a project.
        if hasattr(self, "inscription_tree"):
            self.refresh_inscription_table()

        self.show_annotations = tk.BooleanVar(value=True)
        self.normalized_click_selection = False

    def rebuild_counts(self):
        self.counts = {}
        for sid, rows in self.group_rows_by_sign().items():
            first = rows[0]
            k = (
                first.get("location", ""),
                first.get("object_type", ""),
                first.get("object_number", ""),
                self._primary_grapheme(first.get("graphemes", "")),
            )
            try:
                inst = int(first["instance"])
            except Exception:
                inst = 0
            self.counts[k] = max(self.counts.get(k, 0), inst)

    # ---------- drawing ----------

    def _rotated_image_dimensions(self):
        if self.image is None:
            return (1, 1)
        if self._rotated_image_size is not None:
            return self._rotated_image_size
        angle = float(self.view_rotation_deg or 0.0)
        if abs(angle) < 1e-9:
            self._rotated_image_size = (
                self.image.width, self.image.height
            )
        else:
            preview = self.image.rotate(
                angle, resample=Image.Resampling.BICUBIC,
                expand=True
            )
            self._rotated_image_size = preview.size
        return self._rotated_image_size

    def _image_to_rotated(self, x, y):
        if self.image is None:
            return (x, y)
        angle = math.radians(float(self.view_rotation_deg or 0.0))
        cos_a = math.cos(angle)
        sin_a = math.sin(angle)
        cx = self.image.width / 2.0
        cy = self.image.height / 2.0
        rw, rh = self._rotated_image_dimensions()
        dx = x - cx
        dy = y - cy
        return (
            rw / 2.0 + cos_a * dx + sin_a * dy,
            rh / 2.0 - sin_a * dx + cos_a * dy
        )

    def _rotated_to_image(self, x, y):
        if self.image is None:
            return (x, y)
        angle = math.radians(float(self.view_rotation_deg or 0.0))
        cos_a = math.cos(angle)
        sin_a = math.sin(angle)
        rw, rh = self._rotated_image_dimensions()
        dx = x - rw / 2.0
        dy = y - rh / 2.0
        return (
            self.image.width / 2.0 + cos_a * dx - sin_a * dy,
            self.image.height / 2.0 + sin_a * dx + cos_a * dy
        )

    def i2c(self, x, y):
        rx, ry = self._image_to_rotated(x, y)
        return rx*self.scale+self.ox, ry*self.scale+self.oy

    def c2i(self, x, y):
        rx = (x-self.ox)/self.scale
        ry = (y-self.oy)/self.scale
        return self._rotated_to_image(rx, ry)

    def draw_polyline(self, points, fill, width):
        if len(points) == 1:
            x,y = self.i2c(*points[0])
            self.c.create_oval(x-4,y-4,x+4,y+4, outline=fill, width=2)
        elif len(points) >= 2:
            coords = []
            for p in points:
                coords.extend(self.i2c(*p))
            self.c.create_line(*coords, fill=fill, width=width, smooth=True, splinesteps=24)
            for p in points:
                x,y = self.i2c(*p)
                self.c.create_oval(x-3,y-3,x+3,y+3, fill=fill, outline=fill)

    def draw(self, refresh_table=True):
        if self.image is None:
            if refresh_table:
                self.refresh_sign_table()
            self._update_contextual_toolbar_state()
            return

        self.c.delete("all")
        angle = float(self.view_rotation_deg or 0.0)
        if abs(angle) < 1e-9:
            display_image = self.image
        else:
            display_image = self.image.rotate(
                angle, resample=Image.Resampling.BICUBIC,
                expand=True
            )
        self._rotated_image_size = display_image.size
        w = max(1, int(display_image.width*self.scale))
        h = max(1, int(display_image.height*self.scale))
        self.photo = ImageTk.PhotoImage(
            display_image.resize((w,h), Image.Resampling.LANCZOS)
        )
        self.c.create_image(
            self.ox, self.oy, anchor="nw", image=self.photo
        )

        image_name = os.path.basename(self.path)
        selected = getattr(self, "active_sign_id", None)

        if self.show_annotations.get():
            for sid, rows in self.group_rows_by_sign().items():
                if not rows or rows[0].get("image","") != image_name:
                    continue
                by_stroke = {}
                for r in rows:
                    by_stroke.setdefault(int(r["stroke"]), []).append(r)

                is_selected = sid == selected
                for stroke, rr in sorted(by_stroke.items()):
                    rr.sort(key=lambda z: int(z["point"]))
                    pts = [(float(z["x"]), float(z["y"])) for z in rr]
                    self.draw_polyline(pts, "magenta" if is_selected else "cyan", 5 if is_selected else 3)

                first = rows[0]
                pts_all = [(float(r["x"]), float(r["y"])) for r in rows]
                if pts_all:
                    x = sum(p[0] for p in pts_all)/len(pts_all)
                    y = min(p[1] for p in pts_all)
                    cx, cy = self.i2c(x, y)
                    self.c.create_text(
                        cx, cy-12,
                        text=self.display_sign_identifier(
                            first["graphemes"],
                            first.get("certainty", "complete"),
                            first["instance"],
                        ),
                        fill="white" if is_selected else "yellow",
                        font=("Arial", 10, "bold")
                    )

            for stroke in self.current_strokes:
                self.draw_polyline(stroke["points"], "orange", 3)
            self.draw_polyline(self.current_points, "red", 3)

        if refresh_table:
            self.refresh_sign_table()
        self._update_contextual_toolbar_state()

    def rotate_editing_view(self, delta_degrees):
        if self.current_view != "entry" or self.image is None:
            return
        old_rw, old_rh = self._rotated_image_dimensions()
        centre_canvas_x = self.ox + old_rw*self.scale/2.0
        centre_canvas_y = self.oy + old_rh*self.scale/2.0

        self.view_rotation_deg = (
            float(self.view_rotation_deg) + float(delta_degrees)
        )
        # Keep angles readable and equivalent.
        while self.view_rotation_deg > 180:
            self.view_rotation_deg -= 360
        while self.view_rotation_deg <= -180:
            self.view_rotation_deg += 360

        self._rotated_image_size = None
        new_rw, new_rh = self._rotated_image_dimensions()
        self.ox = centre_canvas_x - new_rw*self.scale/2.0
        self.oy = centre_canvas_y - new_rh*self.scale/2.0
        self.rotation_status.set(
            f"Rotation: {self.view_rotation_deg:g}°"
        )
        self.status.set(
            f"Editing view rotated to {self.view_rotation_deg:g}°."
        )
        self.draw(refresh_table=False)

    def reset_editing_view_rotation(self):
        if self.current_view != "entry" or self.image is None:
            return
        self.rotate_editing_view(-float(self.view_rotation_deg))

    # ---------- annotation ----------

    def click(self, e):
        if self.current_view != "entry":
            return
        if self.image is None:
            return
        if not self._is_editing() and not self._is_drawing_new_sign():
            self._enter_drawing_mode()
        self.current_points.append(self.c2i(e.x,e.y))
        self.status.set(f"Current stroke: {len(self.current_points)} point(s).")
        self.draw(refresh_table=False)

    def double_click(self, e):
        if self.current_view != "entry":
            return
        self.finish_stroke()

    def finish_stroke(self):
        if self.current_view != "entry":
            self.status.set("Stroke editing is disabled in normalized visualization mode.")
            return
        if len(self.current_points) < 2:
            self.status.set("A stroke needs at least two points.")
            return
        raw_graphemes = self.graphemes.get().strip()
        comp = (
            self._primary_grapheme(raw_graphemes)
            if self._is_ambiguous_grapheme(raw_graphemes)
            else self.component.get().strip() or raw_graphemes
        )
        self.current_strokes.append({"points": self.current_points[:], "component": comp})
        self.current_points = []
        self.status.set(f"Stroke {len(self.current_strokes)} finished. Draw next stroke or press Enter.")
        self.draw(refresh_table=False)

    def make_rows_for_current_buffer(self, sign_id, instance):
        location = self._nfc(self.ins.get()).strip()
        graphemes = self._nfc(self.graphemes.get()).strip()
        cert = "incomplete" if self.incomplete.get() else "complete"
        image_name = os.path.basename(self.path)

        out = []
        for s, stroke_data in enumerate(self.current_strokes, 1):
            for p, (x,y) in enumerate(stroke_data["points"], 1):
                out.append({
                    "sign_id": sign_id,
                    "location": location,
                    "latitude": self.fmt_coord(self.latitude.get()),
                    "longitude": self.fmt_coord(self.longitude.get()),
                    "object_type": self.object_type.get().strip(),
                    "object_number": self.object_number.get().strip(),
                    "date_start": self.date_start.get().strip(),
                    "date_end": self.date_end.get().strip(),
                    "image": image_name,
                    "direction": self.direction.get(),
                    "graphemes": graphemes,
                    "instance": instance,
                    "certainty": cert,
                    "view_rotation_deg": f"{self.view_rotation_deg:.1f}",
                    "annotator": (
                        self.editing_annotator
                        if self.editing_annotator is not None
                        else self.current_annotator.get().strip()
                    ),
                    "stroke": s,
                    "component": stroke_data["component"],
                    "point": p,
                    "x": round(x,2),
                    "y": round(y,2),
                })
        return out

    def _reset_sign_metadata_for_next_sign(self):
        """Reset sign-specific fields while preserving inscription/object metadata."""
        self.updating_fields = True
        try:
            self.graphemes.set("")
            self.component.set("")
            self.incomplete.set(False)
        finally:
            self.updating_fields = False
        self.last_graphemes_value = ""

    def _clear_saved_navigation_after_finish(self):
        """Clear stale Saved-pane selection without navigating the editing view.

        Finishing a new or edited sign rebuilds the Saved signs / inscriptions
        trees.  If an older sign or inscription is still selected, Tk can queue
        a <<TreeviewSelect>> event while the trees are rebuilt.  That event may
        reopen the selected inscription's first sign, restoring its rotation
        and viewport.  Finishing a sign is a save operation, not navigation,
        so clear both selections while their callbacks are suppressed.
        """
        self._begin_selection_suppression(
            saved=True, inscriptions=True
        )
        try:
            if hasattr(self, "tree"):
                selection = self.tree.selection()
                if selection:
                    self.tree.selection_remove(selection)
            if hasattr(self, "inscription_tree"):
                selection = self.inscription_tree.selection()
                if selection:
                    self.inscription_tree.selection_remove(selection)
        except Exception:
            pass

    def _finish_saved_navigation_refresh(self, sign_id):
        """Refresh and select the saved sign without navigating the editing view."""
        self._clear_saved_navigation_after_finish()
        self.refresh_sign_table()
        # Keep the finished sign visibly selected and available for subsequent
        # actions. Selection callbacks remain suppressed until Tk has processed
        # the queued events, so this does not reopen its image or refill the
        # sign metadata fields that are reset for the next drawing.
        self._select_saved_item_for_sign(sign_id)

    def finish_sign(self):
        if self.current_view != "entry":
            self.status.set("Stroke editing is disabled in normalized visualization mode.")
            return
        if self._is_editing():
            return self.finish_editing()
        if self.current_points:
            if len(self.current_points) >= 2:
                self.finish_stroke()
            else:
                self.status.set("Unfinished one-point stroke; right-click or Esc to remove it.")
                return
        if not self.current_strokes:
            self.status.set("No strokes to save.")
            return

        location = self._nfc(self.ins.get()).strip()
        graphemes = self._nfc(self.graphemes.get()).strip()
        if not graphemes:
            self.status.set("Enter grapheme(s), e.g. a, ø, ŋ, or e+m.")
            return
        try:
            graphemes = self._normalized_grapheme_expression(graphemes)
        except ValueError as exc:
            self.status.set(str(exc))
            return
        self.graphemes.set(graphemes)
        if self._is_ambiguous_grapheme(graphemes):
            primary = self._primary_grapheme(graphemes)
            for stroke_data in self.current_strokes:
                stroke_data["component"] = primary

        cert = "incomplete" if self.incomplete.get() else "complete"
        k = (
            location,
            self.object_type.get().strip(),
            self.object_number.get().strip(),
            self._primary_grapheme(graphemes),
        )
        self.counts[k] = self.counts.get(k, 0) + 1
        instance = self.counts[k]
        sid = short_id()

        self.rows.extend(self.make_rows_for_current_buffer(sid, instance))
        self.current_strokes = []
        self.current_points = []
        self._leave_drawing_mode()
        # Saving a sign must not navigate back to a previously selected sign or
        # inscription.  Keep the current image, zoom, pan and view rotation.
        self._finish_saved_navigation_refresh(sid)
        self._reset_sign_metadata_for_next_sign()
        self.status.set(
            f"Saved {self.display_sign_identifier(graphemes, cert, instance)}."
        )
        self.draw(refresh_table=False)

    # ---------- edit/delete/go ----------

    def _try_open_image_for_rows(self, rows):
        """Open the image for a saved sign if possible.
        We only store the filename in the CSV, so search likely folders."""
        if not rows:
            return False
        image_name = rows[0].get("image", "")
        if not image_name:
            return False
        if self.path and os.path.basename(self.path) == image_name:
            return True

        candidates = []
        candidates.append(os.path.join(self.image_dir, image_name))
        candidates.append(os.path.join(self.legacy_image_dir, image_name))
        candidates.append(os.path.join(self.app_dir, image_name))
        if self.path:
            candidates.append(os.path.join(os.path.dirname(self.path), image_name))
        if self.csv_dir:
            candidates.append(os.path.join(self.csv_dir, image_name))
            candidates.append(os.path.join(self.csv_dir, "images", image_name))
            candidates.append(
                os.path.join(self.csv_dir, "runic images", image_name)
            )
        if self.project_folder:
            candidates.append(
                os.path.join(self.project_folder, "images", image_name)
            )
            candidates.append(
                os.path.join(
                    self.project_folder, "runic images", image_name
                )
            )
        candidates.append(os.path.abspath(image_name))

        for candidate in candidates:
            if candidate and os.path.exists(candidate):
                self.path = candidate
                self.image = Image.open(candidate).convert("RGB")
                self.scale = min(
                    max(self.c.winfo_width(),1000) / self.image.width,
                    max(self.c.winfo_height(),700) / self.image.height
                )
                self.ox = self.oy = 0
                self.update_current_image_label()
                return True
        self.status.set(f"Could not find image {image_name} in {self.image_dir}. Open it manually first.")
        return False

    def go_to_selected_sign(self):
        sid = self.selected_sign_id()
        if not sid:
            self.status.set("No saved sign selected.")
            return
        rows = self.group_rows_by_sign().get(sid, [])
        if not rows:
            return

        if not self._try_open_image_for_rows(rows):
            return

        # Work in expanded rotated-image coordinates, matching draw() and
        # cursor-centred wheel zoom. Original-image coordinates only centre
        # correctly when the editing view is not rotated.
        rotated_points = [
            self._image_to_rotated(float(r["x"]), float(r["y"]))
            for r in rows
        ]
        xs = [point[0] for point in rotated_points]
        ys = [point[1] for point in rotated_points]
        xmin, xmax = min(xs), max(xs)
        ymin, ymax = min(ys), max(ys)
        bw, bh = max(xmax - xmin, 1), max(ymax - ymin, 1)
        canvas_w = max(self.c.winfo_width(), 100)
        canvas_h = max(self.c.winfo_height(), 100)

        self.scale = min(
            canvas_w / (bw * 3.0),
            canvas_h / (bh * 3.0),
            8.0
        )
        cx = (xmin + xmax) / 2.0
        cy = (ymin + ymax) / 2.0
        self.ox = canvas_w / 2.0 - cx * self.scale
        self.oy = canvas_h / 2.0 - cy * self.scale
        self.status.set("Zoomed to selected sign.")
        self.draw(refresh_table=False)

    def edit_selected_sign_from_any_mode(self):
        if not self._context_change_allowed():
            return
        """Open the selected sign in Sign editing, regardless of active mode."""
        sid = self.selected_sign_id()
        if not sid:
            self.status.set("No saved sign selected.")
            return
        if self.current_view != "entry":
            self.return_to_entry_view()
            if sid in self.tree.get_children(""):
                self.tree.selection_set(sid)
                self.tree.focus(sid)
                self._scroll_saved_sign_near_top(sid)
        self.root.after_idle(self.edit_selected_sign)

    def edit_selected_sign(self):
        sid = self.selected_sign_id()
        if not sid:
            self.status.set("No saved sign selected.")
            return
        if self.current_strokes or self.current_points:
            if not messagebox.askyesno("Discard active drawing?", "Discard current unfinished drawing and edit the selected sign?"):
                return

        rows = self.group_rows_by_sign().get(sid, [])
        if not rows:
            return

        if not self._try_open_image_for_rows(rows):
            return

        first = rows[0]
        self.editing_instance = int(first["instance"]) if str(first.get("instance","")).isdigit() else 1
        self.editing_annotator = first.get("annotator", "")
        selected_annotator = str(self.editing_annotator or "").strip()
        if selected_annotator and selected_annotator not in self.annotators:
            self.annotators.append(selected_annotator)
        self.current_annotator.set(selected_annotator)
        self._annotator_edit_original = selected_annotator
        self._refresh_annotator_selector()
        self.updating_fields = True
        try:
            self.ins.set(first.get("location",""))
            self.latitude.set(first.get("latitude",""))
            self.longitude.set(first.get("longitude",""))
            self.object_type.set(first.get("object_type",""))
            self.object_number.set(first.get("object_number",""))
            self.direction.set(first.get("direction","LTR"))
            self.graphemes.set(first.get("graphemes",""))
            self.component.set(first.get("component", first.get("graphemes","")))
            self.incomplete.set(first.get("certainty","complete") == "incomplete")
            try:
                self.view_rotation_deg = float(
                    first.get("view_rotation_deg", "0") or 0
                )
            except (TypeError, ValueError):
                self.view_rotation_deg = 0.0
            self.edit_original_view_rotation = self.view_rotation_deg
            self._rotated_image_size = None
            self.rotation_status.set(
                f"Rotation: {self.view_rotation_deg:g}°"
            )
        finally:
            self.updating_fields = False
            self.metadata_dirty = False

        by_stroke = {}
        components = {}
        for r in rows:
            st = int(r["stroke"])
            by_stroke.setdefault(st, []).append(r)
            components[st] = r.get("component", first.get("graphemes",""))

        self.current_strokes = []
        for st, rr in sorted(by_stroke.items()):
            rr.sort(key=lambda z: int(z["point"]))
            pts = [(float(z["x"]), float(z["y"])) for z in rr]
            self.current_strokes.append({"points": pts, "component": components.get(st, first.get("graphemes",""))})

        self.current_points = []
        self.editing_sign_id = sid
        self._enter_edit_mode()
        self.rows = [r for r in self.rows if r["sign_id"] != sid]
        self.refresh_sign_table()
        self.status.set("Editing selected sign. Adjust strokes, then Finish sign.")
        self.draw(refresh_table=False)

    def finish_editing(self):
        if self.editing_sign_id is None:
            self.status.set("Not currently editing a saved sign.")
            return
        if self.current_points:
            if len(self.current_points) >= 2:
                self.finish_stroke()
            else:
                self.status.set("Unfinished one-point stroke; right-click or Esc to remove it.")
                return
        if not self.current_strokes:
            self.status.set("No strokes in edited sign.")
            return

        sid = self.editing_sign_id
        instance = self.editing_instance or 1

        # For an ordinary (non-bindrune) sign, the Component field applies to
        # every stroke. This ensures a renamed sign/component is actually saved.
        graphemes = self._nfc(self.graphemes.get()).strip()
        try:
            graphemes = self._normalized_grapheme_expression(graphemes)
        except ValueError as exc:
            self.status.set(str(exc))
            return
        self.graphemes.set(graphemes)
        component = (
            self._primary_grapheme(graphemes)
            if self._is_ambiguous_grapheme(graphemes)
            else self.component.get().strip() or graphemes
        )
        if "+" not in graphemes:
            for stroke_data in self.current_strokes:
                stroke_data["component"] = component

        self.rows.extend(self.make_rows_for_current_buffer(sid, instance))
        self.current_strokes = []
        self.current_points = []
        self.editing_sign_id = None
        self.editing_instance = None
        self.editing_annotator = None
        self._leave_edit_mode()
        self.rebuild_counts()
        # Finishing an edit is likewise a save operation, not a request to
        # reopen the inscription's first sign. Preserve the current viewport.
        self._finish_saved_navigation_refresh(sid)
        self._reset_sign_metadata_for_next_sign()
        self.update_metadata_button_visibility()
        self.status.set("Finished sign.")
        self.draw(refresh_table=False)

    def delete_selected_sign(self):
        if self._is_editing():
            self.status.set("Finish the current edit first.")
            return
        sid = self.selected_sign_id()
        if not sid:
            self.status.set("No saved sign selected.")
            return
        before = len(self.rows)
        self.rows = [r for r in self.rows if r["sign_id"] != sid]
        self.rebuild_counts()
        self.refresh_sign_table()
        self.status.set(f"Deleted {before-len(self.rows)} point rows.")
        self.draw(refresh_table=False)

    # ---------- undo/navigation ----------

    def undo_point(self):
        if self.current_view != "entry":
            return
        if self.current_points:
            self.current_points.pop()
            self.status.set(f"Current stroke: {len(self.current_points)} point(s).")
        elif self.current_strokes:
            self.status.set("No active points. Use Undo stroke to remove the last completed stroke.")
        self._release_drawing_lock_if_empty()
        self.draw(refresh_table=False)

    def undo_stroke(self):
        if self.current_view != "entry":
            return
        if self.current_points:
            self.current_points = []
        elif self.current_strokes:
            self.current_strokes.pop()
        self._release_drawing_lock_if_empty()
        self.draw(refresh_table=False)

    def cancel_current_stroke(self):
        if self.current_view != "entry":
            return
        self.current_points = []
        self._release_drawing_lock_if_empty()
        self.status.set("Current stroke cancelled.")
        self.draw(refresh_table=False)

    def wheel(self, e):
        """Zoom smoothly around the cursor in displayed-image coordinates."""
        if self.image is None:
            return

        rotated_x = (e.x - self.ox) / self.scale
        rotated_y = (e.y - self.oy) / self.scale

        factor = 1.15 if e.delta > 0 else 1 / 1.15
        new_scale = max(0.1, min(12.0, self.scale * factor))
        if abs(new_scale - self.scale) <= 1e-12:
            return "break"

        self.scale = new_scale
        self.ox = e.x - rotated_x * self.scale
        self.oy = e.y - rotated_y * self.scale
        self.draw(refresh_table=False)
        return "break"

    def pan_start(self, e):
        self.pan = (e.x,e.y,self.ox,self.oy)

    def pan_move(self, e):
        if self.pan is None:
            return
        x,y,ox,oy = self.pan
        self.ox = ox + e.x - x
        self.oy = oy + e.y - y
        self.draw(refresh_table=False)

    # ---------- matrix geometry ----------

    def _matrix_21_node_coordinates(self):
        """Fixed zero-based node ids for the displayed 1–21 cross matrix."""
        layout = [(1,0),(2,0),(3,0), (0,1),(1,1),(2,1),(3,1),(4,1), (0,2),(1,2),(2,2),(3,2),(4,2), (0,3),(1,3),(2,3),(3,3),(4,3), (1,4),(2,4),(3,4)]
        return {i: xy for i, xy in enumerate(layout)}

    def _tokens(self, s):
        return {x.strip() for x in str(s).split("+") if x.strip()}

    def _is_ambiguous_grapheme(self, value):
        """Return whether a stored Sign(s) value records alternatives."""
        return "," in str(value or "")

    def _primary_grapheme(self, value):
        """Return the first alternative used by this intermediate version."""
        return self._nfc(value).split(",", 1)[0].strip()

    def _normalized_grapheme_expression(self, value):
        """Validate and normalize bindrune or ambiguity notation.

        Commas record alternative readings, while plus signs retain their
        existing bindrune meaning. Combining both syntaxes in one physical
        sign is deliberately unsupported in this intermediate version.
        """
        raw = self._nfc(value).strip()
        if not raw:
            raise ValueError("Enter at least one sign value.")
        if "," in raw and "+" in raw:
            raise ValueError(
                "Use either commas for ambiguous values or plus signs for "
                "bindrunes, not both."
            )
        separator = "," if "," in raw else "+" if "+" in raw else None
        if separator is None:
            return raw
        values = [part.strip() for part in raw.split(separator)]
        if any(not part for part in values):
            kind = "ambiguous value" if separator == "," else "bindrune"
            raise ValueError(f"Every {kind} component must contain a sign.")
        return separator.join(values)

    def _analysis_unit_is_included(self, unit, include_incomplete=None):
        """Apply the shared completeness and ambiguity inclusion policy."""
        if include_incomplete is None:
            include_incomplete = self.analysis_include_incomplete.get()
        if (
            not include_incomplete
            and unit.get("certainty", "complete") != "complete"
        ):
            return False
        if (
            not self.analysis_include_ambiguous.get()
            and unit.get("ambiguous", False)
        ):
            return False
        return True

    def _clean_points(self, pts):
        pts = [(float(x), float(y)) for x, y in pts]
        if len(pts) < 2:
            return pts
        out = [pts[0]]
        for p in pts[1:]:
            if ((p[0]-out[-1][0])**2 + (p[1]-out[-1][1])**2) ** 0.5 > 1:
                out.append(p)
        return out

    def _build_normalized_units(self):
        units = []
        for sid, rows in self.group_rows_by_sign().items():
            if not rows:
                continue
            first = rows[0]
            graphemes = first.get("graphemes", "")
            primary_grapheme = self._primary_grapheme(graphemes)
            ambiguous = self._is_ambiguous_grapheme(graphemes)
            gs = self._tokens(graphemes)

            def add_unit(gr, selected_rows, from_bindrune):
                by_stroke = {}
                for r in selected_rows:
                    by_stroke.setdefault(int(r["stroke"]), []).append(r)
                strokes = []
                for st, rr in sorted(by_stroke.items()):
                    rr.sort(key=lambda z: int(z["point"]))
                    pts = self._clean_points([(r["x"], r["y"]) for r in rr])
                    if len(pts) >= 2:
                        strokes.append(pts)
                if not strokes:
                    return

                # Apply the remembered editing-view rotation to the
                # sign geometry before normalization. This lets a manually
                # chosen tracing rotation guide the later automatic
                # rotation correction.
                try:
                    view_angle = float(
                        first.get("view_rotation_deg", "0") or 0
                    )
                except (TypeError, ValueError):
                    view_angle = 0.0
                if abs(view_angle) > 1e-9:
                    allpts0 = [
                        p for stroke in strokes for p in stroke
                    ]
                    centre_x = sum(x for x, _ in allpts0) / len(allpts0)
                    centre_y = sum(y for _, y in allpts0) / len(allpts0)
                    angle = math.radians(view_angle)
                    cos_a = math.cos(angle)
                    sin_a = math.sin(angle)
                    strokes = [[
                        (
                            centre_x + cos_a*(x-centre_x)
                            + sin_a*(y-centre_y),
                            centre_y - sin_a*(x-centre_x)
                            + cos_a*(y-centre_y)
                        )
                        for x, y in stroke
                    ] for stroke in strokes]

                allpts = [p for stroke in strokes for p in stroke]
                if first.get("direction", "LTR") == "RTL":
                    xmin0 = min(p[0] for p in allpts)
                    xmax0 = max(p[0] for p in allpts)
                    xmid = (xmin0 + xmax0) / 2
                    strokes = [[(2*xmid-x, y) for x, y in stroke] for stroke in strokes]

                allpts = [p for stroke in strokes for p in stroke]
                xmin = min(p[0] for p in allpts)
                ymin = min(p[1] for p in allpts)
                ymax = max(p[1] for p in allpts)
                h = max(ymax - ymin, 1e-9)
                norm_strokes = [[((x-xmin)/h, (y-ymin)/h) for x,y in stroke] for stroke in strokes]
                label = self.object_label_from_values(first.get("location",""), first.get("object_type",""), first.get("object_number",""))
                units.append({
                    "sign_id": sid,
                    "label": label,
                    "location": first.get("location", ""),
                    "latitude": first.get("latitude", ""),
                    "longitude": first.get("longitude", ""),
                    "object_type": first.get("object_type", ""),
                    "object_number": first.get("object_number", ""),
                    "date_start": first.get("date_start", ""),
                    "date_end": first.get("date_end", ""),
                    "grapheme": gr,
                    "display_graphemes": graphemes,
                    "ambiguous": ambiguous,
                    "instance": first.get("instance", ""),
                    "certainty": first.get("certainty", "complete"),
                    "matrix_orientation_detection": first.get("matrix_orientation_detection", ""),
                    "from_bindrune": from_bindrune,
                    "strokes": norm_strokes,
                })

            if ambiguous:
                add_unit(primary_grapheme, rows, False)
            elif len(gs) <= 1:
                add_unit(graphemes, rows, False)
            else:
                for gr in sorted(gs):
                    selected = [r for r in rows if gr in self._tokens(r.get("component", ""))]
                    add_unit(gr, selected, True)
        return units

    def render_normalized_comparison(self):
        canvas = self.normalized_canvas
        canvas.delete("all")
        units = [
            u for u in self._build_normalized_units()
            if self._analysis_unit_is_included(
                u, self.normalized_include_incomplete.get()
            )
        ]
        units = self._analysis_normalized_units(
            units,
            correct_rotation=self.normalized_correct_rotation.get(),
            proportion=self.normalized_show_iar.get(),
        )
        if not units:
            canvas.create_text(40, 40, text="No saved signs to visualize.", anchor="w", fill="black")
            canvas.configure(scrollregion=(0, 0, 800, 600))
            return

        coverage = {}
        for unit in units:
            if "+" not in str(unit["grapheme"]):
                coverage.setdefault(unit["grapheme"], set()).add(unit["location"])
        shared = sorted([g for g, locs in coverage.items() if len(locs) >= 2])
        if not shared:
            canvas.create_text(40, 40, text="No grapheme occurs in at least two locations yet.", anchor="w", fill="black")
            canvas.configure(scrollregion=(0, 0, 800, 600))
            return

        colors = [
            "#1f77b4", "#ff7f0e", "#2ca02c", "#d62728", "#9467bd", "#8c564b",
            "#e377c2", "#7f7f7f", "#bcbd22", "#17becf", "#111111", "#a55194",
            "#393b79", "#637939", "#8c6d31", "#843c39"
        ]
        # Fixed Sign Inventory display: 225% rune size, 125% label text.
        # Screen wrapping changes only the flow of signs, not their scale.
        wrap_mode = bool(self.normalized_wrap_to_screen.get())
        symbol_scale = 225.0 / 125.0
        layout_scale = symbol_scale
        # Keep large signs fairly close together; labels slope into the space
        # below rather than requiring proportionally larger horizontal gaps.
        x_step = 70
        y_step = max(72, round(94 * layout_scale))
        if self.normalized_show_derotation_diagnostics.get():
            y_step += 34
        rune_box = 24.0 * symbol_scale
        inventory_font_size = 9
        inventory_text_font = ("Arial", inventory_font_size)
        margin_x, margin_y = 58, 24
        heading_x = 30
        first_sign_x = margin_x
        canvas.update_idletasks()
        if wrap_mode:
            visible_width = max(canvas.winfo_width(), 500)
            usable_right = visible_width - 40
            signs_per_row = max(1, int((usable_right - first_sign_x) // x_step))
        else:
            signs_per_row = None
        y = margin_y
        stroke_color_index = 0
        self.normalized_sign_boxes = {}

        # Recreate the UI-only checkbox controls on every inventory redraw.
        # Destroy the previous embedded widgets explicitly: deleting their canvas
        # window items does not destroy the Tk widgets themselves.
        for widget in getattr(self, "inventory_orientation_widgets", []):
            try:
                widget.destroy()
            except tk.TclError:
                pass
        self.inventory_orientation_widgets = []
        self.inventory_orientation_vars = {}
        if getattr(self, "_inventory_orientation_tooltip", None) is not None:
            try:
                self._inventory_orientation_tooltip.destroy()
            except tk.TclError:
                pass
            self._inventory_orientation_tooltip = None

        def orientation_detection_enabled(grapheme):
            key = self._unicode_key(grapheme)
            for row in self.rows:
                if self._unicode_key(
                    self._primary_grapheme(row.get("graphemes", ""))
                ) == key:
                    value = str(row.get("matrix_orientation_detection", "")).strip().lower()
                    if value in {"1", "true", "yes", "on"}:
                        return True
            return False

        def set_orientation_detection(grapheme, var):
            key = self._unicode_key(grapheme)
            value = "1" if var.get() else ""
            for row in self.rows:
                if self._unicode_key(
                    self._primary_grapheme(row.get("graphemes", ""))
                ) == key:
                    row["matrix_orientation_detection"] = value
            self._refresh_status_line()

        for grapheme in shared:
            vals = [u for u in units if u["grapheme"] == grapheme]
            vals.sort(key=lambda u: (u["label"], int(u["instance"]) if str(u["instance"]).isdigit() else 0))
            # A compact UI-only checkbox sits immediately to the left of the
            # grapheme heading. Its meaning is shown only on hover, keeping the
            # inventory itself visually clean and preventing overlap with signs.
            detect_var = tk.BooleanVar(value=orientation_detection_enabled(grapheme))
            self.inventory_orientation_vars[self._unicode_key(grapheme)] = detect_var
            check = tk.Checkbutton(
                canvas, text="", variable=detect_var,
                command=lambda g=grapheme, v=detect_var: set_orientation_detection(g, v),
                takefocus=False, bg="white", activebackground="white",
                selectcolor="white", highlightthickness=0, bd=0,
                padx=0, pady=0
            )
            self.inventory_orientation_widgets.append(check)

            def show_orientation_tooltip(event, widget=check):
                old_tip = getattr(self, "_inventory_orientation_tooltip", None)
                if old_tip is not None:
                    try:
                        old_tip.destroy()
                    except tk.TclError:
                        pass
                tip = tk.Toplevel(self.root)
                tip.wm_overrideredirect(True)
                tip.attributes("-topmost", True)
                label = ttk.Label(
                    tip, text="Matrix orientation detection",
                    padding=(5, 2), relief="solid", borderwidth=1
                )
                label.pack()
                x = widget.winfo_rootx() + widget.winfo_width() + 4
                y_tip = widget.winfo_rooty() + max(0, widget.winfo_height() // 2 - 10)
                tip.wm_geometry(f"+{x}+{y_tip}")
                self._inventory_orientation_tooltip = tip

            def hide_orientation_tooltip(event=None):
                tip = getattr(self, "_inventory_orientation_tooltip", None)
                if tip is not None:
                    try:
                        tip.destroy()
                    except tk.TclError:
                        pass
                    self._inventory_orientation_tooltip = None

            check.bind("<Enter>", show_orientation_tooltip)
            check.bind("<Leave>", hide_orientation_tooltip)

            # This is an interactive control only. Canvas window items are ignored
            # by the JPG/SVG/PDF exporters.
            canvas.create_window(
                20, y + 28, window=check, anchor="center",
                tags=("inventory_ui_control",)
            )
            canvas.create_text(
                heading_x, y + 28, text=grapheme, anchor="w", fill="black",
                font=("Arial", 18, "bold")
            )

            for j, unit in enumerate(vals):
                if wrap_mode:
                    row_index = j // signs_per_row
                    col_index = j % signs_per_row
                    item_y = y + row_index * y_step
                    x0 = first_sign_x + col_index * x_step
                else:
                    item_y = y
                    x0 = first_sign_x + j * x_step
                tag = f'signid:{unit["sign_id"]}'

                # Square covers the sign only; metadata sits below it.
                square_left = x0 - 8
                square_top = item_y - 8
                square_right = x0 + 42
                square_bottom = item_y + 42

                # Full square is clickable, even in blank areas.
                canvas.create_rectangle(
                    square_left, square_top, square_right, square_bottom,
                    fill="white", outline="",
                    tags=(tag, f'signbox:{unit["sign_id"]}', "normalized_sign")
                )
                self.normalized_sign_boxes[unit["sign_id"]] = (
                    square_left, square_top, square_right, square_bottom
                )

                pts = [p for stroke in unit["strokes"] for p in stroke]
                if pts:
                    ux0 = min(px for px, _ in pts); ux1 = max(px for px, _ in pts)
                    uy0 = min(py for _, py in pts); uy1 = max(py for _, py in pts)
                    uw = max(ux1 - ux0, 1e-9); uh = max(uy1 - uy0, 1e-9)
                    sign_scale = min(rune_box / uw, rune_box / uh)
                    ucx = (ux0 + ux1) / 2.0; ucy = (uy0 + uy1) / 2.0
                else:
                    sign_scale = 1.0; ucx = ucy = 0.0
                rune_cx, rune_cy = x0 + 17, item_y + 17
                for stroke in unit["strokes"]:
                    if self.normalized_colored_strokes.get():
                        color = colors[stroke_color_index % len(colors)]
                        stroke_color_index += 1
                    else:
                        color = "black"
                    coords = []
                    for x, yy in stroke:
                        coords.extend([
                            rune_cx + (x - ucx) * sign_scale,
                            rune_cy + (yy - ucy) * sign_scale
                        ])
                    if len(coords) >= 4:
                        canvas.create_line(
                            *coords, fill=color, width=2, smooth=True,
                            tags=(tag, f'signbox:{unit["sign_id"]}', "normalized_sign")
                        )

                sign_text = self.display_sign_identifier(
                    unit.get("display_graphemes", grapheme),
                    unit.get("certainty", "complete"),
                    unit.get("instance", ""),
                )

                # One canvas text object keeps the label stable under rotation
                # and preserves the combining dot used for incomplete signs.
                # Keep at most two lines, with no colon between metadata and sign.
                full_label = " ".join(
                    value for value in [
                        str(unit.get("label", "")).strip(),
                        sign_text,
                    ] if value
                )
                words = full_label.split()
                if len(words) >= 2:
                    candidates = []
                    for cut in range(1, len(words)):
                        left = " ".join(words[:cut])
                        right = " ".join(words[cut:])
                        candidates.append(
                            (abs(len(left) - len(right)), cut, left, right)
                        )
                    _score, _cut, line1, line2 = min(
                        candidates, key=lambda item: (item[0], item[1])
                    )
                    combined_label = line1 + "\n" + line2
                else:
                    combined_label = full_label

                canvas.create_text(
                    x0 + 4, item_y + 48, text=combined_label,
                    anchor="nw", fill="black", font=inventory_text_font,
                    angle=-35, justify="left",
                    tags=(tag, "normalized_sign")
                )

                if self.normalized_show_derotation_diagnostics.get():
                    variant, mechanism, detail = self._derotation_diagnostic_labels(unit)
                    diag_tag = f'derotation_diag:{unit["sign_id"]}'
                    diag_label = f"{variant}\n{mechanism}"
                    canvas.create_text(
                        x0 + 4, item_y + 82, text=diag_label,
                        anchor="nw", fill="#555555", font=("Arial", 7),
                        angle=-35, justify="left",
                        tags=(tag, diag_tag, "normalized_sign")
                    )

                    def show_derotation_tooltip(event, text=detail):
                        old_tip = getattr(self, "_inventory_orientation_tooltip", None)
                        if old_tip is not None:
                            try:
                                old_tip.destroy()
                            except tk.TclError:
                                pass
                        tip = tk.Toplevel(self.root)
                        tip.wm_overrideredirect(True)
                        tip.attributes("-topmost", True)
                        label = ttk.Label(
                            tip, text=text, padding=(5, 2),
                            relief="solid", borderwidth=1
                        )
                        label.pack()
                        tip.wm_geometry(f"+{event.x_root + 10}+{event.y_root + 10}")
                        self._inventory_orientation_tooltip = tip

                    canvas.tag_bind(diag_tag, "<Enter>", show_derotation_tooltip)
                    canvas.tag_bind(diag_tag, "<Leave>", hide_orientation_tooltip)
            if wrap_mode:
                rows_used = max(1, math.ceil(len(vals) / signs_per_row))
                y += rows_used * y_step
            else:
                y += y_step

        max_items = max(len([u for u in units if u["grapheme"] == g]) for g in shared)
        canvas.update_idletasks()
        if wrap_mode:
            content_right = max(canvas.winfo_width(), first_sign_x + x_step * signs_per_row + 120)
        else:
            content_right = max(1000, margin_x + x_step * max_items + 120)
        content_bottom = max(y, margin_y + y_step)
        # Clean figure bounds exclude the UI-only checkbox widgets.
        self._inventory_export_bbox = (0, 0, content_right, content_bottom)
        canvas.configure(
            scrollregion=(
                0, 0, content_right, content_bottom
            )
        )
        self._highlight_normalized_selection(self.selected_sign_id())

        # Default normalized view starts at the actual content, not in padding.
        if not self.selected_sign_id():
            canvas.xview_moveto(0.0)
            canvas.yview_moveto(0.0)

    # ---------- whole-shape similarity network ----------

    def _resample_normalized_stroke(self, stroke, n=24):
        """Resample a normalized polyline at approximately equal arc-length intervals."""
        if len(stroke) < 2:
            return list(stroke)
        lengths = [0.0]
        for i in range(1, len(stroke)):
            dx = stroke[i][0] - stroke[i-1][0]
            dy = stroke[i][1] - stroke[i-1][1]
            lengths.append(lengths[-1] + math.hypot(dx, dy))
        total = lengths[-1]
        if total <= 0:
            return [stroke[0]] * n

        result = []
        seg = 0
        for j in range(n):
            target = total * j / max(n - 1, 1)
            while seg < len(lengths) - 2 and lengths[seg + 1] < target:
                seg += 1
            left = lengths[seg]
            right = lengths[seg + 1]
            ratio = 0.0 if right == left else (target - left) / (right - left)
            x = stroke[seg][0] + ratio * (stroke[seg + 1][0] - stroke[seg][0])
            y = stroke[seg][1] + ratio * (stroke[seg + 1][1] - stroke[seg][1])
            result.append((x, y))
        return result

    def _unit_shape_cloud(self, unit, points_per_stroke=48):
        cloud = []
        for stroke in unit["strokes"]:
            cloud.extend(
                self._resample_normalized_stroke(
                    stroke, n=points_per_stroke
                )
            )
        return cloud

    def _nearest_distances(self, source, target):
        """Exact Euclidean nearest-neighbour distances.

        NumPy performs the O(n*m) coordinate arithmetic in compiled code.
        The pure-Python implementation is retained as a dependency-free
        fallback and preserves the same metric definition.
        """
        if source is None or target is None or len(source) == 0 or len(target) == 0:
            return []
        if np is not None:
            a = np.asarray(source, dtype=float)
            b = np.asarray(target, dtype=float)
            delta = a[:, None, :] - b[None, :, :]
            d2 = np.einsum("ijk,ijk->ij", delta, delta, optimize=True)
            return np.sqrt(np.min(d2, axis=1)).tolist()

        out = []
        for ax, ay in source:
            best2 = float("inf")
            for bx, by in target:
                dx = ax - bx
                dy = ay - by
                d2 = dx * dx + dy * dy
                if d2 < best2:
                    best2 = d2
                    if best2 == 0.0:
                        break
            out.append(math.sqrt(best2))
        return out

    def _chamfer_shape_distance(self, cloud_a, cloud_b):
        """Symmetric mean nearest-point distance between normalized shape clouds."""
        if not cloud_a or not cloud_b:
            return float("inf")
        da = self._nearest_distances(cloud_a, cloud_b)
        db = self._nearest_distances(cloud_b, cloud_a)
        return (sum(da) / len(da) + sum(db) / len(db)) / 2.0

    def _directional_chamfer_cloud(self, unit, points_per_stroke=48):
        """Return (x, y, axial tangent angle) samples for Directional Chamfer.

        Tangents are estimated from the resampled vector stroke itself.  Angles
        are treated axially, so reversing an annotated stroke changes nothing.
        """
        cloud = []
        for stroke in unit.get("strokes", []):
            pts = self._resample_normalized_stroke(stroke, n=points_per_stroke)
            if not pts:
                continue
            if len(pts) == 1:
                cloud.append((pts[0][0], pts[0][1], 0.0))
                continue
            for i, (x, y) in enumerate(pts):
                if i == 0:
                    dx = pts[1][0] - x
                    dy = pts[1][1] - y
                elif i == len(pts) - 1:
                    dx = x - pts[i-1][0]
                    dy = y - pts[i-1][1]
                else:
                    dx = pts[i+1][0] - pts[i-1][0]
                    dy = pts[i+1][1] - pts[i-1][1]
                if abs(dx) <= 1e-15 and abs(dy) <= 1e-15:
                    theta = 0.0
                else:
                    # Modulo pi makes the tangent axial: theta and theta+pi
                    # are identical, so annotation stroke direction is ignored.
                    theta = math.atan2(dy, dx) % math.pi
                cloud.append((x, y, theta))
        return cloud

    def _cached_directional_chamfer_cloud(self, unit, points_per_stroke=48):
        cache = getattr(self, "_directional_chamfer_cloud_cache", None)
        if cache is None:
            self._directional_chamfer_cloud_cache = {}
            cache = self._directional_chamfer_cloud_cache
        key = (points_per_stroke, self._shape_fingerprint(unit))
        if key not in cache:
            cache[key] = self._directional_chamfer_cloud(
                unit, points_per_stroke=points_per_stroke
            )
        return cache[key]

    def _directional_nearest_costs(self, source, target, lam):
        """Nearest costs in joint position/local-orientation space.

        Spatial coordinates remain in Carve's normalized geometry.  Angular
        mismatch is normalized to [0, 1], where 0 = parallel/antiparallel and
        1 = perpendicular, then scaled by lambda.
        """
        if not source or not target:
            return []
        lam = float(lam)
        half_pi = math.pi / 2.0
        if np is not None:
            a = np.asarray(source, dtype=float)
            b = np.asarray(target, dtype=float)
            dx = a[:, None, 0] - b[None, :, 0]
            dy = a[:, None, 1] - b[None, :, 1]
            spatial2 = dx * dx + dy * dy
            diff = np.abs(a[:, None, 2] - b[None, :, 2])
            diff = np.minimum(diff, math.pi - diff)
            angle_norm = diff / half_pi
            cost2 = spatial2 + (lam * angle_norm) ** 2
            return np.sqrt(np.min(cost2, axis=1)).tolist()

        out = []
        for ax, ay, atheta in source:
            best2 = float("inf")
            for bx, by, btheta in target:
                dx = ax - bx
                dy = ay - by
                diff = abs(atheta - btheta)
                diff = min(diff, math.pi - diff)
                angle_norm = diff / half_pi
                c2 = dx*dx + dy*dy + (lam * angle_norm) ** 2
                if c2 < best2:
                    best2 = c2
            out.append(math.sqrt(best2))
        return out

    def _directional_chamfer_distance(self, cloud_a, cloud_b, lam):
        """Symmetric Directional Chamfer distance for vector rune traces."""
        if not cloud_a or not cloud_b:
            return float("inf")
        if np is not None:
            # The joint position/orientation cost is symmetric. Reuse one
            # point-pair array for both directed minima, preserving the existing
            # arithmetic and Python summation order for the final means.
            a = np.asarray(cloud_a, dtype=float)
            b = np.asarray(cloud_b, dtype=float)
            dx = a[:, None, 0] - b[None, :, 0]
            dy = a[:, None, 1] - b[None, :, 1]
            spatial2 = dx * dx + dy * dy
            diff = np.abs(a[:, None, 2] - b[None, :, 2])
            diff = np.minimum(diff, math.pi - diff)
            angle_norm = diff / (math.pi / 2.0)
            cost2 = spatial2 + (float(lam) * angle_norm) ** 2
            da = np.sqrt(np.min(cost2, axis=1)).tolist()
            db = np.sqrt(np.min(cost2, axis=0)).tolist()
        else:
            da = self._directional_nearest_costs(cloud_a, cloud_b, lam)
            db = self._directional_nearest_costs(cloud_b, cloud_a, lam)
        return (sum(da) / len(da) + sum(db) / len(db)) / 2.0

    def _cached_directional_stroke_clouds(self, unit, points_per_stroke=48):
        """Reuse per-stroke samples without changing sampling or assignment."""
        cache = getattr(self, "_directional_stroke_cloud_cache", None)
        if cache is None:
            cache = self._directional_stroke_cloud_cache = {}
        key = (points_per_stroke, self._exact_stroke_geometry(unit))
        if key not in cache:
            clouds = [
                self._directional_chamfer_cloud(
                    {"strokes": [stroke]}, points_per_stroke=points_per_stroke
                )
                for stroke in unit.get("strokes", []) if stroke
            ]
            if len(cache) >= 2048:
                cache.clear()
            cache[key] = [cloud for cloud in clouds if cloud]
        return cache[key]

    @staticmethod
    def _exact_stroke_geometry(unit):
        """Immutable geometry key: even very small coordinate edits invalidate it."""
        return tuple(tuple((x, y) for x, y in stroke)
                     for stroke in unit.get("strokes", []))

    def _stroke_directional_chamfer_distance(self, unit_a, unit_b, lam=0.50, points_per_stroke=48):
        """Directional Chamfer with a one-to-one whole-stroke assignment.

        Candidate stroke pairs are scored by symmetric Directional Chamfer.
        Hungarian assignment then fixes one correspondence per stroke, so a
        stroke cannot obtain cheap matches from fragments of several strokes.
        Tangents remain axial, hence annotation traversal direction is ignored.
        """
        a = self._cached_directional_stroke_clouds(unit_a, points_per_stroke)
        b = self._cached_directional_stroke_clouds(unit_b, points_per_stroke)
        if not a or not b:
            return float("inf")
        small, large = (a, b) if len(a) <= len(b) else (b, a)
        ns, nl = len(small), len(large)
        costs = [[self._directional_chamfer_distance(sa, lb, lam)
                  for lb in large] for sa in small]
        if ns == nl:
            best = self._hungarian_min_cost(costs)
        else:
            square = [row[:] for row in costs]
            square.extend([[0.0] * nl for _ in range(nl - ns)])
            square_mean = self._hungarian_min_cost(square)
            best = (square_mean * nl) / max(ns, 1)
        # Match the established stroke-aware curve-distance treatment of
        # genuinely missing/additional strokes.
        return best + 0.45 * (nl - ns)

    def _shape_fingerprint(self, unit):
        return tuple(
            tuple((round(x, 5), round(y, 5)) for x, y in stroke)
            for stroke in unit.get("strokes", [])
        )

    def _cached_unit_shape_cloud(self, unit, points_per_stroke=48):
        cache = getattr(self, "_unit_shape_cloud_cache", None)
        if cache is None:
            self._unit_shape_cloud_cache = {}
            cache = self._unit_shape_cloud_cache
        key = (points_per_stroke, self._shape_fingerprint(unit))
        if key not in cache:
            cache[key] = self._unit_shape_cloud(
                unit, points_per_stroke=points_per_stroke
            )
        return cache[key]

    def _cached_curve_strokes(self, unit, n=20):
        cache = getattr(self, "_curve_strokes_cache", None)
        if cache is None:
            self._curve_strokes_cache = {}
            cache = self._curve_strokes_cache
        key = (n, self._shape_fingerprint(unit))
        if key not in cache:
            cache[key] = [
                self._curve_resample(stroke, n=n)
                for stroke in unit.get("strokes", [])
            ]
        return cache[key]

    def _curve_resample(self, stroke, n=20):
        """Equal arc-length resampling for curve distances."""
        if len(stroke) < 2:
            return list(stroke)
        lengths = [0.0]
        for i in range(1, len(stroke)):
            lengths.append(
                lengths[-1] + math.hypot(
                    stroke[i][0] - stroke[i-1][0],
                    stroke[i][1] - stroke[i-1][1]
                )
            )
        total = lengths[-1]
        if total <= 1e-12:
            return [stroke[0]] * n

        result = []
        seg = 0
        for j in range(n):
            target = total * j / max(n - 1, 1)
            while seg < len(lengths) - 2 and lengths[seg + 1] < target:
                seg += 1
            left = lengths[seg]
            right = lengths[seg + 1]
            t = 0.0 if right == left else (target - left) / (right - left)
            result.append((
                stroke[seg][0] + t * (stroke[seg + 1][0] - stroke[seg][0]),
                stroke[seg][1] + t * (stroke[seg + 1][1] - stroke[seg][1])
            ))
        return result

    def _discrete_frechet(self, curve_a, curve_b, squared_distances=None, reverse=False):
        """Discrete Fréchet distance using squared distances internally.

        sqrt is monotone, so the min/max dynamic programme is exactly
        equivalent while avoiding a square root at every DP cell.
        """
        n = len(curve_a)
        m = len(curve_b)
        if not n or not m:
            return float("inf")

        prev = [0.0] * m
        for i, (ax, ay) in enumerate(curve_a):
            cur = [0.0] * m
            if squared_distances is None:
                row = []
                for bx, by in curve_b:
                    dx = ax - bx
                    dy = ay - by
                    row.append(dx * dx + dy * dy)
            else:
                row = squared_distances[i]
            for j, d2 in enumerate(reversed(row) if reverse else row):
                if i == 0 and j == 0:
                    cur[j] = d2
                elif i == 0:
                    cur[j] = max(cur[j - 1], d2)
                elif j == 0:
                    cur[j] = max(prev[j], d2)
                else:
                    cur[j] = max(min(prev[j], prev[j - 1], cur[j - 1]), d2)
            prev = cur
        return math.sqrt(prev[-1])

    def _average_dtw_curve_distance(self, curve_a, curve_b):
        """DTW mean local cost along the optimal warping path.

        Uses rolling rows instead of full Python matrices. Tie-breaking is
        preserved: up, then left, then diagonal for equal (cost, steps).
        """
        n = len(curve_a)
        m = len(curve_b)
        if not n or not m:
            return float("inf")

        inf = float("inf")
        prev_cost = [inf] * (m + 1)
        prev_steps = [0] * (m + 1)
        prev_cost[0] = 0.0

        for i in range(1, n + 1):
            ax, ay = curve_a[i - 1]
            cur_cost = [inf] * (m + 1)
            cur_steps = [0] * (m + 1)
            for j in range(1, m + 1):
                bx, by = curve_b[j - 1]
                local = math.hypot(ax - bx, ay - by)

                # Same candidate order as the original implementation:
                # up, left, diagonal.
                c0, s0 = prev_cost[j], prev_steps[j]
                c1, s1 = cur_cost[j - 1], cur_steps[j - 1]
                c2, s2 = prev_cost[j - 1], prev_steps[j - 1]

                pc, ps = c0, s0
                if (c1, s1) < (pc, ps):
                    pc, ps = c1, s1
                if (c2, s2) < (pc, ps):
                    pc, ps = c2, s2

                cur_cost[j] = local + pc
                cur_steps[j] = ps + 1

            prev_cost, prev_steps = cur_cost, cur_steps

        return prev_cost[m] / max(prev_steps[m], 1)


    def _sampled_stroke_curve_distance(self, a, b, metric):
        """Direction-invariant distance for already-resampled stroke curves."""
        if metric == "Fréchet":
            # Reversing a stroke changes traversal, not its point-pair costs.
            squared = []
            for ax, ay in a:
                row = []
                for bx, by in b:
                    dx = ax - bx
                    dy = ay - by
                    row.append(dx * dx + dy * dy)
                squared.append(row)
            direct = self._discrete_frechet(a, b, squared)
            reverse = self._discrete_frechet(a, b, squared, reverse=True)
        else:
            direct = self._average_dtw_curve_distance(a, b)
            reverse = self._average_dtw_curve_distance(a, list(reversed(b)))
        return min(direct, reverse)

    def _stroke_assignment_curve_distance(self, unit_a, unit_b, metric):
        """Minimum-cost stroke assignment for Fréchet or DTW rune distance.

        The smaller stroke set is matched one-to-one into the larger set.
        Each candidate stroke pair is compared in both traversal directions,
        so annotation direction is irrelevant. A Hungarian assignment gives
        the same optimum as exhaustive permutation search without factorial
        growth.
        """
        strokes_a = self._cached_curve_strokes(unit_a, n=20)
        strokes_b = self._cached_curve_strokes(unit_b, n=20)
        if not strokes_a or not strokes_b:
            return float("inf")

        small, large = strokes_a, strokes_b
        if len(strokes_a) > len(strokes_b):
            small, large = strokes_b, strokes_a

        ns = len(small)
        nl = len(large)

        pair_cost = [
            [
                self._sampled_stroke_curve_distance(sa, lb, metric)
                for lb in large
            ]
            for sa in small
        ]

        # Minimum one-to-one stroke assignment. The former implementation
        # enumerated all permutations up to six strokes. Padding with zero-cost
        # dummy rows lets the existing Hungarian solver find the identical
        # rectangular assignment in O(n^3), without factorial growth.
        if ns == nl:
            best = self._hungarian_min_cost(pair_cost)
        else:
            square_cost = [row[:] for row in pair_cost]
            square_cost.extend([[0.0] * nl for _ in range(nl - ns)])
            square_mean = self._hungarian_min_cost(square_cost)
            best = (square_mean * nl) / max(ns, 1)

        unmatched = nl - ns
        # Missing or additional strokes remain strongly diagnostic.
        return best + 0.45 * unmatched

    @staticmethod
    def _tangent_vectors(curve):
        """Unit tangent vectors for an already resampled stroke curve.

        Central differences are used internally and one-sided differences at
        the endpoints. Degenerate local segments fall back to (0, 0).
        """
        n = len(curve)
        if n == 0:
            return []
        if n == 1:
            return [(0.0, 0.0)]
        tangents = []
        for i in range(n):
            if i == 0:
                dx = curve[1][0] - curve[0][0]
                dy = curve[1][1] - curve[0][1]
            elif i == n - 1:
                dx = curve[-1][0] - curve[-2][0]
                dy = curve[-1][1] - curve[-2][1]
            else:
                dx = curve[i + 1][0] - curve[i - 1][0]
                dy = curve[i + 1][1] - curve[i - 1][1]
            length = math.hypot(dx, dy)
            if length <= 1e-12:
                tangents.append((0.0, 0.0))
            else:
                tangents.append((dx / length, dy / length))
        return tangents

    def _sampled_tangent_stroke_distance(self, curve_a, curve_b):
        """Position-aware tangent distance for two resampled strokes.

        Local tangent orientation is the dominant term (75%); normalized
        point position contributes 25% so that otherwise parallel strokes or
        branches attached at different places are not treated as identical.
        Tangent orientation is axial (the sign of the tangent vector is
        ignored), reflecting that annotation direction is not historical
        carving direction. The candidate stroke is nevertheless evaluated in
        both traversal directions so corresponding positions remain direction
        invariant as well.
        """
        if not curve_a or not curve_b:
            return float("inf")

        def directed_cost(a, b):
            n = min(len(a), len(b))
            if n <= 0:
                return float("inf")
            a = a[:n]
            b = b[:n]
            ta = self._tangent_vectors(a)
            tb = self._tangent_vectors(b)
            total = 0.0
            for (ax, ay), (bx, by), (tax, tay), (tbx, tby) in zip(a, b, ta, tb):
                # Axial tangent difference: 0 for parallel/antiparallel local
                # directions, 1 for a 90-degree difference.
                if (tax == 0.0 and tay == 0.0) or (tbx == 0.0 and tby == 0.0):
                    tangent_cost = 0.0
                else:
                    dot = max(-1.0, min(1.0, tax * tbx + tay * tby))
                    angle = math.acos(abs(dot))
                    tangent_cost = angle / (0.5 * math.pi)

                # Coordinates have already passed through Carve's selected
                # normalization, so Euclidean position is directly comparable.
                position_cost = math.hypot(ax - bx, ay - by)
                total += 0.75 * tangent_cost + 0.25 * position_cost
            return total / n

        direct = directed_cost(curve_a, curve_b)
        reverse = directed_cost(curve_a, list(reversed(curve_b)))
        return min(direct, reverse)

    def _stroke_assignment_tangent_distance(self, unit_a, unit_b):
        """Experimental rune distance based on matched stroke tangents.

        It mirrors the stroke-assignment logic of Fréchet/DTW: the smaller
        stroke set is matched one-to-one into the larger set, annotation
        direction is ignored, and unmatched strokes receive the same 0.45
        structural penalty. No extra rotation, scale, reflection or
        translation is introduced beyond Carve's selected normalization.
        """
        strokes_a = self._cached_curve_strokes(unit_a, n=20)
        strokes_b = self._cached_curve_strokes(unit_b, n=20)
        if not strokes_a or not strokes_b:
            return float("inf")

        small, large = strokes_a, strokes_b
        if len(strokes_a) > len(strokes_b):
            small, large = strokes_b, strokes_a

        ns = len(small)
        nl = len(large)
        pair_cost = [
            [self._sampled_tangent_stroke_distance(sa, lb) for lb in large]
            for sa in small
        ]

        if nl <= 6:
            assignments = itertools.permutations(range(nl), ns)
        else:
            def key(stroke):
                cx = sum(x for x, y in stroke) / len(stroke)
                cy = sum(y for x, y in stroke) / len(stroke)
                length = sum(
                    math.hypot(
                        stroke[i][0] - stroke[i - 1][0],
                        stroke[i][1] - stroke[i - 1][1]
                    )
                    for i in range(1, len(stroke))
                )
                return (round(cx, 3), round(cy, 3), -length)

            small_order = sorted(range(ns), key=lambda i: key(small[i]))
            large_order = sorted(range(nl), key=lambda i: key(large[i]))
            chosen = [None] * ns
            for rank, i in enumerate(small_order):
                chosen[i] = large_order[rank]
            assignments = [tuple(chosen)]

        best = float("inf")
        for assignment in assignments:
            value = sum(pair_cost[i][assignment[i]] for i in range(ns)) / max(ns, 1)
            if value < best:
                best = value

        return best + 0.45 * (nl - ns)

    def _fixed_arc_length_sample(self, unit, n=48):
        """Sample a fixed-size point cloud approximately uniformly by arc length.

        A fixed point count makes Shape Context correspondence well-defined
        across signs with different numbers of annotated strokes.
        """
        strokes = [
            stroke for stroke in unit.get("strokes", [])
            if len(stroke) >= 2
        ]
        if not strokes:
            return []

        lengths = []
        for stroke in strokes:
            length = sum(
                math.hypot(
                    stroke[i][0] - stroke[i - 1][0],
                    stroke[i][1] - stroke[i - 1][1]
                )
                for i in range(1, len(stroke))
            )
            lengths.append(max(length, 1e-12))

        total = sum(lengths)
        raw = [n * length / total for length in lengths]
        counts = [max(2, int(math.floor(value))) for value in raw]

        # Bring the allocation back to exactly n points.
        while sum(counts) > n:
            candidates = [i for i, c in enumerate(counts) if c > 2]
            if not candidates:
                break
            i = max(candidates, key=lambda k: counts[k] - raw[k])
            counts[i] -= 1
        while sum(counts) < n:
            i = max(
                range(len(counts)),
                key=lambda k: raw[k] - counts[k]
            )
            counts[i] += 1

        cloud = []
        for stroke, count in zip(strokes, counts):
            cloud.extend(self._resample_normalized_stroke(stroke, count))
        return cloud

    def _hungarian_min_cost(self, cost):
        """Minimum square assignment cost, O(n^3), without SciPy dependency."""
        n = len(cost)
        if n == 0:
            return 0.0
        m = len(cost[0])
        if n != m:
            raise ValueError("Shape Context assignment requires a square matrix")

        # Potentials-based Hungarian algorithm (1-indexed internally).
        u = [0.0] * (n + 1)
        v = [0.0] * (m + 1)
        p = [0] * (m + 1)
        way = [0] * (m + 1)

        for i in range(1, n + 1):
            p[0] = i
            j0 = 0
            minv = [float("inf")] * (m + 1)
            used = [False] * (m + 1)
            while True:
                used[j0] = True
                i0 = p[j0]
                delta = float("inf")
                j1 = 0
                for j in range(1, m + 1):
                    if used[j]:
                        continue
                    cur = cost[i0 - 1][j - 1] - u[i0] - v[j]
                    if cur < minv[j]:
                        minv[j] = cur
                        way[j] = j0
                    if minv[j] < delta:
                        delta = minv[j]
                        j1 = j
                for j in range(m + 1):
                    if used[j]:
                        u[p[j]] += delta
                        v[j] -= delta
                    else:
                        minv[j] -= delta
                j0 = j1
                if p[j0] == 0:
                    break

            while True:
                j1 = way[j0]
                p[j0] = p[j1]
                j0 = j1
                if j0 == 0:
                    break

        assignment = [-1] * n
        for j in range(1, m + 1):
            if p[j]:
                assignment[p[j] - 1] = j - 1

        return sum(cost[i][assignment[i]] for i in range(n)) / n

    def _cached_fixed_arc_length_sample(self, unit, n=48):
        cache = getattr(self, "_fixed_arc_sample_cache", None)
        if cache is None:
            self._fixed_arc_sample_cache = {}
            cache = self._fixed_arc_sample_cache
        key = (n, self._shape_fingerprint(unit))
        if key not in cache:
            cache[key] = self._fixed_arc_length_sample(unit, n=n)
        return cache[key]

    def _wasserstein_distance(self, unit_a, unit_b):
        """Equal-mass 2D Wasserstein / optimal-transport distance.

        Each normalized sign is represented by the same fixed number of
        approximately arc-length-uniform sample points. The ground cost is
        Euclidean distance, and the Hungarian assignment gives the minimum
        mean one-to-one transport cost.

        No additional translation, scaling, rotation or reflection is applied:
        Carve's normalization and optional orientation correction remain authoritative.
        """
        points_a = self._cached_fixed_arc_length_sample(unit_a, n=48)
        points_b = self._cached_fixed_arc_length_sample(unit_b, n=48)
        if not points_a or not points_b:
            return float("inf")

        n = min(len(points_a), len(points_b))
        points_a = points_a[:n]
        points_b = points_b[:n]

        cost = [
            [math.hypot(ax - bx, ay - by) for bx, by in points_b]
            for ax, ay in points_a
        ]
        return self._hungarian_min_cost(cost)

    def _modified_hausdorff_distance(self, cloud_a, cloud_b):
        """Modified Hausdorff: max of the two mean nearest-neighbour distances."""
        if not cloud_a or not cloud_b:
            return float("inf")
        da = self._nearest_distances(cloud_a, cloud_b)
        db = self._nearest_distances(cloud_b, cloud_a)
        return max(sum(da) / len(da), sum(db) / len(db))

    def _ray_space_signature(self, unit, rays=72):
        """Stroke-order-blind radial intersection descriptor.

        Rays originate at the centre of the sign's bounding box. Every
        intersection with traced geometry is retained, sorted by radius.
        """
        strokes = [s for s in unit.get("strokes", []) if len(s) >= 2]
        points = [p for s in strokes for p in s]
        if not points:
            return [[] for _ in range(rays)]

        xmin = min(x for x, y in points); xmax = max(x for x, y in points)
        ymin = min(y for x, y in points); ymax = max(y for x, y in points)
        cx = (xmin + xmax) / 2.0
        cy = (ymin + ymax) / 2.0
        scale = max(xmax-xmin, ymax-ymin, 1e-9)
        result = []

        for ri in range(rays):
            a = 2.0 * math.pi * ri / rays
            dx, dy = math.cos(a), math.sin(a)
            hits = []
            for stroke in strokes:
                for k in range(len(stroke)-1):
                    x1, y1 = stroke[k]
                    x2, y2 = stroke[k+1]
                    sx, sy = x2-x1, y2-y1
                    den = dx*sy - dy*sx
                    if abs(den) < 1e-10:
                        continue
                    qx, qy = x1-cx, y1-cy
                    ray_t = (qx*sy - qy*sx) / den
                    seg_t = (qx*dy - qy*dx) / den
                    if ray_t >= -1e-9 and -1e-9 <= seg_t <= 1.0+1e-9:
                        hits.append(max(0.0, ray_t) / scale)
            # Merge duplicate hits at junctions.
            hits.sort()
            merged = []
            for h in hits:
                if not merged or abs(h-merged[-1]) > 1e-4:
                    merged.append(h)
            result.append(merged)
        return result


    def _ray_space_distance(self, unit_a, unit_b):
        """Mean radial intersection distance with unmatched-hit penalty."""
        sa = self._ray_space_signature(unit_a)
        sb = self._ray_space_signature(unit_b)
        costs = []
        unmatched_penalty = 0.35
        for a, b in zip(sa, sb):
            m = min(len(a), len(b))
            # Ordered radial hits provide a natural correspondence.
            c = sum(abs(a[i]-b[i]) for i in range(m))
            c += unmatched_penalty * abs(len(a)-len(b))
            costs.append(c / max(len(a), len(b), 1))
        return sum(costs) / max(len(costs), 1)

    @staticmethod
    def _segment_intersection_parameters(p1, p2, q1, q2):
        """Return segment parameters (t,u) for a proper/touching intersection."""
        rx, ry = p2[0]-p1[0], p2[1]-p1[1]
        sx, sy = q2[0]-q1[0], q2[1]-q1[1]
        den = rx*sy - ry*sx
        if abs(den) < 1e-10:
            return None
        qpx, qpy = q1[0]-p1[0], q1[1]-p1[1]
        tt = (qpx*sy - qpy*sx) / den
        uu = (qpx*ry - qpy*rx) / den
        if -1e-9 <= tt <= 1.0+1e-9 and -1e-9 <= uu <= 1.0+1e-9:
            return tt, uu
        return None

    def _branch_position_signature(self, unit):
        """Rune-structural descriptor of crossings/junction positions.

        Each inter-stroke intersection is represented by the normalized
        distance from the nearest endpoint of each participating stroke plus
        the acute crossing angle. This makes the descriptor invariant to
        annotation stroke direction; stroke labels/order are then discarded
        by sorting the two endpoint distances.
        """
        strokes = [s for s in unit.get("strokes", []) if len(s) >= 2]
        if not strokes:
            return []

        seglens = []
        totals = []
        for s in strokes:
            ls = [math.hypot(s[i+1][0]-s[i][0], s[i+1][1]-s[i][1])
                  for i in range(len(s)-1)]
            seglens.append(ls)
            totals.append(max(sum(ls), 1e-9))

        feats = []
        for i in range(len(strokes)):
            for j in range(i+1, len(strokes)):
                before_i = 0.0
                for ai in range(len(strokes[i])-1):
                    li = seglens[i][ai]
                    before_j = 0.0
                    for bj in range(len(strokes[j])-1):
                        lj = seglens[j][bj]
                        hit = self._segment_intersection_parameters(
                            strokes[i][ai], strokes[i][ai+1],
                            strokes[j][bj], strokes[j][bj+1]
                        )
                        if hit is not None:
                            ti, tj = hit
                            pi = (before_i + ti*li) / totals[i]
                            pj = (before_j + tj*lj) / totals[j]
                            v1 = (strokes[i][ai+1][0]-strokes[i][ai][0],
                                  strokes[i][ai+1][1]-strokes[i][ai][1])
                            v2 = (strokes[j][bj+1][0]-strokes[j][bj][0],
                                  strokes[j][bj+1][1]-strokes[j][bj][1])
                            n1 = math.hypot(*v1); n2 = math.hypot(*v2)
                            dot = abs(v1[0]*v2[0]+v1[1]*v2[1]) / max(n1*n2,1e-9)
                            angle = math.acos(max(-1.0,min(1.0,dot))) / (math.pi/2)
                            # Annotation direction is not graphemic evidence.
                            # A physical junction at p along a stroke becomes
                            # 1-p if that same stroke was traced in reverse.
                            # Represent each position by distance from its
                            # nearest endpoint, then discard stroke identity.
                            pi_inv = min(pi, 1.0 - pi)
                            pj_inv = min(pj, 1.0 - pj)
                            lo, hi = sorted((pi_inv, pj_inv))
                            feats.append((lo, hi, angle))
                        before_j += lj
                    before_i += li

        # Include coarse stroke-count information, but only weakly in distance.
        return feats

    def _cached_branch_position_signature(self, unit):
        cache = getattr(self, "_branch_position_signature_cache", None)
        if cache is None:
            self._branch_position_signature_cache = {}
            cache = self._branch_position_signature_cache
        key = self._shape_fingerprint(unit)
        if key not in cache:
            cache[key] = self._branch_position_signature(unit)
        return cache[key]

    def _branch_position_distance(self, unit_a, unit_b):
        """Assignment-like distance between structural junction descriptors."""
        a = self._cached_branch_position_signature(unit_a)
        b = self._cached_branch_position_signature(unit_b)
        if not a and not b:
            # No inter-stroke junctions: weakly distinguish stroke counts only.
            return 0.08 * abs(len(unit_a.get("strokes", [])) -
                            len(unit_b.get("strokes", [])))
        if not a or not b:
            return 0.45 + 0.08 * abs(len(a)-len(b))

        def featdist(x, y):
            return math.sqrt(
                (x[0]-y[0])**2 + (x[1]-y[1])**2 + 0.35*(x[2]-y[2])**2
            )
        # Symmetric nearest-feature distance; deliberately independent of
        # annotated stroke identities and stroke order.
        da = sum(min(featdist(x,y) for y in b) for x in a) / len(a)
        db = sum(min(featdist(y,x) for x in a) for y in b) / len(b)
        count_penalty = 0.18 * abs(len(a)-len(b))
        return 0.5*(da+db) + count_penalty

    def _sdf_grid(self, unit, size=128):
        """Unsigned 128x128 distance field to the traced centre-lines.

        This intentionally removes stroke identity/order and raster resolution
        dependence from the comparison while retaining visible geometry.
        """
        strokes = [s for s in unit.get("strokes", []) if len(s) >= 2]
        points = [p for s in strokes for p in s]
        if not points:
            return [1.0] * (size*size)

        xmin = min(x for x,y in points); xmax = max(x for x,y in points)
        ymin = min(y for x,y in points); ymax = max(y for x,y in points)
        span = max(xmax-xmin, ymax-ymin, 1e-9)
        pad = 0.08 * span
        xmin -= pad; xmax += pad; ymin -= pad; ymax += pad
        w = max(xmax-xmin, 1e-9); h = max(ymax-ymin, 1e-9)

        segs = []
        for s in strokes:
            for i in range(len(s)-1):
                x1,y1=s[i]; x2,y2=s[i+1]
                segs.append((x1,y1,x2,y2))

        grid = []
        for iy in range(size):
            y = ymin + (iy+0.5)*h/size
            for ix in range(size):
                x = xmin + (ix+0.5)*w/size
                best = float("inf")
                for x1,y1,x2,y2 in segs:
                    vx,vy=x2-x1,y2-y1
                    vv=vx*vx+vy*vy
                    if vv <= 1e-15:
                        d=math.hypot(x-x1,y-y1)
                    else:
                        q=max(0.0,min(1.0,((x-x1)*vx+(y-y1)*vy)/vv))
                        d=math.hypot(x-(x1+q*vx), y-(y1+q*vy))
                    if d < best: best=d
                grid.append(min(best/span, 1.0))
        return grid

    def _cached_sdf_grid(self, unit, size=128):
        """Cache the expensive SDF representation once per analytical shape."""
        cache = getattr(self, "_sdf_grid_cache", None)
        if cache is None:
            self._sdf_grid_cache = {}
            cache = self._sdf_grid_cache
        key = (size, self._shape_fingerprint(unit))
        if key not in cache:
            cache[key] = self._sdf_grid(unit, size=size)
        return cache[key]

    def _sdf_distance(self, unit_a, unit_b):
        """RMS difference between cached unsigned 128x128 distance fields."""
        a = self._cached_sdf_grid(unit_a, size=128)
        b = self._cached_sdf_grid(unit_b, size=128)
        if not a or not b:
            return float("inf")
        return math.sqrt(sum((x-y)*(x-y) for x,y in zip(a,b))/len(a))

    def _distance_between_units(self, unit_a, unit_b, metric):
        metric = str(metric or "Chamfer")
        fp_a = self._shape_fingerprint(unit_a)
        fp_b = self._shape_fingerprint(unit_b)
        key = (
            metric,
            unit_a.get("sign_id", ""), unit_b.get("sign_id", ""),
            fp_a, fp_b
        )
        reverse_key = (
            metric,
            unit_b.get("sign_id", ""), unit_a.get("sign_id", ""),
            fp_b, fp_a
        )
        cache = getattr(self, "_analysis_distance_cache", None)
        if cache is None:
            self._analysis_distance_cache = {}
            cache = self._analysis_distance_cache
        if key in cache:
            return cache[key]
        if reverse_key in cache:
            return cache[reverse_key]

        if metric == "Hausdorff":
            value = self._hausdorff_distance(
                self._cached_hausdorff_cloud(unit_a),
                self._cached_hausdorff_cloud(unit_b)
            )
        elif metric == "Modified Hausdorff":
            value = self._modified_hausdorff_distance(
                self._cached_hausdorff_cloud(unit_a),
                self._cached_hausdorff_cloud(unit_b)
            )
        elif metric == "Ray-space":
            value = self._ray_space_distance(unit_a, unit_b)
        elif metric == "Branch-position":
            value = self._branch_position_distance(unit_a, unit_b)
        elif metric == "SDF":
            value = self._sdf_distance(unit_a, unit_b)
        elif metric == "Procrustes":
            # Efficient stroke assignment followed by one global Procrustes fit,
            # with the explicit symmetric rotation penalty adopted for Carve 1.1.
            value, _angle = self._proc_pair_distance_efficient_details(
                unit_a, unit_b, rotation_penalty=True
            )
        elif metric == "Procrustes + rotation":
            value, angle = self._proc_pair_distance_efficient_details(
                unit_a, unit_b, rotation_penalty=False
            )
            value += self._proc_rotation_penalty_variant(angle, 0.0007)
        elif metric == "Procrustes ++ rotation":
            value, angle = self._proc_pair_distance_efficient_details(
                unit_a, unit_b, rotation_penalty=False
            )
            value += self._proc_rotation_penalty_variant(angle, 0.0010)
        elif metric == "Huber Procrustes":
            value, _angle = self._proc_pair_distance_huber_details(
                unit_a, unit_b, rotation_penalty=True
            )
        elif metric == "Biweight Procrustes":
            value, _angle = self._proc_pair_distance_resistant_details(
                unit_a, unit_b, method="biweight", rotation_penalty=True
            )
        elif metric == "LMS Procrustes":
            value, _angle = self._proc_pair_distance_resistant_details(
                unit_a, unit_b, method="lms", rotation_penalty=True
            )
        elif metric == "ILMS Procrustes":
            value, _angle = self._proc_pair_distance_resistant_details(
                unit_a, unit_b, method="ilms", rotation_penalty=True
            )
        elif metric == "LTS Procrustes":
            value, _angle = self._proc_pair_distance_resistant_details(
                unit_a, unit_b, method="lts", rotation_penalty=True
            )
        elif metric == "Wasserstein":
            value = self._wasserstein_distance(unit_a, unit_b)
        elif metric == "Directional Chamfer":
            value = self._directional_chamfer_distance(
                self._cached_directional_chamfer_cloud(unit_a, points_per_stroke=48),
                self._cached_directional_chamfer_cloud(unit_b, points_per_stroke=48),
                0.50
            )
        elif metric == "Stroke-assigned Directional Chamfer":
            value = self._stroke_directional_chamfer_distance(
                unit_a, unit_b, lam=0.50, points_per_stroke=48
            )
        elif metric.startswith("Directional Chamfer λ="):
            # Backward-compatible support for experimental labels in any
            # session state created by earlier test builds.
            try:
                lam = float(metric.split("=", 1)[1])
            except Exception:
                lam = 0.50
            value = self._directional_chamfer_distance(
                self._cached_directional_chamfer_cloud(unit_a, points_per_stroke=48),
                self._cached_directional_chamfer_cloud(unit_b, points_per_stroke=48),
                lam
            )
        elif metric == "Fréchet":
            value = self._stroke_assignment_curve_distance(
                unit_a, unit_b, "Fréchet"
            )
        elif metric == "DTW":
            value = self._stroke_assignment_curve_distance(
                unit_a, unit_b, "DTW"
            )
        elif metric == "Tangent distance":
            value = self._stroke_assignment_tangent_distance(unit_a, unit_b)
        else:
            value = self._chamfer_shape_distance(
                self._cached_unit_shape_cloud(unit_a),
                self._cached_unit_shape_cloud(unit_b)
            )

        cache_was_empty = not cache
        cache[key] = value
        if cache_was_empty:
            self._update_distance_matrix_export_state()
        return value

    def _distance_matrix_for_units(self, units, metric):
        n = len(units)
        units = self._analysis_normalized_units(
            units,
            correct_rotation="skip",
            trim=self._selected_trimming_passes_enabled(),
            crop=self.analysis_cropping.get(),
            proportion=False,
        )

        # Hybrid Chamfer combines complete DC and SAC distance matrices,
        # rather than changing either constituent algorithm.  Each constituent
        # is divided by its median positive finite pairwise distance first, so
        # the stated weights represent comparable influence rather than raw
        # numerical scale.  This preserves unrestricted local directional
        # matching (DC) alongside coherent whole-stroke correspondence (SAC).
        hybrid_weights = {
            # Final Hybrid Chamfer: 80% unrestricted Directional Chamfer +
            # 20% stroke-assigned Directional Chamfer after robust median scaling.
            "Hybrid Chamfer": (0.80, 0.20),
        }
        if metric in hybrid_weights:
            dc_matrix, dc_finite = self._distance_matrix_for_units(
                units, "Directional Chamfer"
            )
            sac_matrix, sac_finite = self._distance_matrix_for_units(
                units, "Stroke-assigned Directional Chamfer"
            )

            def positive_median(values):
                vals = sorted(v for v in values if math.isfinite(v) and v > 1e-12)
                if not vals:
                    return 1.0
                m = len(vals)
                if m % 2:
                    return vals[m // 2]
                return 0.5 * (vals[m // 2 - 1] + vals[m // 2])

            dc_scale = positive_median(dc_finite)
            sac_scale = positive_median(sac_finite)
            w_dc, w_sac = hybrid_weights[metric]
            matrix = [[0.0] * n for _ in range(n)]
            finite = []
            for i in range(n):
                for j in range(i + 1, n):
                    dc = dc_matrix[i][j]
                    sac = sac_matrix[i][j]
                    if math.isfinite(dc) and math.isfinite(sac):
                        value = w_dc * (dc / dc_scale) + w_sac * (sac / sac_scale)
                    else:
                        value = float("inf")
                    matrix[i][j] = matrix[j][i] = value
                    if math.isfinite(value):
                        finite.append(value)
            return matrix, finite

        matrix = [[0.0]*n for _ in range(n)]
        finite = []
        for i in range(n):
            for j in range(i+1, n):
                value = self._distance_between_units(
                    units[i], units[j], metric
                )
                matrix[i][j] = matrix[j][i] = value
                if math.isfinite(value):
                    finite.append(value)
        return matrix, finite

    def _network_grapheme_default(self):
        sid = self.selected_sign_id()
        if sid:
            rows = self.group_rows_by_sign().get(sid, [])
            if rows:
                return rows[0].get("graphemes", "")
        return self.graphemes.get().strip()

    def _fade_plot_labels_enabled(self):
        return True

    def _plot_label_fill(self):
        return "#666666" if self._fade_plot_labels_enabled() else "black"

    def _draw_normalized_sign_node(
        self, canvas, unit, x, y, tag, colour,
        selected=False, show_label=True, label_text=None,
        radius=18.0, stroke_width=1.5
    ):
        """Draw the same normalized sign-in-circle node in any analysis view."""
        circle = canvas.create_oval(
            x - radius, y - radius,
            x + radius, y + radius,
            fill=colour,
            outline="black",
            width=2 if selected else 1,
            tags=(tag,)
        )

        all_points = [
            point
            for stroke in unit.get("strokes", [])
            for point in stroke
        ]
        if all_points:
            min_x = min(px for px, _ in all_points)
            max_x = max(px for px, _ in all_points)
            min_y = min(py for _, py in all_points)
            max_y = max(py for _, py in all_points)
            shape_w = max(max_x - min_x, 1e-9)
            shape_h = max(max_y - min_y, 1e-9)
            node_size = radius * 1.38
            sign_scale = min(
                node_size / shape_w,
                node_size / shape_h
            )
            centre_x = (min_x + max_x) / 2.0
            centre_y = (min_y + max_y) / 2.0

            for stroke in unit.get("strokes", []):
                coords = []
                for px, py in stroke:
                    coords.extend([
                        x + (px - centre_x) * sign_scale,
                        y + (py - centre_y) * sign_scale
                    ])
                if len(coords) >= 4:
                    canvas.create_line(
                        *coords,
                        fill="black",
                        width=stroke_width,
                        smooth=True,
                        splinesteps=24,
                        capstyle="round",
                        joinstyle="round",
                        tags=(tag,)
                    )

        if show_label:
            if label_text is None:
                label_text = (
                    f'{unit.get("location", "")} '
                    f'{unit.get("instance", "")}'
                ).strip()
                if unit.get("from_bindrune"):
                    label_text
            canvas.create_text(
                x,
                y + radius + 7,
                text=label_text,
                anchor="n",
                font=("Arial", 8),
                width=125,
                justify="center",
                tags=(tag,)
            )
        return circle

    def _site_representatives(
        self, units, metric, use_consensus=False
    ):
        """Return one medoid or average representative per object at a site.

        Medoids remain actual saved signs. Consensus nodes reuse the existing
        cluster-average routine and keep the site's medoid sign_id so that
        clicking the synthetic node selects the closest real inscription.
        """
        grouped = {}
        for unit in units:
            key = self._site_representative_key(unit)
            grouped.setdefault(key, []).append(unit)

        representatives = []
        for key in sorted(grouped, key=self._unicode_key):
            members = grouped[key]
            if len(members) == 1:
                representative = dict(members[0])
                medoid = members[0]
            else:
                distances, _ = self._distance_matrix_for_units(
                    members, metric
                )
                indices = list(range(len(members)))
                medoid_index, _ = self._cluster_medoid(
                    indices, distances
                )
                medoid = members[medoid_index]

                if use_consensus:
                    consensus, consensus_n = self._cluster_consensus_unit(
                        members, indices, medoid_index, distances
                    )
                    representative = dict(consensus)
                    representative["sign_id"] = medoid["sign_id"]
                    representative["grapheme"] = medoid.get("grapheme", "")
                    representative["instance"] = medoid.get("instance", "")
                    representative["certainty"] = medoid.get(
                        "certainty", "complete"
                    )
                    representative["from_bindrune"] = medoid.get(
                        "from_bindrune", False
                    )
                    representative["network_consensus_n"] = consensus_n
                else:
                    representative = dict(medoid)

            location = self._nfc(medoid.get("location", "")).strip()
            representative["location"] = location
            representative["object_type"] = medoid.get("object_type", "")
            representative["object_number"] = medoid.get("object_number", "")
            representative["network_site_key"] = key
            representative["network_site_label"] = (
                self._location_label_for_plot(representative)
                or location
                or "(unknown location)"
            )
            representative["network_site_count"] = len(members)
            representative["network_is_consensus"] = bool(use_consensus)
            member_dates = [
                self._network_time_midpoint(member)
                for member in members
            ]
            member_dates = [
                value for value in member_dates if value is not None
            ]
            representative["network_time_midpoint"] = (
                sum(member_dates) / len(member_dates)
                if member_dates else None
            )
            member_coordinates = [
                self._network_geographic_coordinates(member)
                for member in members
            ]
            member_coordinates = [
                value for value in member_coordinates if value is not None
            ]
            if member_coordinates:
                representative["network_longitude"] = sum(
                    value[0] for value in member_coordinates
                ) / len(member_coordinates)
                representative["network_latitude"] = sum(
                    value[1] for value in member_coordinates
                ) / len(member_coordinates)
            representatives.append(representative)

        return representatives

    def _network_site_representatives(
        self, units, metric, use_consensus=False
    ):
        """Compatibility wrapper for Similarity Network."""
        return self._site_representatives(
            units, metric, use_consensus=use_consensus
        )


    def _redraw_existing_network(self, event=None):
        """Redraw display options only after a network has been built."""
        if self.network_canvas.find_all():
            self.render_similarity_network()

    @staticmethod
    def _network_time_midpoint(unit):
        """Return the midpoint of a unit's archaeological date range."""
        stored = unit.get("network_time_midpoint")
        if stored is not None:
            try:
                return float(stored)
            except (TypeError, ValueError):
                pass
        start = App._parse_period_year(unit.get("date_start", ""))
        end = App._parse_period_year(unit.get("date_end", ""))
        if start is None and end is None:
            return None
        if start is None:
            return float(end)
        if end is None:
            return float(start)
        return (float(start) + float(end)) / 2.0

    def _project_time_bounds(self):
        """Use the entire loaded dataset for a consistent date colour scale."""
        dates = (
            self._network_time_midpoint(row) for row in self.rows
        )
        dates = [value for value in dates if value is not None]
        return (min(dates), max(dates)) if dates else None

    def _shown_network_time_bounds(self):
        """Return date limits for the nodes in the rendered network only."""
        dates = [
            value for value in self.network_node_dates.values()
            if value is not None
        ]
        return (min(dates), max(dates)) if dates else None

    def _network_time_bounds(self):
        """Return chronology bounds for the active network legend scope."""
        if self.network_time_range_scope == "shown":
            shown = self._shown_network_time_bounds()
            if shown is not None:
                return shown
        return self._project_time_bounds()

    def _toggle_network_time_range(self, event=None):
        """Toggle chronology colours between project-wide and shown bounds."""
        if self.network_colour_mode.get() != "Chronological":
            return "break"
        self.network_time_range_scope = (
            "shown"
            if self.network_time_range_scope == "project"
            else "project"
        )
        self._update_network_node_colours()
        label = (
            "displayed-network range"
            if self.network_time_range_scope == "shown"
            else "full-project range"
        )
        self.network_status.set(
            f"Chronological colour scale: {label}. Click the legend to toggle."
        )
        return "break"

    @staticmethod
    def _network_time_colour(value, earliest, latest, opacity=0.42):
        """Interpolate the five-stage time palette and blend it with white."""
        # Viridis: perceptually uniform, colour-blind friendly, and legible
        # in greyscale. Dark purple/blue denotes older material; yellow
        # denotes younger material.
        palette = [
            (68, 1, 84),
            (59, 82, 139),
            (33, 145, 140),
            (94, 201, 98),
            (253, 231, 37),
        ]
        if latest <= earliest:
            position = 0.5
        else:
            position = min(max((value - earliest) / (latest - earliest), 0.0), 1.0)
        scaled = position * (len(palette) - 1)
        lower = min(int(math.floor(scaled)), len(palette) - 1)
        upper = min(lower + 1, len(palette) - 1)
        fraction = scaled - lower
        rgb = [
            palette[lower][channel] * (1.0 - fraction)
            + palette[upper][channel] * fraction
            for channel in range(3)
        ]
        blended = [
            round(255.0 * (1.0 - opacity) + component * opacity)
            for component in rgb
        ]
        return "#{:02x}{:02x}{:02x}".format(*blended)

    def _network_geographic_coordinates(self, unit):
        """Return a unit's longitude and latitude, including representatives."""
        longitude = unit.get("network_longitude", unit.get("longitude", ""))
        latitude = unit.get("network_latitude", unit.get("latitude", ""))
        longitude = self._parse_coordinate(longitude)
        latitude = self._parse_coordinate(latitude)
        if (
            longitude is None or latitude is None
            or not (-180.0 <= longitude <= 180.0)
            or not (-90.0 <= latitude <= 90.0)
        ):
            return None
        return float(longitude), float(latitude)

    def _project_geographic_bounds(self):
        """Return stable coordinate limits from all signs in the project."""
        coordinates = []
        seen = set()
        for row in self.rows:
            sign_id = row.get("sign_id")
            if sign_id in seen:
                continue
            seen.add(sign_id)
            value = self._network_geographic_coordinates(row)
            if value is not None:
                coordinates.append(value)
        if not coordinates:
            return None
        longitudes = [value[0] for value in coordinates]
        latitudes = [value[1] for value in coordinates]
        return (
            min(longitudes), max(longitudes),
            min(latitudes), max(latitudes)
        )

    def _shown_network_geographic_bounds(self):
        """Return coordinate limits for the rendered network nodes only."""
        coordinates = [
            value for value in self.network_node_coordinates.values()
            if value is not None
        ]
        if not coordinates:
            return None
        longitudes = [value[0] for value in coordinates]
        latitudes = [value[1] for value in coordinates]
        return (
            min(longitudes), max(longitudes),
            min(latitudes), max(latitudes)
        )

    def _network_geographic_bounds(self):
        """Return geographic bounds for the active network legend scope."""
        if self.network_geographic_range_scope == "shown":
            shown = self._shown_network_geographic_bounds()
            if shown is not None:
                return shown
        return self._project_geographic_bounds()

    def _toggle_network_geographic_range(self, event=None):
        """Toggle geographic colours between shown and project bounds."""
        if self.network_colour_mode.get() != "Geographical":
            return "break"
        self.network_geographic_range_scope = (
            "project"
            if self.network_geographic_range_scope == "shown"
            else "shown"
        )
        self._update_network_node_colours()
        label = (
            "displayed-network range"
            if self.network_geographic_range_scope == "shown"
            else "full-project range"
        )
        self.network_status.set(
            f"Geographical colour scale: {label}. Click the legend to toggle."
        )
        return "break"

    @staticmethod
    def _lab_to_rgb(lightness, axis_a, axis_b):
        """Convert a CIELAB colour to a clipped sRGB triplet."""
        fy = (lightness + 16.0) / 116.0
        fx = fy + axis_a / 500.0
        fz = fy - axis_b / 200.0

        def inverse_pivot(value):
            cube = value ** 3
            return cube if cube > 0.008856 else (value - 16.0 / 116.0) / 7.787

        x = 0.95047 * inverse_pivot(fx)
        y = inverse_pivot(fy)
        z = 1.08883 * inverse_pivot(fz)
        linear = (
            3.2406*x - 1.5372*y - 0.4986*z,
            -0.9689*x + 1.8758*y + 0.0415*z,
            0.0557*x - 0.2040*y + 1.0570*z,
        )

        def gamma(value):
            value = max(0.0, min(1.0, value))
            if value <= 0.0031308:
                return 12.92 * value
            return 1.055 * (value ** (1.0 / 2.4)) - 0.055

        return tuple(round(255.0 * gamma(value)) for value in linear)

    def _network_geographic_colour(
        self, longitude, latitude, bounds, opacity=0.52
    ):
        """Map longitude to blue–yellow and latitude to red–green."""
        lon_min, lon_max, lat_min, lat_max = bounds
        lon_position = (
            0.5 if lon_max <= lon_min else
            min(max((longitude - lon_min) / (lon_max - lon_min), 0.0), 1.0)
        )
        lat_position = (
            0.5 if lat_max <= lat_min else
            min(max((latitude - lat_min) / (lat_max - lat_min), 0.0), 1.0)
        )
        # CIELAB a*: red (+) to green (-); b*: yellow (+) to blue (-).
        axis_a = 42.0 * (1.0 - 2.0 * lat_position)
        axis_b = 42.0 * (2.0 * lon_position - 1.0)
        rgb = self._lab_to_rgb(72.0, axis_a, axis_b)
        blended = [
            round(255.0 * (1.0 - opacity) + component * opacity)
            for component in rgb
        ]
        return "#{:02x}{:02x}{:02x}".format(*blended)

    @staticmethod
    def _date_era_label(value):
        """Format a numerical year with an explicit BCE/CE suffix."""
        number = float(value)
        magnitude = int(math.floor(abs(number) + 0.5))
        text = str(magnitude)
        return f"{text} {'BCE' if number < 0 else 'CE'}"

    def _draw_date_colour_legend(
        self, canvas, tag, earliest, latest, *, left=14.0, top=14.0
    ):
        """Draw endpoint dates and the Viridis scale on one compact line."""
        canvas.delete(tag)
        steps = 64
        # Match the 62-pixel colored square in the geographic legend.
        bar_width, bar_height = 62.0, 10.0
        gap, padding = 7.0, 7.0
        font_spec = ("Arial", 8)
        font = tkfont.Font(root=self.root, font=font_spec)
        early_text = self._date_era_label(earliest)
        late_text = self._date_era_label(latest)
        early_width = font.measure(early_text)
        late_width = font.measure(late_text)
        content_width = early_width + gap + bar_width + gap + late_width
        box_height = 24.0
        centre_y = top + box_height / 2.0
        canvas.create_rectangle(
            left, top, left + content_width + 2 * padding, top + box_height,
            fill="white", outline="#c7c7c7",
            tags=(tag,)
        )
        cursor = left + padding
        canvas.create_text(
            cursor, centre_y, text=early_text, anchor="w",
            font=font_spec, fill="#555555", tags=(tag,)
        )
        cursor += early_width + gap
        for index in range(steps):
            fraction = index / max(steps - 1, 1)
            value = earliest + fraction * (latest - earliest)
            x1 = cursor + index * bar_width / steps
            x2 = cursor + (index + 1) * bar_width / steps + 0.5
            canvas.create_rectangle(
                x1, centre_y - bar_height / 2.0,
                x2, centre_y + bar_height / 2.0,
                fill=self._network_time_colour(value, earliest, latest),
                outline="",
                tags=(tag,)
            )
        cursor += bar_width + gap
        canvas.create_text(
            cursor, centre_y, text=late_text, anchor="w",
            font=font_spec, fill="#555555", tags=(tag,)
        )
        canvas.tag_raise(tag)

    def _draw_network_time_legend(self, earliest, latest):
        """Draw the clickable one-line date legend on the network canvas."""
        self._draw_date_colour_legend(
            self.network_canvas, "network_time_legend", earliest, latest
        )
        self.network_canvas.tag_bind(
            "network_time_legend", "<Button-1>",
            self._toggle_network_time_range
        )
        self.network_canvas.tag_bind(
            "network_time_legend", "<Enter>",
            lambda event: self.network_canvas.configure(cursor="hand2")
        )
        self.network_canvas.tag_bind(
            "network_time_legend", "<Leave>",
            lambda event: self.network_canvas.configure(cursor="")
        )

    def _draw_geographic_colour_legend(
        self, canvas, tag, bounds, *, left=14.0, top=14.0
    ):
        """Draw the two-dimensional longitude/latitude colour legend."""
        canvas.delete(tag)
        lon_min, lon_max, lat_min, lat_max = bounds
        steps = 9
        grid_size = 62.0
        label_space = 18.0
        padding = 7.0
        box_width = grid_size + label_space + 2 * padding
        box_height = grid_size + label_space + 2 * padding
        canvas.create_rectangle(
            left, top, left + box_width, top + box_height,
            fill="white", outline="#c7c7c7", tags=(tag,)
        )
        grid_left = left + padding + label_space
        grid_top = top + padding
        for row in range(steps):
            latitude = lat_max - row * (lat_max - lat_min) / max(steps - 1, 1)
            for column in range(steps):
                longitude = lon_min + column * (lon_max - lon_min) / max(steps - 1, 1)
                x1 = grid_left + column * grid_size / steps
                y1 = grid_top + row * grid_size / steps
                x2 = grid_left + (column + 1) * grid_size / steps + 0.5
                y2 = grid_top + (row + 1) * grid_size / steps + 0.5
                canvas.create_rectangle(
                    x1, y1, x2, y2,
                    fill=self._network_geographic_colour(
                        longitude, latitude, bounds
                    ),
                    outline="", tags=(tag,)
                )
        font_spec = ("Arial", 8)
        canvas.create_text(
            grid_left - 4, grid_top, text="N", anchor="ne",
            font=font_spec, fill="#555555", tags=(tag,)
        )
        canvas.create_text(
            grid_left - 4, grid_top + grid_size, text="S", anchor="se",
            font=font_spec, fill="#555555", tags=(tag,)
        )
        canvas.create_text(
            grid_left, grid_top + grid_size + 4, text="W", anchor="nw",
            font=font_spec, fill="#555555", tags=(tag,)
        )
        canvas.create_text(
            grid_left + grid_size, grid_top + grid_size + 4,
            text="E", anchor="ne", font=font_spec,
            fill="#555555", tags=(tag,)
        )
        canvas.tag_raise(tag)

    def _draw_network_geographic_legend(self, bounds):
        """Draw the clickable geographic legend on the network canvas."""
        tag = "network_geography_legend"
        self._draw_geographic_colour_legend(
            self.network_canvas, tag, bounds
        )
        self.network_canvas.tag_bind(
            tag, "<Button-1>", self._toggle_network_geographic_range
        )
        self.network_canvas.tag_bind(
            tag, "<Enter>",
            lambda event: self.network_canvas.configure(cursor="hand2")
        )
        self.network_canvas.tag_bind(
            tag, "<Leave>",
            lambda event: self.network_canvas.configure(cursor="")
        )

    def _on_analysis_colour_mode_changed(self, event=None):
        """Apply the shared Fill state to the active analytical view."""
        if self.current_view == "network":
            self._update_network_node_colours()
        elif self.current_view == "cluster":
            self._redraw_existing_cluster()
        elif self.current_view == "map":
            self._redraw_existing_map()

    def _update_network_node_colours(self, event=None):
        """Recolour existing network circles without rebuilding the network."""
        canvas = self.network_canvas
        canvas.delete("network_time_legend")
        canvas.delete("network_geography_legend")
        if not self.network_node_items:
            return
        colour_mode = self.network_colour_mode.get()
        time_bounds = self._network_time_bounds()
        earliest, latest = time_bounds if time_bounds else (None, None)
        geographic_bounds = self._network_geographic_bounds()
        for sign_id, items in self.network_node_items.items():
            if not items:
                continue
            if colour_mode == "Legacy":
                colour = self._legacy_sign_colour(sign_id)
            elif colour_mode == "Chronological" and earliest is not None:
                value = self.network_node_dates.get(sign_id)
                colour = (
                    self._network_time_colour(value, earliest, latest)
                    if value is not None else "#eeeeee"
                )
            elif colour_mode == "Geographical" and geographic_bounds is not None:
                coordinates = self.network_node_coordinates.get(sign_id)
                colour = (
                    self._network_geographic_colour(
                        coordinates[0], coordinates[1], geographic_bounds
                    )
                    if coordinates is not None else "#eeeeee"
                )
            else:
                colour = "white"
            try:
                canvas.itemconfigure(items[0], fill=colour)
            except tk.TclError:
                pass
        if colour_mode == "Chronological" and earliest is not None:
            self._draw_network_time_legend(earliest, latest)
        elif colour_mode == "Geographical" and geographic_bounds is not None:
            self._draw_network_geographic_legend(geographic_bounds)

    def _highlight_network_selection(self, sign_id):
        """Update only network node outlines after a click; no analysis rerun."""
        canvas = self.network_canvas
        for sid, items in self.network_node_items.items():
            if not items:
                continue
            try:
                canvas.itemconfigure(items[0], width=(2 if sid == sign_id else 1))
            except tk.TclError:
                pass

    def _highlight_normalized_selection(self, sign_id):
        """Update Sign inventory selection without rebuilding or scrolling."""
        canvas = self.normalized_canvas
        try:
            canvas.delete("normalized_selection_overlay")
        except tk.TclError:
            return
        boxes = getattr(self, "normalized_sign_boxes", {})
        box = boxes.get(sign_id) if sign_id else None
        if not box:
            return
        x1, y1, x2, y2 = box
        canvas.create_rectangle(
            x1, y1, x2, y2,
            fill="", outline="black", width=2,
            tags=("normalized_selection_overlay",)
        )

    def _redraw_existing_cluster(self, event=None):
        """Redraw an existing cluster result without recomputing distances.

        Centralize, symmetry, coloured strokes, and selection highlighting are
        display/matrix operations.  Reuse the last analytical clustering so these
        controls remain interactive even for large sign sets.
        """
        if self.cluster_canvas.find_all():
            self.render_cluster_view(reuse_analysis=True)

    def _highlight_cluster_selection(self, sign_id):
        """Update Subclustering selection without redrawing the clusters."""
        canvas = self.cluster_canvas
        try:
            canvas.delete("cluster_selection_overlay")
        except tk.TclError:
            return
        bounds = getattr(self, "cluster_selection_bounds", {})
        selected = bounds.get(sign_id) if sign_id else None
        if not selected:
            return
        for kind, coords in selected:
            if kind == "oval":
                canvas.create_oval(
                    *coords,
                    fill="", outline="black", width=2,
                    tags=("cluster_selection_overlay",)
                )
            else:
                canvas.create_rectangle(
                    *coords,
                    fill="", outline="black", width=2,
                    tags=("cluster_selection_overlay",)
                )

    def _redraw_existing_map(self, event=None):
        """Apply map display options only after a map has been drawn."""
        if hasattr(self, "map_canvas") and self.map_canvas.find_all():
            self.render_rune_map()

