        positions = getattr(self, "map_sign_positions", {})
        if sign_id and sign_id in positions and sign_id not in circle_items:
            x, y, symbol_scale = positions[sign_id]
            radius = 16 * symbol_scale
            canvas.create_oval(
                x - radius, y - radius,
                x + radius, y + radius,
                fill="", outline="black", width=2,
                tags=("map_selection_overlay",)
            )

