    # ---------- Hausdorff-distance clustering ----------

    def _hausdorff_cloud(self, unit, points_per_stroke=48):
        """Resample all strokes into a point cloud for Hausdorff comparison."""
        cloud = []
        for stroke in unit.get("strokes", []):
            if len(stroke) < 2:
                continue
            lengths = [0.0]
            for i in range(1, len(stroke)):
                lengths.append(
                    lengths[-1] + math.hypot(
                        stroke[i][0] - stroke[i-1][0],
                        stroke[i][1] - stroke[i-1][1]
                    )
                )
            total = lengths[-1]
            if total <= 1e-12:
                cloud.append(stroke[0])
                continue

            seg = 0
            for j in range(points_per_stroke):
                target = total * j / max(points_per_stroke - 1, 1)
                while seg < len(lengths) - 2 and lengths[seg + 1] < target:
                    seg += 1
                left = lengths[seg]
                right = lengths[seg + 1]
                t = 0.0 if right == left else (target-left)/(right-left)
                x = stroke[seg][0] + t*(stroke[seg+1][0]-stroke[seg][0])
                y = stroke[seg][1] + t*(stroke[seg+1][1]-stroke[seg][1])
                cloud.append((x, y))
        return cloud

    def _cached_hausdorff_cloud(self, unit, points_per_stroke=48):
        cache = getattr(self, "_hausdorff_cloud_cache", None)
        if cache is None:
            self._hausdorff_cloud_cache = {}
            cache = self._hausdorff_cloud_cache
        key = (points_per_stroke, self._shape_fingerprint(unit))
        if key not in cache:
            cache[key] = self._hausdorff_cloud(
                unit, points_per_stroke=points_per_stroke
            )
        return cache[key]

    def _directed_hausdorff(self, source, target):
        if not source or not target:
            return float("inf")
        distances = self._nearest_distances(source, target)
        return max(distances) if distances else float("inf")

    def _hausdorff_distance(self, cloud_a, cloud_b):
        """Symmetric Hausdorff distance between two normalized point clouds."""
        if not cloud_a or not cloud_b:
            return float("inf")
        if np is not None:
            a = np.asarray(cloud_a, dtype=float)
            b = np.asarray(cloud_b, dtype=float)
            delta = a[:, None, :] - b[None, :, :]
            d2 = np.einsum("ijk,ijk->ij", delta, delta, optimize=True)
            # Same point distances serve both directions. Keep the existing
            # square-root operations before taking either directed maximum.
            da = np.sqrt(np.min(d2, axis=1)).tolist()
            db = np.sqrt(np.min(d2, axis=0)).tolist()
            return max(max(da), max(db))
        return max(
            self._directed_hausdorff(cloud_a, cloud_b),
            self._directed_hausdorff(cloud_b, cloud_a)
        )

    # ---------- stroke-aware Procrustes clustering ----------

    def _proc_resample_stroke(self, stroke, n=16):
        if len(stroke) < 2:
            return list(stroke)
        lengths = [0.0]
        for i in range(1, len(stroke)):
            lengths.append(
                lengths[-1] + math.hypot(
                    stroke[i][0] - stroke[i-1][0],
                    stroke[i][1] - stroke[i-1][1]
                )
            )
        total = lengths[-1]
        if total <= 1e-12:
            return [stroke[0]] * n
        out = []
        seg = 0
        for j in range(n):
            target = total * j / max(n-1, 1)
            while seg < len(lengths)-2 and lengths[seg+1] < target:
                seg += 1
            left = lengths[seg]
            right = lengths[seg+1]
            t = 0.0 if right == left else (target-left)/(right-left)
            out.append((
                stroke[seg][0] + t*(stroke[seg+1][0]-stroke[seg][0]),
                stroke[seg][1] + t*(stroke[seg+1][1]-stroke[seg][1])
            ))
        return out

    def _proc_normalize_points(self, points):
        cx = sum(x for x, y in points) / len(points)
        cy = sum(y for x, y in points) / len(points)
        centered = [(x-cx, y-cy) for x, y in points]
        size = math.sqrt(sum(x*x+y*y for x, y in centered))
        if size <= 1e-12:
            return centered
        return [(x/size, y/size) for x, y in centered]

    def _proc_distance_and_angle_for_pairs(self, points_a, points_b):
        """Return full Procrustes distance and optimal rotation in degrees.

        Translation and scale are removed. Reflection is not allowed.
        The signed angle rotates B onto A; its absolute magnitude is used by
        the optional rotation-penalized metric.
        """
        a = self._proc_normalize_points(points_a)
        b = self._proc_normalize_points(points_b)

        c = sum(ax*bx + ay*by for (ax, ay), (bx, by) in zip(a, b))
        ss = sum(ax*by - ay*bx for (ax, ay), (bx, by) in zip(a, b))
        # Rotate B onto A using the fitted proper rotation.
        angle = -math.atan2(ss, c)
        ca = math.cos(angle)
        sa = math.sin(angle)
        b_rot = [
            (ca*bx - sa*by, sa*bx + ca*by)
            for bx, by in b
        ]
        distance = math.sqrt(
            sum(
                (ax-bx)**2 + (ay-by)**2
                for (ax, ay), (bx, by) in zip(a, b_rot)
            )
        )
        angle_deg = abs(math.degrees(angle))
        # atan2 already gives [-180, 180], but keep the magnitude canonical.
        angle_deg = min(angle_deg, 360.0 - angle_deg)
        return distance, angle_deg


    def _proc_rotation_penalty(self, angle_deg):
        """Penalty for the rotation used by an optimal Procrustes fit.

        Rotations up to 30 degrees are treated as ordinary orientation noise.
        Between 30 and 45 degrees the penalty rises gently and quadratically.
        Beyond 45 degrees it rises steeply so quarter-turn equivalences are
        strongly discouraged without being made mathematically impossible.
        """
        angle = abs(float(angle_deg))
        if angle <= 30.0:
            return 0.0
        if angle <= 45.0:
            return 0.0004 * (angle - 30.0) ** 2  # 0.090 at 45°
        return 0.090 + 0.015 * (angle - 45.0)   # 0.765 at 90°



    def _hungarian_assignment(self, cost):
        """Return a minimum-cost row-to-column assignment for n <= m."""
        n = len(cost)
        if n == 0:
            return []
        m = len(cost[0])
        if m == 0 or n > m:
            raise ValueError("Hungarian assignment requires 0 < rows <= columns")

        u = [0.0] * (n + 1)
        v = [0.0] * (m + 1)
        p = [0] * (m + 1)
        way = [0] * (m + 1)
        for i in range(1, n + 1):
            p[0] = i
            j0 = 0
            minv = [float("inf")] * (m + 1)
            used = [False] * (m + 1)
            while True:
                used[j0] = True
                i0 = p[j0]
                delta = float("inf")
                j1 = 0
                for j in range(1, m + 1):
                    if used[j]:
                        continue
                    cur = cost[i0 - 1][j - 1] - u[i0] - v[j]
                    if cur < minv[j]:
                        minv[j] = cur
                        way[j] = j0
                    if minv[j] < delta:
                        delta = minv[j]
                        j1 = j
                for j in range(m + 1):
                    if used[j]:
                        u[p[j]] += delta
                        v[j] -= delta
                    else:
                        minv[j] -= delta
                j0 = j1
                if p[j0] == 0:
                    break
            while True:
                j1 = way[j0]
                p[j0] = p[j1]
                j0 = j1
                if j0 == 0:
                    break

        assignment = [-1] * n
        for j in range(1, m + 1):
            if p[j]:
                assignment[p[j] - 1] = j - 1
        return assignment

    def _proc_normalized_resampled_strokes(self, resampled):
        """Globally normalize resampled strokes while preserving stroke groups."""
        flat = [point for stroke in resampled for point in stroke]
        if not flat:
            return [[] for _ in resampled]
        normalized = self._proc_normalize_points(flat)
        out = []
        pos = 0
        for stroke in resampled:
            out.append(normalized[pos:pos + len(stroke)])
            pos += len(stroke)
        return out

    def _cached_proc_strokes(self, unit):
        """Prepare each shape once using the existing Procrustes arithmetic."""
        cache = getattr(self, "_proc_stroke_preparation_cache", None)
        if cache is None:
            cache = self._proc_stroke_preparation_cache = {}
        key = self._exact_stroke_geometry(unit)
        if key not in cache:
            sampled = [self._proc_resample_stroke(stroke)
                       for stroke in unit.get("strokes", [])]
            normalized = self._proc_normalized_resampled_strokes(sampled)
            if len(cache) >= 2048:
                cache.clear()
            cache[key] = (sampled, normalized)
        return cache[key]

    def _proc_pair_distance_efficient_details(
        self, unit_a, unit_b, rotation_penalty=False
    ):
        """Fast stroke-aware Procrustes, returning (distance, |rotation|).

        Stroke correspondence is chosen once with a Hungarian assignment using
        globally normalized stroke geometry. Each assigned stroke is given its
        cheaper traversal direction, followed by one global Procrustes fit.
        When ``rotation_penalty`` is true, the same symmetric absolute-angle
        penalty as the exhaustive diagnostic metric is added.
        """
        sa = unit_a.get("strokes", [])
        sb = unit_b.get("strokes", [])
        if not sa or not sb:
            return float("inf"), 0.0

        small_unit, large_unit = unit_a, unit_b
        if len(sa) > len(sb):
            small_unit, large_unit = unit_b, unit_a

        small_res, small_norm = self._cached_proc_strokes(small_unit)
        large_res, large_norm = self._cached_proc_strokes(large_unit)
        ns, nl = len(small_res), len(large_res)

        direction_choice = {}
        cost = []
        for i, a_stroke in enumerate(small_norm):
            row = []
            for j, b_stroke in enumerate(large_norm):
                direct = sum(
                    (ax-bx)**2 + (ay-by)**2
                    for (ax, ay), (bx, by) in zip(a_stroke, b_stroke)
                )
                rev = list(reversed(b_stroke))
                reverse = sum(
                    (ax-bx)**2 + (ay-by)**2
                    for (ax, ay), (bx, by) in zip(a_stroke, rev)
                )
                reversed_choice = reverse < direct
                direction_choice[(i, j)] = reversed_choice
                row.append(min(direct, reverse) / max(len(a_stroke), 1))
            cost.append(row)

        assignment = self._hungarian_assignment(cost)
        pts_small = []
        pts_large = []
        for i, j in enumerate(assignment):
            a_stroke = small_res[i]
            b_stroke = large_res[j]
            if direction_choice[(i, j)]:
                b_stroke = list(reversed(b_stroke))
            pts_small.extend(a_stroke)
            pts_large.extend(b_stroke)

        value, angle_deg = self._proc_distance_and_angle_for_pairs(
            pts_small, pts_large
        )
        if rotation_penalty:
            value += self._proc_rotation_penalty(angle_deg)
        value += 0.35 * (nl - ns)
        return value, angle_deg


    def _proc_rotation_penalty_variant(self, angle_deg, mid_coefficient):
        """Experimental rotation penalty; only strengthens the 30–45° band."""
        angle = abs(float(angle_deg))
        if angle <= 30.0:
            return 0.0
        if angle <= 45.0:
            return float(mid_coefficient) * (angle - 30.0) ** 2
        # Keep the accepted >45° regime unchanged so this experiment isolates
        # the ambiguous 30–45° range.
        return 0.09 + 0.015 * (angle - 45.0)

    def _proc_similarity_transform(self, points_a, points_b, indices=None):
        """Proper similarity transform mapping B to A, with no reflection."""
        if indices is None:
            indices = range(len(points_a))
        idx = list(indices)
        if len(idx) < 2:
            return None
        aa0 = [points_a[i] for i in idx]
        bb0 = [points_b[i] for i in idx]
        acx = sum(x for x, _ in aa0) / len(aa0)
        acy = sum(y for _, y in aa0) / len(aa0)
        bcx = sum(x for x, _ in bb0) / len(bb0)
        bcy = sum(y for _, y in bb0) / len(bb0)
        aa = [(x-acx, y-acy) for x,y in aa0]
        bb = [(x-bcx, y-bcy) for x,y in bb0]
        denom = sum(x*x+y*y for x,y in bb)
        if denom <= 1e-12:
            return None
        c = sum(ax*bx + ay*by for (ax,ay),(bx,by) in zip(aa,bb))
        ss = sum(ax*by - ay*bx for (ax,ay),(bx,by) in zip(aa,bb))
        angle = -math.atan2(ss, c)
        ca, sa = math.cos(angle), math.sin(angle)
        numer = 0.0
        for (ax,ay),(bx,by) in zip(aa,bb):
            rx = ca*bx - sa*by
            ry = sa*bx + ca*by
            numer += ax*rx + ay*ry
        scale = max(0.0, numer / denom)
        tx = acx - scale*(ca*bcx - sa*bcy)
        ty = acy - scale*(sa*bcx + ca*bcy)
        return scale, angle, tx, ty

    def _proc_transform_residuals(self, points_a, points_b, transform):
        if transform is None:
            return [float("inf")] * len(points_a)
        scale, angle, tx, ty = transform
        ca, sa = math.cos(angle), math.sin(angle)
        out = []
        for (ax,ay),(bx,by) in zip(points_a,points_b):
            rx = scale*(ca*bx-sa*by)+tx
            ry = scale*(sa*bx+ca*by)+ty
            out.append(math.hypot(ax-rx, ay-ry))
        return out

    def _proc_candidate_triples(self, n, cap=160):
        """Deterministic p=3 candidate subsets for Carve's interactive benchmark.

        Tang & Jackson use exhaustive or random p-subsets depending on cost.
        Carve caps the candidate count deterministically because this estimator
        is evaluated for every pair of rune signs in an interactive matrix.
        """
        triples = list(itertools.combinations(range(n), 3))
        if len(triples) <= cap:
            return triples
        # Evenly cover the lexicographic subset sequence, reproducibly.
        step = (len(triples)-1) / float(cap-1)
        chosen = []
        seen = set()
        for k in range(cap):
            j = int(round(k*step))
            if j not in seen:
                seen.add(j); chosen.append(triples[j])
        return chosen

    def _proc_subset_fit(self, points_a, points_b, method="lms"):
        """Carve-adapted Tang–Jackson p-subset LMS/ILMS/LTS fit.

        p=3 in 2D and K=ceil(n/2). LMS minimizes the median squared residual;
        LTS minimizes the K-smallest squared-residual sum; ILMS takes the LMS
        solution, selects its K smallest-residual landmarks, then refits PA.
        Reflection is prohibited, matching Carve's graphemic requirements.
        """
        n = len(points_a)
        if n < 3 or n != len(points_b):
            return None, float("inf"), 0.0
        kkeep = max(3, int(math.ceil(n/2.0)))
        best = None
        best_obj = float("inf")
        best_res = None
        for subset in self._proc_candidate_triples(n):
            tr = self._proc_similarity_transform(points_a, points_b, subset)
            if tr is None:
                continue
            res = self._proc_transform_residuals(points_a, points_b, tr)
            sq = sorted(r*r for r in res)
            if method in ("lms", "ilms"):
                mid = len(sq)//2
                obj = sq[mid] if len(sq)%2 else 0.5*(sq[mid-1]+sq[mid])
            else:
                obj = sum(sq[:kkeep])
            if obj < best_obj:
                best_obj, best, best_res = obj, tr, res
        if best is None:
            return None, float("inf"), 0.0
        if method in ("ilms", "lts"):
            keep = sorted(range(n), key=lambda i: best_res[i])[:kkeep]
            refined = self._proc_similarity_transform(points_a, points_b, keep)
            if refined is not None:
                best = refined
        residuals = self._proc_transform_residuals(points_a, points_b, best)
        # Report RMS over all correspondences: robust fitting changes alignment,
        # but the distance still records discrepancies rather than deleting them.
        distance = math.sqrt(sum(r*r for r in residuals)/n)
        angle_deg = abs(math.degrees(best[1]))
        angle_deg = min(angle_deg, 360.0-angle_deg)
        return best, distance, angle_deg

    def _proc_biweight_fit(self, points_a, points_b, tuning=4.685, max_iter=30):
        """Tukey biweight IRLS proper-similarity fit; reflection prohibited.

        This implementation is deliberately defensive: every IRLS iteration
        computes an explicit weighted similarity transform in the original
        coordinate system, so degenerate or fully downweighted iterations
        cannot leak a None result into the pairwise benchmark.
        """
        n = len(points_a)
        if n < 2 or n != len(points_b):
            return float("inf"), 0.0

        def weighted_fit(weights):
            sw = sum(weights)
            if sw <= 1e-12:
                return None
            acx = sum(w * p[0] for w, p in zip(weights, points_a)) / sw
            acy = sum(w * p[1] for w, p in zip(weights, points_a)) / sw
            bcx = sum(w * p[0] for w, p in zip(weights, points_b)) / sw
            bcy = sum(w * p[1] for w, p in zip(weights, points_b)) / sw
            aa = [(x-acx, y-acy) for x, y in points_a]
            bb = [(x-bcx, y-bcy) for x, y in points_b]
            denom = sum(w*(x*x+y*y) for w,(x,y) in zip(weights, bb))
            if denom <= 1e-12:
                return None
            c = sum(w*(ax*bx+ay*by) for w,(ax,ay),(bx,by) in zip(weights, aa, bb))
            ss = sum(w*(ax*by-ay*bx) for w,(ax,ay),(bx,by) in zip(weights, aa, bb))
            angle = -math.atan2(ss, c)
            ca, sa = math.cos(angle), math.sin(angle)
            numer = 0.0
            for w,(ax,ay),(bx,by) in zip(weights, aa, bb):
                rx = ca*bx - sa*by
                ry = sa*bx + ca*by
                numer += w*(ax*rx + ay*ry)
            scale = max(0.0, numer/denom)
            tx = acx - scale*(ca*bcx - sa*bcy)
            ty = acy - scale*(sa*bcx + ca*bcy)
            return scale, angle, tx, ty

        weights = [1.0] * n
        transform = weighted_fit(weights)
        if transform is None:
            return float("inf"), 0.0

        for _ in range(max_iter):
            residuals = self._proc_transform_residuals(points_a, points_b, transform)
            finite_res = [r for r in residuals if math.isfinite(r)]
            if not finite_res:
                return float("inf"), 0.0
            ordered = sorted(finite_res)
            m = len(ordered)
            med = ordered[m//2] if m % 2 else 0.5*(ordered[m//2-1]+ordered[m//2])
            dev = sorted(abs(r-med) for r in finite_res)
            mad = dev[m//2] if m % 2 else 0.5*(dev[m//2-1]+dev[m//2])
            scale_r = max(1.4826*mad, 1e-6)
            cutoff = max(tuning*scale_r, 1e-12)
            new_weights = []
            for r in residuals:
                if not math.isfinite(r):
                    new_weights.append(0.0)
                    continue
                u = r/cutoff
                new_weights.append((1.0-u*u)**2 if abs(u) < 1.0 else 0.0)

            # A redescending estimator can, in an extreme configuration,
            # reject every point. Keep the previous valid transform rather
            # than returning None or crashing the whole benchmark.
            if sum(new_weights) <= 1e-12:
                break
            new_transform = weighted_fit(new_weights)
            if new_transform is None:
                break
            change = max(abs(a-b) for a,b in zip(weights, new_weights))
            weights = new_weights
            transform = new_transform
            if change < 1e-6:
                break

        residuals = self._proc_transform_residuals(points_a, points_b, transform)
        if not residuals or any(not math.isfinite(r) for r in residuals):
            return float("inf"), 0.0
        distance = math.sqrt(sum(r*r for r in residuals)/n)
        angle_deg = abs(math.degrees(transform[1]))
        angle_deg = min(angle_deg, 360.0-angle_deg)
        return distance, angle_deg

    def _proc_pair_distance_resistant_details(self, unit_a, unit_b, method, rotation_penalty=False):
        """Same stroke assignment as Carve Procrustes; resistant final fit only."""
        sa=unit_a.get("strokes",[]); sb=unit_b.get("strokes",[])
        if not sa or not sb: return float("inf"),0.0
        small,large=sa,sb
        if len(sa)>len(sb): small,large=sb,sa
        ns,nl=len(small),len(large)
        small_res=[self._proc_resample_stroke(st) for st in small]
        large_res=[self._proc_resample_stroke(st) for st in large]
        small_norm=self._proc_normalized_resampled_strokes(small_res)
        large_norm=self._proc_normalized_resampled_strokes(large_res)
        direction_choice={}; cost=[]
        for i,a_stroke in enumerate(small_norm):
            row=[]
            for j,b_stroke in enumerate(large_norm):
                direct=sum((ax-bx)**2+(ay-by)**2 for (ax,ay),(bx,by) in zip(a_stroke,b_stroke))
                rev=list(reversed(b_stroke)); reverse=sum((ax-bx)**2+(ay-by)**2 for (ax,ay),(bx,by) in zip(a_stroke,rev))
                direction_choice[(i,j)]=reverse<direct; row.append(min(direct,reverse)/max(len(a_stroke),1))
            cost.append(row)
        assignment=self._hungarian_assignment(cost); pa=[]; pb=[]
        for i,j in enumerate(assignment):
            a=small_res[i]; b=large_res[j]
            if direction_choice[(i,j)]: b=list(reversed(b))
            pa.extend(a); pb.extend(b)
        if method=="biweight": value,angle=self._proc_biweight_fit(pa,pb)
        else: _tr,value,angle=self._proc_subset_fit(pa,pb,method=method)
        if rotation_penalty: value += self._proc_rotation_penalty(angle)
        value += 0.35*(nl-ns)
        return value,angle

    def _proc_huber_fit(self, points_a, points_b, tuning=1.345, max_iter=25):
        """Robust proper-similarity Procrustes fit using Huber IRLS.

        The Huber weights reduce the leverage of unusually large matched-point
        residuals on the fitted centring, scale and rotation. Reflection is
        never allowed. The returned distance is a Huber-loss analogue of RMS
        residual distance; for small residuals it is on the ordinary RMS scale.
        """
        if not points_a or len(points_a) != len(points_b):
            return float("inf"), 0.0
        n = len(points_a)
        weights = [1.0] * n
        angle = 0.0
        residuals = [0.0] * n
        for _ in range(max_iter):
            sw = sum(weights)
            if sw <= 1e-12:
                weights = [1.0] * n
                sw = float(n)
            acx = sum(w*p[0] for w,p in zip(weights, points_a)) / sw
            acy = sum(w*p[1] for w,p in zip(weights, points_a)) / sw
            bcx = sum(w*p[0] for w,p in zip(weights, points_b)) / sw
            bcy = sum(w*p[1] for w,p in zip(weights, points_b)) / sw
            aa = [(x-acx, y-acy) for x,y in points_a]
            bb = [(x-bcx, y-bcy) for x,y in points_b]
            an = math.sqrt(sum(w*(x*x+y*y) for w,(x,y) in zip(weights, aa)))
            bn = math.sqrt(sum(w*(x*x+y*y) for w,(x,y) in zip(weights, bb)))
            if an <= 1e-12 or bn <= 1e-12:
                return float("inf"), 0.0
            aa = [(x/an, y/an) for x,y in aa]
            bb = [(x/bn, y/bn) for x,y in bb]
            c = sum(w*(ax*bx + ay*by) for w,(ax,ay),(bx,by) in zip(weights, aa, bb))
            ss = sum(w*(ax*by - ay*bx) for w,(ax,ay),(bx,by) in zip(weights, aa, bb))
            angle = -math.atan2(ss, c)
            ca, sa = math.cos(angle), math.sin(angle)
            residuals = []
            for (ax,ay),(bx,by) in zip(aa, bb):
                rx = ca*bx - sa*by
                ry = sa*bx + ca*by
                residuals.append(math.hypot(ax-rx, ay-ry))
            ordered = sorted(residuals)
            med = ordered[n//2] if n % 2 else 0.5*(ordered[n//2-1] + ordered[n//2])
            deviations = sorted(abs(r-med) for r in residuals)
            mad = deviations[n//2] if n % 2 else 0.5*(deviations[n//2-1] + deviations[n//2])
            scale = max(1.4826 * mad, 1e-6)
            delta = tuning * scale
            new_weights = [1.0 if r <= delta else delta/max(r, 1e-12) for r in residuals]
            if max(abs(a-b) for a,b in zip(weights, new_weights)) < 1e-6:
                weights = new_weights
                break
            weights = new_weights

        # Re-express Huber loss with the final robust residual scale. This keeps
        # small residuals quadratic while large ones grow only linearly.
        ordered = sorted(residuals)
        med = ordered[n//2] if n % 2 else 0.5*(ordered[n//2-1] + ordered[n//2])
        deviations = sorted(abs(r-med) for r in residuals)
        mad = deviations[n//2] if n % 2 else 0.5*(deviations[n//2-1] + deviations[n//2])
        delta = tuning * max(1.4826 * mad, 1e-6)
        loss = 0.0
        for r in residuals:
            if r <= delta:
                loss += 0.5 * r*r
            else:
                loss += delta * (r - 0.5*delta)
        distance = math.sqrt(max(0.0, 2.0*loss/n))
        angle_deg = abs(math.degrees(angle))
        angle_deg = min(angle_deg, 360.0-angle_deg)
        return distance, angle_deg

    def _proc_pair_distance_huber_details(self, unit_a, unit_b, rotation_penalty=False):
        """Efficient stroke-aware Huber Procrustes, experimental.

        Stroke assignment and traversal-direction choice are deliberately the
        same as ordinary efficient Procrustes. Only the final global fit is
        replaced by Huber IRLS, isolating the effect of resistant fitting.
        """
        sa = unit_a.get("strokes", [])
        sb = unit_b.get("strokes", [])
        if not sa or not sb:
            return float("inf"), 0.0
        small, large = sa, sb
        if len(sa) > len(sb):
            small, large = sb, sa
        ns, nl = len(small), len(large)
        small_res = [self._proc_resample_stroke(st) for st in small]
        large_res = [self._proc_resample_stroke(st) for st in large]
        small_norm = self._proc_normalized_resampled_strokes(small_res)
        large_norm = self._proc_normalized_resampled_strokes(large_res)
        direction_choice = {}
        cost = []
        for i, a_stroke in enumerate(small_norm):
            row = []
            for j, b_stroke in enumerate(large_norm):
                direct = sum((ax-bx)**2+(ay-by)**2 for (ax,ay),(bx,by) in zip(a_stroke,b_stroke))
                rev = list(reversed(b_stroke))
                reverse = sum((ax-bx)**2+(ay-by)**2 for (ax,ay),(bx,by) in zip(a_stroke,rev))
                direction_choice[(i,j)] = reverse < direct
                row.append(min(direct, reverse)/max(len(a_stroke),1))
            cost.append(row)
        assignment = self._hungarian_assignment(cost)
        pts_small, pts_large = [], []
        for i,j in enumerate(assignment):
            a_stroke = small_res[i]
            b_stroke = large_res[j]
            if direction_choice[(i,j)]:
                b_stroke = list(reversed(b_stroke))
            pts_small.extend(a_stroke)
            pts_large.extend(b_stroke)
        value, angle_deg = self._proc_huber_fit(pts_small, pts_large)
        if rotation_penalty:
            value += self._proc_rotation_penalty(angle_deg)
        value += 0.35 * (nl-ns)
        return value, angle_deg


